window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["U7"]={"deck":"U7","slides":[{"p":1,"title":"07 르 코르뷔지에 (Le Corbusier) (표지)","terms":["Le Corbusier"],"pass1":[{"kind":"say","lines":["7단원 표지예요. 초록 띠에 '07 르 코르뷔지에 (Le Corbusier)' 라고 쓰여 있어요.","이번 단원은 건축가 한 사람, **르 코르뷔지에(Le Corbusier)** 의 이야기예요.","5단원 **바이센호프 주거단지(Weissenhof Siedlung)** 에 집을 지은 바로 그 사람이에요."]}],"pass2":[{"kind":"points","head":"7단원에서 만날 차례","items":["7-1 르 코르뷔지에와 모듈러 (p.1-5)","7-2 현대도시와 건축의 5원칙 (p.6-12)","7-3 1920년대 흰 주택 (p.13-21)","7-4 빌라 사보아 (p.22-25), 7-5 유니테 다비타시옹 (p.26-37)","7-6 노트르담 뒤 오 교회(롱샹교회) (p.38-49)","7-7 르 코르뷔지에 센터와 라 투레트 수도원 (p.50-58)"]},{"kind":"points","head":"이 단원을 꿰는 한 줄","items":["주문을 다시 외워요. 기계 시대에 건축은 어떻게 생겨야 하나? 싫어 → 새 장식 → 정리 → 없애.","**르 코르뷔지에(Le Corbusier)** 의 대답은 '집은 **살기 위한 기계**' 예요.","장식을 없앤 하얀 상자 집, 그리고 그 집을 짓는 규칙 **건축의 5원칙(Five Points of Architecture)** 이 나와요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.31,0.72,0.11],"c":[0,0.285,0.792,0.16],"r":6.6,"img":"img/U7/walk/p001_22_01.jpg","say":"제목: 07 르 코르뷔지에 (Le Corbusier). 이 단원 전체가 이 한 사람 이야기예요."}]}},{"p":2,"title":"르 코르뷔지에(Le Corbusier, 1887-1965)","terms":["Le Corbusier","국제주의 건축의 제 1세대","브루탈리즘","인본적 디자인 방식","Functionalism","Expressionism"],"pass1":[{"kind":"say","lines":["**르 코르뷔지에(Le Corbusier)** 의 소개 카드예요. 1887년에 나서 1965년에 세상을 떠났어요.","이론을 쓰고, 건물을 짓고, 도시까지 계획한 사람이에요."]},{"kind":"analogy","head":"두 맛을 한 그릇에 섞은 요리사","scene":"담백한 맛과 강렬한 맛을 한 그릇에 함께 담은 요리를 떠올려 보세요.","map":[["담백하게 쓸모를 따지는 맛","**기능주의(Functionalism)**"],["눈길을 끄는 강렬한 맛","**표현주의(Expressionism)**"],["둘을 한 그릇에 담은 요리사","**르 코르뷔지에(Le Corbusier)**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**국제주의 건축의 제 1세대**: 국제주의 건축을 처음 연 세대예요. **르 코르뷔지에(Le Corbusier)** 가 여기에 속해요.","**브루탈리즘**: 거친 콘크리트를 그대로 드러내는 건축 흐름이에요.","**인본적 디자인 방식**: 사람을 중심에 둔 디자인 태도예요. 뒤 p.5의 **모듈러(Modulor)** 와 이어져요.","**기능주의(Functionalism)** 는 4단원, **표현주의(Expressionism)** 는 6단원에서 배운 말이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실 (왼쪽 일곱 줄)","items":["현대 건축에 이론적 연구의 숨결을 불어넣은 선구자","도시 거주자들의 생활환경 개선에 큰 영향","**기능주의(Functionalism)** 와 대담하고 조소적인 **표현주의(Expressionism)** 의 결합","**국제주의 건축의 제 1세대**","당시 기능주의자들의 열망과 표현주의적인 강렬한 감각을 결합","거친 마감 콘크리트 사용을 연구한 최초의 건축가","중앙유럽, 인도, 러시아, 미국 등지에 수많은 건축물을 세운 탁월한 도시계획가"]},{"kind":"points","head":"오른쪽 세 키워드","items":["**브루탈리즘** 의 발전","**인본적 디자인 방식**","주거와 도시설계에 대한 영향력"]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**르 코르뷔지에(Le Corbusier)** 를 소개한 말로 이 쪽에 없는 것은 무엇일까요?","choices":["**국제주의 건축의 제 1세대**","거친 마감 콘크리트 사용을 연구한 최초의 건축가","장식은 죄악이라고 선언한 건축가"],"a":2,"why":"'장식은 죄악' 은 3단원 아돌프 로스 이야기예요. 앞의 두 개는 이 쪽 문장이에요."},{"kind":"check","q":"오른쪽 세 키워드에 들어 있는 것은 무엇일까요?","choices":["**브루탈리즘** 의 발전","아르누보의 확산","고딕의 부활"],"a":0,"why":"세 키워드는 **브루탈리즘** 의 발전, **인본적 디자인 방식**, 주거와 도시설계에 대한 영향력이에요."},{"kind":"english","head":"논술 답안: 르 코르뷔지에 소개","en":"르 코르뷔지에(1887-1965)는 국제주의 건축의 제 1세대로, 당시 기능주의자들의 열망과 표현주의적인 강렬한 감각을 결합하였으며 거친 마감 콘크리트 사용을 연구한 최초의 건축가이다.","ko":"생몰년, 제 1세대, 두 흐름의 결합, 콘크리트 네 가지를 넣어요.","tip":"'기능(머리) + 표현(가슴) + 거친 콘크리트(손)' 로 외워요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["파란 손글씨는 누군가의 필기예요. 슬라이드 원문이 아니라서 시험 사실로 외우지 않아요.","1번 줄 위의 작은 필기도 슬라이드 글이 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.06,0.04,0.38,0.07],"c":[0.041,0.02,0.418,0.11],"r":5.0667,"img":"img/U7/walk/p002_23_01.jpg","say":"제목: 르 코르뷔지에(Le Corbusier)."},{"b":[0.56,0.06,0.43,0.05],"c":[0.527,0.03,0.473,0.11],"r":5.7333,"img":"img/U7/walk/p002_23_02.jpg","say":"이름과 생몰년: 1887-1965."},{"b":[0.04,0.15,0.58,0.18],"c":[0.011,0.134,0.638,0.212],"r":4.0126,"img":"img/U7/walk/p002_23_03.jpg","say":"위 세 줄: 이론의 선구자, 생활환경 개선, 기능주의와 표현주의의 결합."},{"b":[0.04,0.34,0.82,0.23],"c":[0,0.324,0.902,0.262],"r":4.5903,"img":"img/U7/walk/p002_23_04.jpg","say":"아래 네 줄: 국제주의 건축의 제 1세대, 거친 마감 콘크리트, 탁월한 도시계획가."},{"b":[0.62,0.13,0.36,0.14],"c":[0.602,0.114,0.396,0.172],"r":3.0698,"img":"img/U7/walk/p002_23_05.jpg","say":"오른쪽 세 키워드: 브루탈리즘의 발전, 인본적 디자인 방식, 주거와 도시설계."},{"b":[0.23,0.58,0.76,0.41],"c":[0.164,0.549,0.836,0.451],"r":2.4715,"img":"img/U7/walk/p002_23_06.jpg","say":"아래 그림 두 장: 안경 쓴 얼굴의 초상화와 둥근 안경에 파이프를 문 사진. 캡션은 없어요."}]}},{"p":3,"title":"르 코르뷔지에의 말, 에스프리 누보(1920), 건축을 향하여(1923)","terms":["Le Corbusier","L'Esprit Nouveau","오장팡","Vers une Architecture"],"pass1":[{"kind":"say","lines":["맨 위에 **르 코르뷔지에(Le Corbusier)** 의 말 두 개가 있어요.","'건축가는 시대의 생각을 남기는 사람', '삶 자체가 하나의 건축이다.'","가운데는 그가 낸 잡지와 책, 맨 아래는 그림 두 장이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**에스프리 누보(L'Esprit Nouveau)**: '새로운 정신' 이라는 뜻의 잡지 이름이에요.","**오장팡**: **르 코르뷔지에(Le Corbusier)** 와 함께 이 잡지를 창간한 사람이에요.","**건축을 향하여(Vers une Architecture)**: 1923년에 낸 건축 선언의 책이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**에스프리 누보(L'Esprit Nouveau)**, 1920: 1920년 1월 **르 코르뷔지에(Le Corbusier)**, **오장팡** 등이 함께 참여해 창간했어요.","미술, 문학, 과학, 건축 등에 관한 새로운 사상과 이론을 담았어요.","**건축을 향하여(Vers une Architecture)**, 1923: 건축적 성찰을 통해 세상에 대한 분명한 선언을 했어요.","자신의 건축작품에 담은 개념을 명료하게 설명하고 있어요.","젊은 날의 진취적이고 개혁적인 생각을 고스란히 담고 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"잡지 **에스프리 누보(L'Esprit Nouveau)** 를 **르 코르뷔지에(Le Corbusier)** 와 함께 창간한 사람은 누구일까요?","choices":["**오장팡**","피에르 잔느레","아인슈타인"],"a":0,"why":"1920년 1월 **오장팡** 등과 함께 창간했어요."},{"kind":"check","q":"책 **건축을 향하여(Vers une Architecture)** 가 나온 해는 언제일까요?","choices":["1920년","1923년","1925년"],"a":1,"why":"1923년이에요. 1920년은 잡지 **에스프리 누보(L'Esprit Nouveau)**, 1925년은 다음 쪽 전시관이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["잡지가 먼저(1920), 책이 나중(1923)이에요.","잡지 이름은 '에스프리 누보', 다음 쪽 전시관은 '에스쁘리 누보' 로 슬라이드 표기가 달라요.","파란 손글씨는 누군가의 필기예요. 슬라이드 원문이 아니라서 시험 사실로 외우지 않아요."]},{"kind":"english","head":"논술 답안: 잡지와 책","en":"르 코르뷔지에는 1920년 1월 오장팡 등과 함께 미술, 문학, 과학, 건축에 관한 새로운 사상과 이론을 담은 잡지 에스프리 누보를 창간하였고, 1923년 건축을 향하여를 펴냈다.","ko":"연도 두 개(1920, 1923)와 함께한 사람(오장팡)을 꼭 넣어요.","tip":"'이공(20)에 새 정신, 이삼(23)에 선언' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.06,0.73,0.1],"c":[0.0335,0.0289,0.803,0.1622],"r":6.6009,"img":"img/U7/walk/p003_22_01.jpg","say":"맨 위: 르 코르뷔지에의 말 두 개. '건축가는 시대의 생각을 남기는 사람', '삶 자체가 하나의 건축이다.'"},{"b":[0.05,0.2,0.42,0.31],"c":[0.029,0.184,0.462,0.342],"r":1.8012,"img":"img/U7/walk/p003_22_02.jpg","say":"왼쪽: 잡지 표지 L'ESPRIT NOUVEAU 와 설명글. 1920년 1월, 오장팡 등과 창간."},{"b":[0.49,0.2,0.36,0.31],"c":[0.472,0.184,0.396,0.342],"r":1.5439,"img":"img/U7/walk/p003_22_03.jpg","say":"오른쪽: 책 VERS UNE ARCHITECTURE 와 설명글. 1923년, 분명한 선언."},{"b":[0.05,0.52,0.88,0.46],"c":[0.006,0.494,0.968,0.506],"r":2.5507,"img":"img/U7/walk/p003_22_04.jpg","say":"아래 그림 두 장: 굵은 검은 선과 넓은 색면으로 그린 그림이에요. 그림 제목과 연도는 슬라이드에 없어요."}]}},{"p":4,"title":"에스쁘리 누보 전시관, 장식 미술 전시회, 파리, 1925","terms":["에스쁘리 누보 전시관","모듈러 스토리지 유닛","벤트우드 체어","순수주의","Le Corbusier"],"pass1":[{"kind":"analogy","head":"아파트 모델하우스","scene":"새 아파트를 팔기 전에 예쁘게 꾸며 보여 주는 모델하우스를 떠올려 보세요.","map":[["꾸며 놓은 견본 집","**에스쁘리 누보 전시관** 의 모델 아파트"],["새로 들여놓은 가구","**모듈러 스토리지 유닛**, **벤트우드 체어**"],["벽에 건 그림","**순수주의** 스타일의 그림"]]},{"kind":"say","lines":["1925년 파리 장식 미술 전시회에 **르 코르뷔지에(Le Corbusier)** 가 이 전시관을 지었어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**에스쁘리 누보 전시관**: 1925년 파리 장식 미술 전시회의 전시관이에요.","**모듈러 스토리지 유닛**: 같은 치수 단위로 짜 맞춘 수납 가구예요.","**벤트우드 체어**: 나무를 구부려 만든 토네트의 의자예요.","**순수주의**: **르 코르뷔지에(Le Corbusier)** 가 주장한 그림 스타일이에요. 단순한 모양으로 사물을 그려요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["전시 공간 안에서 그의 이론들에 따라 디자인된 모델 아파트의 인테리어를 보여 줬어요.","**모듈러 스토리지 유닛** 과 단순한 암 체어, 토네트의 **벤트우드 체어** 들을 놓았어요.","그 시대의 장식적인 가구들이 가지고 있던 표준들과는 차별성이 있는 가구들을 제안했어요.","벽에 걸린 예술 작품들은 그가 주장하던 **순수주의** 스타일의 전형이에요.","캡션: 르 꼬르뷔제, **에스쁘리 누보 전시관**, 장식 미술 전시회, 파리, 1925."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**에스쁘리 누보 전시관** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["파리, 1925","파리, 1920","슈투트가르트, 1927"],"a":0,"why":"장식 미술 전시회, 파리, 1925년이에요. 1920년은 잡지, 슈투트가르트 1927년은 5단원 바이센호프예요."},{"kind":"check","q":"**에스쁘리 누보 전시관** 벽에 걸린 그림은 어떤 스타일의 전형일까요?","choices":["**순수주의**","**표현주의(Expressionism)**","아르누보"],"a":0,"why":"**르 코르뷔지에(Le Corbusier)** 가 주장한 **순수주의** 스타일의 전형이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["같은 사람인데 이 쪽 캡션은 '르 꼬르뷔제', 본문은 '르 꼬르뷔지에' 로 적혀 있어요.","잡지는 '에스프리 누보'(1920), 전시관은 '에스쁘리 누보'(1925)예요."]},{"kind":"english","head":"논술 답안: 에스쁘리 누보 전시관","en":"르 코르뷔지에는 1925년 파리 장식 미술 전시회의 에스쁘리 누보 전시관에서 모듈러 스토리지 유닛, 단순한 암 체어, 토네트의 벤트우드 체어로 장식적인 가구와 차별된 모델 아파트를 보여 주었다.","ko":"전시회 이름, 도시, 연도, 가구 세 가지를 넣어요.","tip":"가구 세 개는 '수납, 팔걸이, 구부린 나무' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.43,0.46],"c":[0.0285,0.037,0.473,0.506],"r":1.2464,"img":"img/U7/walk/p004_22_01.jpg","say":"왼쪽 사진: 천장이 2층 높이로 트인 거실이에요. 위층 난간, 가죽 안락의자, 칸칸이 짠 수납장, 가는 곡선 의자가 보여요."},{"b":[0.06,0.53,0.42,0.07],"c":[0.039,0.51,0.462,0.11],"r":5.6,"img":"img/U7/walk/p004_22_02.jpg","say":"캡션: 르 꼬르뷔제, 에스쁘리 누보 전시관, 장식 미술 전시회, 파리, 1925."},{"b":[0.52,0.15,0.34,0.37],"c":[0.503,0.1315,0.374,0.407],"r":1.2252,"img":"img/U7/walk/p004_22_03.jpg","say":"오른쪽 액자: 기타, 병, 컵 같은 물건을 단순한 모양으로 그린 그림 두 장이에요."},{"b":[0.04,0.63,0.92,0.1],"c":[0.0,0.5778,1,0.2045],"r":6.52,"img":"img/U7/walk/p004_22_04.jpg","say":"첫 줄: 이론에 따라 디자인한 모델 아파트의 인테리어."},{"b":[0.04,0.75,0.92,0.12],"c":[0.0,0.7078,1,0.2045],"r":6.52,"img":"img/U7/walk/p004_22_05.jpg","say":"둘째 줄: 모듈러 스토리지 유닛, 암 체어, 토네트의 벤트우드 체어. 장식적인 가구와 다른 가구."},{"b":[0.04,0.88,0.92,0.07],"c":[0.0,0.7955,1,0.2045],"r":6.52,"img":"img/U7/walk/p004_22_06.jpg","say":"셋째 줄: 벽의 예술 작품은 순수주의 스타일의 전형."}]}},{"p":5,"title":"모듈러, 모듈러를 찾아서, 아인슈타인과의 만남","terms":["Modulor","규준선","아인슈타인과의 만남","인본적 디자인 방식","Le Corbusier"],"pass1":[{"kind":"analogy","head":"사람 몸으로 눈금을 매긴 자","scene":"보통 자는 cm 눈금이지만, 이 자는 사람 몸 치수에서 눈금을 뽑았어요.","map":[["자의 눈금","**모듈러(Modulor)** 의 숫자들"],["눈금의 기준","손을 번쩍 든 사람 그림"],["이 자로 집을 재기","건물의 비례를 맞추기"]]},{"kind":"say","lines":["그래서 p.2의 **인본적 디자인 방식**, 즉 사람을 중심에 둔 디자인과 이어져요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**모듈러(Modulor)**: 사람 몸 치수에서 뽑은 **르 코르뷔지에(Le Corbusier)** 의 비례 체계예요.","**규준선**: 완성된 건물의 비례를 검증하는 기준선이에요.","**아인슈타인과의 만남**: 프린스턴에서 아인슈타인에게 **모듈러(Modulor)** 를 설명한 일화예요."]},{"kind":"points","head":"모듈러를 찾아서 (가운데 글)","items":["완성된 건물의 비례를 검증하는 '**규준선**' 이 설계 단계부터 미리 적용되면 편리하겠다고 생각했어요.","그래서 우선 조각과 회화에서부터 비례를 찾는 연구를 시작했어요.","그 생각이 결국 **모듈러(Modulor)** 를 발명해 내는 계기로 발전했어요.","그의 정물화에서 찾아볼 수 있는 **규준선** 은 편안한 비례로 균형감을 줘요."]},{"kind":"points","head":"아인슈타인과의 만남 (오른쪽 글)","items":["프린스턴에서 아인슈타인 교수와 **모듈러(Modulor)** 에 대해 꽤 오랫동안 이야기했어요.","그날 밤 아인슈타인이 편지를 보내와 **모듈러(Modulor)** 에 대해 설명했어요.","편지: '악을 어렵게 하고 선을 쉽게 만들어내는 것이 바로 비례라는 척도입니다.'","출처: 르 코르뷔지에의 회상 '모듈러' 1950."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**규준선** 의 뜻으로 옳은 것은 무엇일까요?","choices":["완성된 건물의 비례를 검증하는 기준선","건물 아래를 비우는 기둥","도시의 교통망"],"a":0,"why":"**규준선** 을 설계 단계부터 미리 쓰려는 생각이 **모듈러(Modulor)** 발명의 계기가 됐어요."},{"kind":"check","q":"**르 코르뷔지에(Le Corbusier)** 가 아인슈타인과 **모듈러(Modulor)** 를 이야기한 곳은 어디일까요?","choices":["프린스턴","파리","취리히"],"a":0,"why":"**아인슈타인과의 만남** 은 프린스턴이에요. 그날 밤 편지가 왔어요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["그림 위 파란 손글씨 두 개는 필기예요. 슬라이드 글이 아니에요.","출처의 1950은 회상록 '모듈러' 의 연도예요. 모듈러를 만든 해라고 쓰지 않아요."]},{"kind":"english","head":"논술 답안: 모듈러","en":"르 코르뷔지에는 완성된 건물의 비례를 검증하는 규준선을 설계 단계부터 미리 적용하려는 생각에서 조각과 회화의 비례를 연구하였고, 이것이 모듈러를 발명하는 계기가 되었다.","ko":"규준선 → 비례 연구 → 모듈러 순서로 써요.","tip":"'검증하던 선을 처음부터 쓰자' 가 출발점이에요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.04,0.11,0.06],"c":[0.005,0.015,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p005_23_01.jpg","say":"제목: 모듈러."},{"b":[0.03,0.2,0.33,0.63],"c":[0.0135,0.1685,0.363,0.693],"r":0.6984,"img":"img/U7/walk/p005_23_02.jpg","say":"모듈러 그림: 손을 든 사람 옆에 1,829, 1,397, 1,130, 863, 698 같은 숫자 눈금이 있어요."},{"b":[0.37,0.31,0.29,0.37],"c":[0.3555,0.2915,0.319,0.407],"r":1.045,"img":"img/U7/walk/p005_23_03.jpg","say":"모듈러를 찾아서: 규준선을 설계 단계부터 쓰려던 생각이 모듈러 발명의 계기."},{"b":[0.66,0.03,0.33,0.12],"c":[0.637,0.014,0.363,0.152],"r":3.1842,"img":"img/U7/walk/p005_23_04.jpg","say":"아인슈타인과의 만남: 제목."},{"b":[0.67,0.18,0.31,0.51],"c":[0.6545,0.1545,0.341,0.561],"r":0.8105,"img":"img/U7/walk/p005_23_05.jpg","say":"프린스턴에서 아인슈타인과 모듈러를 이야기한 일화예요."},{"b":[0.67,0.71,0.31,0.25],"c":[0.6545,0.694,0.341,0.282],"r":1.6123,"img":"img/U7/walk/p005_23_06.jpg","say":"그날 밤의 편지 문장과 출처: 르 코르뷔지에의 회상 '모듈러' 1950."}]}},{"p":6,"title":"르 코르뷔지에 건축의 특징, 인구 300만의 현대도시(1922)","terms":["Le Corbusier","단위주거","Une Ville Contemporaine","십자형의 사무소 타워","르 꼬르뷔지에의 이상적 도시"],"pass1":[{"kind":"analogy","head":"레고 블록 한 개에서 도시까지","scene":"블록 한 개를 잘 만들면 그걸 쌓아서 마을도, 도시도 만들 수 있어요.","map":[["블록 한 개","**단위주거**"],["블록을 쌓은 큰 마을","도시"],["블록부터 잘 만들기","단위주거에서 출발하여 도시를 설계"]]},{"kind":"say","lines":["그렇게 그린 도시가 1922년 **인구 300만의 현대도시(Une Ville Contemporaine)** 예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**단위주거**: 도시를 이루는 집 한 칸 단위예요.","**인구 300만의 현대도시(Une Ville Contemporaine)**: 1922년 도시계획 이론이에요.","**십자형의 사무소 타워**: 계획안 한가운데 늘어선 십자 모양 고층 사무소예요.","**르 꼬르뷔지에의 이상적 도시**: 과거 도시 구조를 버리고 새로 짠 도시예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**르 코르뷔지에(Le Corbusier)** 건축의 특징: 도시라는 맥락 안에서 **단위주거** 를 설계해요.","그리고 **단위주거** 에서 출발하여 도시를 설계해요.","**인구 300만의 현대도시(Une Ville Contemporaine)**: 1922년 도시계획 이론이에요.","도심으로의 인구 집중에 대비하여 도시 지역을 적극적으로 개발해요.","고층건물을 제시하고, 교통문제를 고려했어요."]},{"kind":"points","head":"**르 꼬르뷔지에의 이상적 도시**","items":["과거의 도시공간구조를 거부해요.","주거, 일터, 여가공간, 교통망으로 구성되는 도시를 제안해요.","도심으로의 인구 집중에 대비하여 도시지역을 적극적으로 개발해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"1922년 **르 코르뷔지에(Le Corbusier)** 의 도시계획 이론은 무엇일까요?","choices":["**인구 300만의 현대도시(Une Ville Contemporaine)**","전원도시","**에스프리 누보(L'Esprit Nouveau)**"],"a":0,"why":"**인구 300만의 현대도시(Une Ville Contemporaine)** 예요. 에스프리 누보는 1920년 잡지예요."},{"kind":"check","q":"**르 꼬르뷔지에의 이상적 도시** 를 이루는 네 가지에 들지 않는 것은 무엇일까요?","choices":["주거","교통망","성벽"],"a":2,"why":"주거, 일터, 여가공간, 교통망이에요. 과거의 도시공간구조는 거부했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이 쪽에는 '르 코르뷔지에' 와 '르 꼬르뷔지에' 가 섞여 있어요. 같은 사람이에요.","그림 속 이름 '빌 콘템포레느' 는 Une Ville Contemporaine 를 읽은 말이에요."]},{"kind":"english","head":"논술 답안: 단위주거와 현대도시","en":"르 코르뷔지에는 도시라는 맥락 안에서 단위주거를 설계하고 단위주거에서 출발하여 도시를 설계하였으며, 1922년 인구 300만의 현대도시에서 고층건물을 제시하고 교통문제를 고려하였다.","ko":"특징 두 줄과 현대도시의 연도, 고층건물, 교통문제를 넣어요.","tip":"'이이(22), 2와 2가 십자(+)로 만나는 타워 도시' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.45,0.16],"c":[0.0275,0.044,0.495,0.192],"r":3.4375,"img":"img/U7/walk/p006_23_01.jpg","say":"르 코르뷔지에 건축의 특징 두 줄: 단위주거 → 도시."},{"b":[0.05,0.3,0.48,0.34],"c":[0.026,0.283,0.528,0.374],"r":1.8824,"img":"img/U7/walk/p006_23_02.jpg","say":"인구 300만의 현대도시(Une Ville Contemporaine): 1922년, 인구 집중 대비, 고층건물, 교통문제."},{"b":[0.05,0.69,0.48,0.29],"c":[0.026,0.674,0.528,0.322],"r":2.1863,"img":"img/U7/walk/p006_23_03.jpg","say":"르 꼬르뷔지에의 이상적 도시: 과거 구조 거부, 주거, 일터, 여가공간, 교통망."},{"b":[0.82,0.25,0.15,0.07],"c":[0.795,0.23,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p006_23_04.jpg","say":"그림 속 글자: 현대도시 빌 콘템포레느(1922)."},{"b":[0.6,0.4,0.38,0.3],"c":[0.581,0.384,0.418,0.332],"r":1.6787,"img":"img/U7/walk/p006_23_05.jpg","say":"가운데 십자 모양 건물들. 그림 속 글자: 십자형의 사무소 타워."},{"b":[0.63,0.945,0.32,0.04],"c":[0.614,0.89,0.352,0.11],"r":4.2667,"img":"img/U7/walk/p006_23_06.jpg","say":"캡션: 르 코르뷔지에, 현대도시 계획안, 1922."}]}},{"p":7,"title":"도시 조직 비교 스케치 (글 없음)","terms":["Une Ville Contemporaine","단위주거"],"pass1":[{"kind":"say","lines":["글 없이 스케치 한 장만 있는 쪽이에요.","앞 쪽 **인구 300만의 현대도시(Une Ville Contemporaine)** 다음에 나와요.","땅 위에 건물이 어떻게 놓이는지 위에서 내려다본 그림이에요."]}],"pass2":[{"kind":"points","head":"그림에서 보이는 것","items":["왼쪽: 길로 나뉜 블록마다 빗금 친 네모 건물이 하나씩 놓여 있어요.","가운데: 아주 작은 네모 칸이 빈틈없이 촘촘히 깔려 있어요.","오른쪽: 넓은 네모 땅 안에 길쭉한 건물 하나와 구불구불한 녹지 모양이 있어요.","오른쪽 아래에 축척 막대가 있어요. 100m, 200, 300 이라고 적혀 있어요."]},{"kind":"points","head":"이 쪽을 볼 때 기억할 것","items":["슬라이드에 그림 설명 글이 없어요. 그래서 어느 그림이 어느 도시인지는 정하지 않아요.","앞 쪽의 **단위주거** 와 도시 이야기를 떠올리며 '건물을 땅에 놓는 방식이 이렇게 다르다' 정도로 봐요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["파란 손글씨는 누군가의 필기예요. 슬라이드 원문이 아니라서 시험 사실로 외우지 않아요.","그림 옆 필기 세 군데도 슬라이드 원문이 아니에요. 이 쪽에서 외울 슬라이드 글은 축척 숫자뿐이에요."]}],"walk":{"head":null,"parts":[{"b":[0.04,0.08,0.4,0.78],"c":[0.02,0.041,0.44,0.858],"r":0.6838,"img":"img/U7/walk/p007_22_01.jpg","say":"왼쪽 그림: 블록마다 빗금 친 네모 건물이 하나씩 있어요."},{"b":[0.27,0.33,0.4,0.53],"c":[0.25,0.3035,0.44,0.583],"r":1.0063,"img":"img/U7/walk/p007_22_02.jpg","say":"가운데 그림: 작은 네모 칸이 촘촘히 깔린 땅이에요."},{"b":[0.7,0.32,0.22,0.37],"c":[0.688,0.3015,0.244,0.407],"r":0.7993,"img":"img/U7/walk/p007_22_03.jpg","say":"오른쪽 그림: 넓은 땅에 길쭉한 건물 하나와 녹지 모양."},{"b":[0.68,0.77,0.3,0.07],"c":[0.665,0.75,0.33,0.11],"r":4.0,"img":"img/U7/walk/p007_22_04.jpg","say":"축척 막대: 100m, 200, 300."}]}},{"p":8,"title":"르 코르뷔지에의 주거개념: 현대도시에서의 주택","terms":["Une Ville Contemporaine","단위주거","복층","옥외공간","Flat Roof","Roof Garden","Pilotis","십자형의 사무소 타워"],"pass1":[{"kind":"say","lines":["이번에는 **인구 300만의 현대도시(Une Ville Contemporaine)** 안에 들어갈 집 이야기예요.","집 한 칸이 넓고, 위아래 두 층을 쓰고, 평평한 지붕 위에는 정원이 있어요.","건물 아래는 기둥으로 들어 올려 비워요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**복층**: 한 집이 위아래 두 층을 함께 쓰는 구성이에요.","**옥외공간**: 집에 딸린 바깥 공간이에요.","**평지붕(Flat Roof)**: 경사 없이 평평한 지붕이에요.","**옥상정원(Roof Garden)**: **평지붕(Flat Roof)** 위에 만든 정원이에요.","**필로티(Pilotis)**: 건물을 기둥으로 들어 올려 아래를 비우는 방식이에요."]},{"kind":"points","head":"현대도시에서의 주택 (네 줄 그대로)","items":["**복층** 의 생활공간과 개인적인 **옥외공간** 제공","넓은 면적의 **단위주거**","발코니와 **옥상정원(Roof Garden)** 을 든 **평지붕(Flat Roof)** 의 주택","건물 하부에 **필로티(Pilotis)** 사용"]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"현대도시에서의 주택 설명으로 이 쪽에 없는 것은 무엇일까요?","choices":["**복층** 의 생활공간","건물 하부에 **필로티(Pilotis)** 사용","뾰족한 경사 지붕"],"a":2,"why":"발코니와 **옥상정원(Roof Garden)** 을 든 **평지붕(Flat Roof)** 의 주택이에요. 경사 지붕이 아니에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["'발코니와 옥상정원을 든' 의 '든' 은 슬라이드 원문 그대로예요.","파란 손글씨는 누군가의 필기예요. 슬라이드 원문이 아니라서 시험 사실로 외우지 않아요."]},{"kind":"english","head":"논술 답안: 현대도시에서의 주택","en":"현대도시에서의 주택은 복층의 생활공간과 개인적인 옥외공간을 제공하는 넓은 면적의 단위주거로, 발코니와 옥상정원을 든 평지붕의 주택이며 건물 하부에 필로티를 사용하였다.","ko":"네 줄을 한 문장으로 이었어요.","tip":"'두 층, 바깥, 넓게, 지붕정원, 기둥' 다섯 낱말로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.05,0.35,0.06],"c":[0.0225,0.025,0.385,0.11],"r":4.6667,"img":"img/U7/walk/p008_22_01.jpg","say":"제목: 르 코르뷔지에의 주거개념."},{"b":[0.04,0.17,0.49,0.31],"c":[0.0155,0.154,0.539,0.342],"r":2.1014,"img":"img/U7/walk/p008_22_02.jpg","say":"현대도시에서의 주택 네 줄: 복층, 옥외공간, 넓은 단위주거, 옥상정원과 평지붕, 필로티."},{"b":[0.52,0.08,0.45,0.54],"c":[0.4975,0.053,0.495,0.594],"r":1.1111,"img":"img/U7/walk/p008_22_03.jpg","say":"모형 사진: 십자 모양 고층 타워들이 줄지어 서 있어요. p.6의 십자형의 사무소 타워와 같은 모양이에요."},{"b":[0.01,0.65,0.96,0.24],"c":[0,0.634,1,0.272],"r":4.902,"img":"img/U7/walk/p008_22_04.jpg","say":"아래 긴 투시도: 고층 타워들 앞에 낮은 건물들과 넓은 길이 펼쳐져 있어요. 캡션은 없어요."}]}},{"p":9,"title":"'살기 위한 기계' 로서의 주택, 건축의 5원칙","terms":["살기 위한 기계","Five Points of Architecture","뼈대와 벽의 기능적 분리","Pilotis","Roof Garden","Open Plan","Freed Facade","철근 콘크리트","Le Corbusier"],"pass1":[{"kind":"analogy","head":"기계처럼 잘 돌아가는 집","scene":"자동차는 어느 나라에서 타도 똑같이 잘 달려요. 집도 그렇게 만들자는 생각이에요.","map":[["군더더기 없이 잘 돌아감","효율적인 기능"],["어느 나라에서나 통함","지역에 관계없는 보편성"],["이런 집","**살기 위한 기계**"]]},{"kind":"say","lines":["그런 집을 짓는 규칙 다섯 가지가 **건축의 5원칙(Five Points of Architecture)** 이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**뼈대와 벽의 기능적 분리**: 짐은 기둥 뼈대가 지고, 벽은 칸막이만 해요.","**필로티(Pilotis)**: 건물을 기둥으로 들어 올려 아래를 비워요.","**옥상정원(Roof Garden)**: 평평한 지붕 위에 정원을 만들어요.","**자유로운 평면(Open Plan)**: 벽이 짐을 안 지니 방 배치를 마음대로 해요.","**자유로운 입면(Freed Facade)**: 겉면의 창과 벽을 마음대로 짜요.","**철근 콘크리트**: 철근을 넣어 굳힌 콘크리트예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["'**살기 위한 기계**' 로서의 주택이에요.","인간의 기본욕구를 만족시키는 합리적인 설계 제안이에요. 효율적인 기능과 지역에 관계없는 보편성을 추구해요.","**건축의 5원칙(Five Points of Architecture)**: ① **뼈대와 벽의 기능적 분리** ② **필로티(Pilotis)** ③ **옥상정원(Roof Garden)**","④ **자유로운 평면(Open Plan)** ⑤ **자유로운 입면(Freed Facade)**","**철근 콘크리트** 라는 새로운 재료의 이용과 그 구조적 미학적 가능성을 완전히 활용한 형태를 추구했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"이 쪽 한국어 **건축의 5원칙(Five Points of Architecture)** 목록에 들어 있지 않은 것은 무엇일까요?","choices":["**뼈대와 벽의 기능적 분리**","**수평띠창(Ribbon Windows)**","**자유로운 입면(Freed Facade)**"],"a":1,"why":"한국어 목록에는 **수평띠창(Ribbon Windows)** 이 없어요. 영어 목록(p.12)에만 있어요."},{"kind":"check","q":"5원칙의 형태를 가능하게 한 새로운 재료는 무엇일까요?","choices":["벽돌","**철근 콘크리트**","목재"],"a":1,"why":"**철근 콘크리트** 라는 새로운 재료의 구조적 미학적 가능성을 완전히 활용했어요."},{"kind":"english","head":"논술 답안: 살기 위한 기계와 5원칙","en":"르 코르뷔지에는 주택을 '살기 위한 기계'로 보고 효율적인 기능과 지역에 관계없는 보편성을 추구하였으며, 뼈대와 벽의 기능적 분리, 필로티, 옥상정원, 자유로운 평면, 자유로운 입면의 5원칙을 제시하였다.","ko":"한국어 목록 다섯 개를 이 쪽 순서대로 써요.","tip":"'뼈, 다리, 정원, 바닥, 얼굴' 로 외워요. 다리는 필로티, 바닥은 평면, 얼굴은 입면이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["다음 p.12 영어 목록과 항목, 순서가 달라요. 두 목록을 모두 알아 둬요.","5원칙 앞 동그라미 숫자와 스케치 아래 파란 글씨는 필기예요. 순서는 슬라이드의 줄 순서를 따라요."]}],"walk":{"head":null,"parts":[{"b":[0.06,0.08,0.33,0.06],"c":[0.0435,0.055,0.363,0.11],"r":4.4,"img":"img/U7/walk/p009_22_01.jpg","say":"'살기위한 기계' 로서의 주택. 이 쪽은 띄어쓰기 없이 적혀 있어요."},{"b":[0.06,0.15,0.9,0.09],"c":[0.01,0.095,0.99,0.2],"r":6.6,"img":"img/U7/walk/p009_22_02.jpg","say":"인간의 기본욕구를 만족시키는 합리적인 설계: 효율적인 기능, 지역에 관계없는 보편성."},{"b":[0.08,0.27,0.38,0.34],"c":[0.061,0.253,0.418,0.374],"r":1.4902,"img":"img/U7/walk/p009_22_03.jpg","say":"건축의 5원칙 다섯 줄: 뼈대와 벽의 기능적 분리, 필로티, 옥상정원, 자유로운 평면, 자유로운 입면."},{"b":[0.04,0.71,0.55,0.11],"c":[0.0125,0.694,0.605,0.142],"r":5.6808,"img":"img/U7/walk/p009_22_04.jpg","say":"철근 콘크리트라는 새로운 재료의 구조적 미학적 가능성."},{"b":[0.59,0.25,0.3,0.71],"c":[0.575,0.2145,0.33,0.781],"r":0.5634,"img":"img/U7/walk/p009_22_05.jpg","say":"오른쪽 스케치 두 줄: 초록 선이 원칙과 스케치를 이어요. 한 줄은 점 같은 기둥, 기둥 위에 들린 집, 길게 이어진 창이고 다른 줄은 두꺼운 벽, 뾰족 지붕 집, 작은 창이에요."}]}},{"p":10,"title":"도미노 시스템(Dom-ino)","terms":["Dom-ino","융통성","단위주거","철근 콘크리트"],"pass1":[{"kind":"say","lines":["**도미노 시스템(Dom-ino)** 은 집의 뼈대만 먼저 만든 거예요.","기둥과 바닥판, 지붕만 있고 벽이 없어요. 오른쪽 그림이 바로 그 뼈대예요."]},{"kind":"analogy","head":"칸막이 없는 빈 책장","scene":"기둥과 선반만 있는 빈 책장을 떠올려 보세요. 칸막이는 나중에 원하는 곳에 끼우면 돼요.","map":[["기둥과 선반만 있는 책장","**도미노 시스템(Dom-ino)**"],["칸막이를 마음대로 끼우기","**융통성**"],["같은 책장을 여러 개 만들기","부재의 표준화"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**도미노 시스템(Dom-ino)**: 기둥과 바닥판만으로 짠 집의 뼈대예요.","**융통성**: 실내구획과 외벽 위치를 마음대로 바꿀 수 있는 여유예요.","부재: 건물을 이루는 부품이에요. 바닥슬래브는 바닥이 되는 판이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["Domus 집 + Innovation 혁신 = dom-ino 도미노(돔 이노)","자동차 뼈대 구조에서 아이디어를 얻었어요.","기둥골조 여섯 개, 바닥슬래브 두 개, 지붕으로 구성돼요.","실내구획과 외벽의 위치에 **융통성** 을 부여해요.","모든 주거계획의 원형이 됐어요.","부재의 표준화, 외부 및 내부 공간구성의 다양화."]},{"kind":"points","head":"왼쪽 아래 인용문","items":["'새로운 건축이 필요한 시대, 도시는 공사기간을 빠르게 단축하면서도 많은 인원을 수용할 수 있는 공공건축을 필요로 하게 되었다.'","빨리, 많이 지어야 하니 같은 뼈대를 되풀이하는 **도미노 시스템(Dom-ino)** 이 필요했다고 이어 읽어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**도미노 시스템(Dom-ino)** 의 구성으로 옳은 것은 무엇일까요?","choices":["기둥골조 여섯 개, 바닥슬래브 두 개, 지붕","기둥골조 네 개, 바닥슬래브 세 개, 지붕","내력벽 네 장과 지붕"],"a":0,"why":"기둥골조 여섯 개, 바닥슬래브 두 개, 지붕이에요. '육이(62)에 뚜껑' 으로 외워요."},{"kind":"check","q":"dom-ino 라는 이름은 어떤 두 말을 합친 것일까요?","choices":["Domus(집) + Innovation(혁신)","Domino(게임) + Nouveau(새로운)","Dome(둥근 지붕) + Inno(안)"],"a":0,"why":"Domus 집 + Innovation 혁신 = dom-ino 예요."},{"kind":"check","q":"**도미노 시스템(Dom-ino)** 은 어디에서 아이디어를 얻었을까요?","choices":["자동차 뼈대 구조","고딕 성당의 벽","일본 목조 주택"],"a":0,"why":"자동차 뼈대 구조에서 아이디어를 얻었어요."},{"kind":"english","head":"논술 답안: 도미노 시스템","en":"도미노 시스템(Domus 집 + Innovation 혁신)은 자동차 뼈대 구조에서 아이디어를 얻어 기둥골조 여섯 개, 바닥슬래브 두 개, 지붕으로 구성되며, 실내구획과 외벽의 위치에 융통성을 부여해 모든 주거계획의 원형이 되었다.","ko":"어원, 아이디어, 구성 숫자, 융통성, 원형 다섯 가지를 넣어요.","tip":"숫자 6과 2를 틀리지 않게 조심해요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.05,0.19,0.06],"c":[0.058,0.025,0.214,0.11],"r":2.5939,"img":"img/U7/walk/p010_23_01.jpg","say":"제목: 도미노 시스템."},{"b":[0.06,0.18,0.62,0.06],"c":[0.029,0.1411,0.682,0.1378],"r":6.5989,"img":"img/U7/walk/p010_23_02.jpg","say":"이름 풀이: Domus 집 + Innovation 혁신 = dom-ino 도미노(돔 이노)."},{"b":[0.08,0.25,0.56,0.29],"c":[0.052,0.234,0.616,0.322],"r":2.5507,"img":"img/U7/walk/p010_23_03.jpg","say":"다섯 줄: 자동차 뼈대, 기둥골조 여섯 개와 바닥슬래브 두 개, 융통성, 원형, 표준화와 다양화."},{"b":[0.04,0.64,0.45,0.22],"c":[0.0175,0.624,0.495,0.252],"r":2.619,"img":"img/U7/walk/p010_23_04.jpg","say":"인용문: 공사기간을 단축하면서 많은 인원을 수용할 공공건축이 필요."},{"b":[0.5,0.6,0.48,0.39],"c":[0.472,0.571,0.528,0.429],"r":1.641,"img":"img/U7/walk/p010_23_05.jpg","say":"뼈대 그림: 가는 기둥, 바닥판, 지붕판, 계단만 있고 벽이 하나도 없어요."}]}},{"p":11,"title":"시트로앵 하우스(1924)와 그 개념","terms":["시트로앵 하우스","Dom-ino","대량생산","복층","Pilotis","살기 위한 기계","단위주거","Une Ville Contemporaine"],"pass1":[{"kind":"say","lines":["**시트로앵 하우스** 는 1924년 집이에요.","앞 쪽 **도미노 시스템(Dom-ino)** 뼈대로 실제 집을 지어 보인 모델이에요.","공장에서 물건 찍어 내듯 많이 만들 수 있게, 즉 **대량생산** 을 생각한 집이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**시트로앵 하우스**: **도미노 시스템(Dom-ino)** 주택의 실제 모델로 제시된 1924년 주택이에요.","**대량생산**: 같은 물건을 공장에서 한꺼번에 많이 만드는 것이에요.","**복층**: 한 집이 위아래 두 층을 함께 쓰는 구성이에요."]},{"kind":"points","head":"**시트로앵 하우스** (1924)","items":["단순한 상자모양, 옥상지붕, 상하층으로 분리된 거실","넓은 전면창, **필로티(Pilotis)**, **복층** 으로 구성","**도미노 시스템(Dom-ino)** 주택의 실제 모델","**대량생산** 의 개념에 따라 제시된 주택","1920, 30년대 꼬르뷔지에의 주거계획을 위한 기본형식"]},{"kind":"points","head":"**시트로앵 하우스** 의 개념","items":["이상적 공동사회로서의 집합주택과 '**살기 위한 기계**' 로서의 주택","합리적으로 설계, 모든 기후 조건에 공통적으로 적용되어야 함","대중소비사회의 문화적, 기술적, 보편화 현상과 부합"]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**시트로앵 하우스** 에 대한 설명으로 옳지 않은 것은 무엇일까요?","choices":["**도미노 시스템(Dom-ino)** 주택의 실제 모델","**대량생산** 의 개념에 따라 제시된 주택","1950년대 교회 건축의 기본형식"],"a":2,"why":"1920, 30년대 꼬르뷔지에의 주거계획을 위한 기본형식이에요."},{"kind":"compare","head":"헷갈리기 쉬운 짝","cols":["구분","**도미노 시스템(Dom-ino)**","**시트로앵 하우스**"],"rows":[["무엇","집의 뼈대 개념","그 뼈대로 만든 실제 모델 주택"],["모양","기둥골조 여섯 개, 바닥슬래브 두 개, 지붕","단순한 상자모양, **필로티(Pilotis)**, **복층**"],["핵심말","**융통성**, 모든 주거계획의 원형","**대량생산**, 1920, 30년대 기본형식"]]},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["제목은 '시트로앵 하우스', 캡션은 '시트로앵주택' 이에요. 같은 집이에요.","파란 손글씨는 누군가의 필기예요. 슬라이드 원문이 아니라서 시험 사실로 외우지 않아요."]},{"kind":"english","head":"논술 답안: 시트로앵 하우스","en":"시트로앵 하우스(1924)는 단순한 상자모양, 옥상지붕, 상하층으로 분리된 거실, 넓은 전면창, 필로티, 복층으로 구성된 도미노 주택의 실제 모델로, 대량생산의 개념에 따라 제시되었다.","ko":"연도, 구성 요소, 도미노의 실제 모델, 대량생산을 넣어요.","tip":"'이사(24)하면 상자 집' 으로 연도를 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.05,0.5,0.45],"c":[0.025,0.0275,0.55,0.495],"r":1.4815,"img":"img/U7/walk/p011_23_01.jpg","say":"시트로앵 하우스(1924) 다섯 줄: 상자모양, 필로티, 복층, 도미노의 실제 모델, 대량생산, 기본형식."},{"b":[0.05,0.58,0.5,0.4],"c":[0.025,0.56,0.55,0.44],"r":1.6667,"img":"img/U7/walk/p011_23_02.jpg","say":"시트로앵 하우스의 개념 세 줄: 집합주택과 살기 위한 기계, 모든 기후 조건, 대중소비사회."},{"b":[0.57,0.12,0.42,0.3],"c":[0.538,0.104,0.462,0.332],"r":1.8554,"img":"img/U7/walk/p011_23_03.jpg","say":"위 그림: 기둥 위에 올린 상자 집. 그림 속 글자 '시트로앵 주택(1924)의 한 예', '필로티'."},{"b":[0.57,0.45,0.43,0.42],"c":[0.527,0.429,0.473,0.462],"r":1.3651,"img":"img/U7/walk/p011_23_04.jpg","say":"아래 그림: 집 한 칸씩 층층이 쌓은 건물. 그림 속 글자 '빌 콘템포레느 계획에서의 2층 높이의 단위주거'."},{"b":[0.64,0.91,0.29,0.04],"c":[0.6255,0.875,0.319,0.11],"r":3.8667,"img":"img/U7/walk/p011_23_05.jpg","say":"캡션: 르 코르뷔지에, 시트로앵주택, 1924."}]}},{"p":12,"title":"Impact on Architecture scene: Five Points of Architecture","terms":["Five Points of Architecture","Flat Roof","Roof Garden","Freed Facade","Ribbon Windows","Pilotis","Open Plan","뼈대와 벽의 기능적 분리"],"pass1":[{"kind":"say","lines":["영어로 쓴 **건축의 5원칙(Five Points of Architecture)** 이에요.","흰 건물 사진 위에 1번부터 5번까지 영어로 적혀 있어요.","p.9 한국어 목록과 거의 같지만 한 개가 달라요."]}],"pass2":[{"kind":"points","head":"영어 목록 다섯 개","items":["1 Flat Roof/Roof Garden: **평지붕(Flat Roof)** 과 **옥상정원(Roof Garden)**","2 Freed Facade: **자유로운 입면(Freed Facade)**","3 Ribbon Windows: **수평띠창(Ribbon Windows)**, 옆으로 길게 이어 붙인 띠 모양 창","4 Pilotis: **필로티(Pilotis)**","5 Open Plan: **자유로운 평면(Open Plan)**"]},{"kind":"compare","head":"한국어 목록(p.9)과 영어 목록(p.12)","cols":["번호","한국어 목록","영어 목록"],"rows":[["1","**뼈대와 벽의 기능적 분리**","Flat Roof/Roof Garden"],["2","**필로티(Pilotis)**","Freed Facade"],["3","**옥상정원(Roof Garden)**","Ribbon Windows"],["4","**자유로운 평면(Open Plan)**","Pilotis"],["5","**자유로운 입면(Freed Facade)**","Open Plan"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"영어 목록에만 있고 한국어 목록에는 없는 원칙은 무엇일까요?","choices":["Pilotis","**수평띠창(Ribbon Windows)**","Open Plan"],"a":1,"why":"Ribbon Windows 예요. 한국어 목록에는 그 대신 **뼈대와 벽의 기능적 분리** 가 있어요."},{"kind":"check","q":"영어 목록에서 Pilotis 는 몇 번일까요?","choices":["2번","4번","5번"],"a":1,"why":"영어 목록은 4번이에요. 한국어 목록에서는 ② **필로티(Pilotis)** 로 2번이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["두 목록은 항목도 순서도 달라요. 필로티, 옥상정원, 평면, 입면은 둘 다 있어요.","한국어에만 '뼈대와 벽의 기능적 분리', 영어에만 'Ribbon Windows' 예요.","그림 오른쪽 파란 세로선은 필기 자국이에요."]},{"kind":"english","head":"논술 답안: Five Points of Architecture","en":"르 코르뷔지에의 Five Points of Architecture는 Flat Roof/Roof Garden, Freed Facade, Ribbon Windows, Pilotis, Open Plan의 다섯 가지이다.","ko":"영어 목록은 이 순서대로 외워요.","tip":"'지붕, 얼굴, 띠창, 다리, 바닥' 순서예요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.07,0.9,0.2],"c":[0,0.054,0.99,0.232],"r":5.6897,"img":"img/U7/walk/p012_22_01.jpg","say":"위 두 띠: Impact on Architecture scene, Five Points of Architecture."},{"b":[0.12,0.3,0.76,0.09],"c":[0.082,0.2606,0.836,0.1689],"r":6.5996,"img":"img/U7/walk/p012_22_02.jpg","say":"1 Flat Roof/Roof Garden."},{"b":[0.12,0.42,0.76,0.08],"c":[0.082,0.3756,0.836,0.1689],"r":6.5996,"img":"img/U7/walk/p012_22_03.jpg","say":"2 Freed Facade."},{"b":[0.12,0.53,0.76,0.08],"c":[0.082,0.4856,0.836,0.1689],"r":6.5996,"img":"img/U7/walk/p012_22_04.jpg","say":"3 Ribbon Windows. 한국어 목록에는 없는 항목이에요."},{"b":[0.12,0.64,0.76,0.08],"c":[0.082,0.5956,0.836,0.1689],"r":6.5996,"img":"img/U7/walk/p012_22_05.jpg","say":"4 Pilotis."},{"b":[0.12,0.75,0.76,0.09],"c":[0.082,0.7106,0.836,0.1689],"r":6.5996,"img":"img/U7/walk/p012_22_06.jpg","say":"5 Open Plan. 뒤 사진은 흰 건물이에요. 이름은 적혀 있지 않아요."}]}},{"p":13,"title":"1920년대 코르뷔지에의 '흰 주택' 의 공간구성","terms":["흰 주택","순수직방체","Void","편심","경사로","황금분할","Dom-ino","Ribbon Windows","Villa Garches","Masion Cook","Villa La Roche Jeanneret","Weissenhof Siedlung"],"pass1":[{"kind":"say","lines":["1920년대 **르 코르뷔지에(Le Corbusier)** 의 집들은 하얀 상자 모양이에요.","그래서 이 집들을 **흰 주택** 이라고 불러요."]},{"kind":"analogy","head":"한쪽에 구멍을 뚫은 각설탕 상자","scene":"하얀 각설탕 상자 속을 한쪽으로 치우치게 파냈다고 생각해 보세요.","map":[["겉은 단순한 상자","**순수직방체**"],["속에 위아래로 뚫린 빈 곳","**Void** 와 테라스"],["중심이 한쪽으로 쏠림","**편심**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**흰 주택**: 1920년대 르 코르뷔지에가 지은 하얀 상자 모양 주택들이에요.","**순수직방체**: 군더더기 없는 단순한 상자 모양이에요.","**Void**: 건물 안에 위아래로 비워 둔 빈 공간이에요.","**편심**: 공간의 중심이 한쪽으로 치우친 것이에요.","**경사로**: 계단 대신 비탈길로 오르내리는 길이에요.","**황금분할**: 가장 아름답다고 여겨 온 비례 나누기예요."]},{"kind":"points","head":"**흰 주택** 의 예 (맨 위 줄)","items":["La Roche-Jeanneret 저택 (뒤 p.17의 **Villa La Roche Jeanneret**)","**Masion Cook** (p.15-16)","Garches의 집, 즉 **메종 스테인(Villa Garches)** (p.14)","Stuttgart의 주택 등 (뒤 p.21의 **바이센호프 주거단지(Weissenhof Siedlung)** 2호연립주택)"]},{"kind":"points","head":"공통 공간구성 일곱 줄","items":["기둥을 규칙적으로 배열한 콘크리트 프레임 가구식","**도미노 시스템(Dom-ino)**: 기둥간격 5미터의 균등한 그리드 형성","수평으로 연속된 창, 단순한 상자형태(**순수직방체**)","**Void** 와 테라스의 비대칭적 배치: 내부 공간의 **편심**","계단과 **경사로** 가 **Void** 및 테라스와 서로 호응(sequence 만듬)","중요한 방은 상층부에 설치: 프라이버시와 전망 확보","곡선을 부분적으로 사용하여 구성에 변화를 줌"]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**흰 주택** 에서 **도미노 시스템(Dom-ino)** 으로 만든 그리드의 기둥간격은 얼마일까요?","choices":["3미터","5미터","10미터"],"a":1,"why":"기둥간격 5미터의 균등한 그리드예요."},{"kind":"check","q":"**흰 주택** 에서 내부 공간의 **편심** 을 만든 것은 무엇일까요?","choices":["**Void** 와 테라스의 비대칭적 배치","대칭으로 놓은 기둥","뾰족한 지붕"],"a":0,"why":"**Void** 와 테라스를 비대칭으로 놓아서 중심이 한쪽으로 쏠려요."},{"kind":"check","q":"**흰 주택** 에서 중요한 방을 상층부에 둔 까닭은 무엇일까요?","choices":["프라이버시와 전망 확보","난방비 절약","주차 공간 확보"],"a":0,"why":"중요한 방은 상층부에 설치해 프라이버시와 전망을 확보해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'Masion Cook' 은 Maison Cook(메종 쿡)의 오타로 보여요. 슬라이드 표기를 그대로 알아 둬요.","그림 속 메종 스테인 글자는 앞부분이 잘려 끝자리 '26' 만 보여요. 다음 쪽 캡션은 1928이에요.","공통점 옆과 그림 위 파란 글씨는 필기예요."]},{"kind":"english","head":"논술 답안: 흰 주택의 공간구성","en":"1920년대 흰 주택은 도미노 시스템으로 기둥간격 5미터의 균등한 그리드를 이루고, 수평으로 연속된 창과 순수직방체 형태를 가지며, Void와 테라스의 비대칭적 배치로 내부 공간의 편심을 만든다.","ko":"그리드 5미터, 연속된 창, 순수직방체, Void, 편심을 넣어요.","tip":"남은 세 줄(경사로 호응, 상층부의 방, 부분적 곡선)도 이어서 쓰면 좋아요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.04,0.58,0.07],"c":[0.001,0.0106,0.638,0.1289],"r":6.5994,"img":"img/U7/walk/p013_23_01.jpg","say":"제목: 1920년대 코르뷔지에의 '흰 주택' 의 공간구성."},{"b":[0.02,0.18,0.57,0.11],"c":[0,0.164,0.627,0.142],"r":5.8873,"img":"img/U7/walk/p013_23_02.jpg","say":"예: La Roche-Jeanneret 저택, Masion Cook, Garches의 집(메종 스테인), Stuttgart의 주택 등."},{"b":[0.04,0.3,0.55,0.22],"c":[0.0125,0.284,0.605,0.252],"r":3.2011,"img":"img/U7/walk/p013_23_03.jpg","say":"콘크리트 프레임 가구식, 도미노 5미터 그리드, 수평으로 연속된 창과 순수직방체."},{"b":[0.04,0.54,0.55,0.33],"c":[0.0125,0.5235,0.605,0.363],"r":2.2222,"img":"img/U7/walk/p013_23_04.jpg","say":"Void와 테라스의 편심, 계단과 경사로의 호응, 상층부의 중요한 방, 부분적인 곡선."},{"b":[0.63,0.14,0.36,0.38],"c":[0.604,0.121,0.396,0.418],"r":1.2632,"img":"img/U7/walk/p013_23_05.jpg","say":"위 그림: 메종 스테인 입면. 그림 속 글자 '2층 높이의 테라스', 'VOID', '황금분할에 기초한 비례 관계'."},{"b":[0.63,0.53,0.36,0.33],"c":[0.604,0.5135,0.396,0.363],"r":1.4545,"img":"img/U7/walk/p013_23_06.jpg","say":"아래 평면: 거실, 식당, 부엌, 테라스, '2층 높이의 차례된 테라스'."}]}},{"p":14,"title":"Villa Garches(메종 스테인), 프랑스 파리 근교, 1928","terms":["Villa Garches","흰 주택","Ribbon Windows","순수직방체","Flat Roof"],"pass1":[{"kind":"say","lines":["**메종 스테인(Villa Garches)** 사진이에요. 프랑스 파리 근교, 1928년이에요.","앞 쪽 그림에 나온 바로 그 **흰 주택** 을 실제 사진과 모형으로 보여 줘요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자, 장소, 연도: **르 코르뷔지에(Le Corbusier)**, 프랑스 파리 근교, 1928년.","위 사진: 흰 상자 정면에 가로로 긴 창이 층마다 이어져요. 앞 쪽의 '수평으로 연속된 창' 이에요.","위 사진 오른쪽에 바깥 계단이 땅으로 내려오고, 아래층 왼쪽에는 둥근 벽이 보여요. '곡선을 부분적으로 사용' 한 모습이에요.","왼쪽 아래 모형: 꼭대기를 위에서 내려다본 흰 모형이에요. 평평한 지붕 층에 둥근 벽이 있어요.","오른쪽 아래 사진: 다른 쪽 정면이에요. 가로로 긴 창 두 줄, 위쪽에 튀어나온 발코니, 오른쪽 출입구 위 넓은 차양이 있어요."]},{"kind":"points","head":"앞 쪽과 이어 보기","items":["겉모습은 단순한 상자, 즉 **순수직방체** 예요.","길게 이어진 창은 p.12 영어 5원칙의 **수평띠창(Ribbon Windows)** 과 같은 생각이에요.","지붕은 **평지붕(Flat Roof)** 이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**메종 스테인(Villa Garches)** 의 장소와 연도로 옳은 것은 무엇일까요?","choices":["프랑스 파리 근교, 1928","프랑스 파리, 1926","독일 슈투트가르트, 1927"],"a":0,"why":"파리 근교, 1928년이에요. 파리 1926은 **Masion Cook**, 슈투트가르트 1927은 **바이센호프 주거단지(Weissenhof Siedlung)** 2호연립주택이에요."},{"kind":"check","q":"p.13 목록의 'Garches의 집' 과 같은 집은 무엇일까요?","choices":["**메종 스테인(Villa Garches)**","**Masion Cook**","**Villa La Roche Jeanneret**"],"a":0,"why":"Garches의 집 = **메종 스테인(Villa Garches)** 이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["모형 위 파란 동그라미와 글씨는 필기예요. 슬라이드 원문이 아니에요.","연도는 캡션의 1928을 써요. p.13 그림 속 글자는 끝자리 '26' 만 보여서 어긋날 수 있어요."]}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.28,0.05],"c":[0.026,0.03,0.308,0.11],"r":3.7333,"img":"img/U7/walk/p014_22_01.jpg","say":"제목: Villa Garches(메종 스테인)."},{"b":[0.35,0.05,0.62,0.46],"c":[0.318,0.027,0.682,0.506],"r":1.7971,"img":"img/U7/walk/p014_22_02.jpg","say":"위 사진: 층마다 가로로 길게 이어진 창, 오른쪽 바깥 계단, 아래층 왼쪽의 둥근 벽."},{"b":[0.03,0.55,0.36,0.41],"c":[0.012,0.5295,0.396,0.451],"r":1.1707,"img":"img/U7/walk/p014_22_03.jpg","say":"왼쪽 아래 모형: 평평한 지붕 층에 둥근 벽과 테라스가 보여요."},{"b":[0.43,0.55,0.41,0.37],"c":[0.4095,0.5315,0.451,0.407],"r":1.4775,"img":"img/U7/walk/p014_22_04.jpg","say":"오른쪽 아래 사진: 가로로 긴 창 두 줄, 튀어나온 발코니, 넓은 차양."},{"b":[0.42,0.93,0.53,0.05],"c":[0.3935,0.8822,0.583,0.1178],"r":6.5988,"img":"img/U7/walk/p014_22_05.jpg","say":"캡션: 르 코르뷔지에, Villa Garches(메종 스테인), 프랑스 파리 근교, 1928."}]}},{"p":15,"title":"Masion Cook, 프랑스 파리, 1926","terms":["Masion Cook","흰 주택","Ribbon Windows","Villa Garches"],"pass1":[{"kind":"say","lines":["**Masion Cook** 이에요. 프랑스 파리, 1926년이에요.","슬라이드 철자 Masion 은 Maison(메종)의 오타로 보여요. 메종 쿡이라고 읽어요.","이것도 1920년대 **흰 주택** 가운데 하나예요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자, 장소, 연도: **르 코르뷔지에(Le Corbusier)**, 프랑스 파리, 1926년.","왼쪽 사진: 흰 정면에 가로로 긴 창이 두 줄 이어져요. **수평띠창(Ribbon Windows)** 과 같은 모양이에요.","위층 앞에는 상자 모양 발코니가 튀어나와 있고, 맨 위는 지붕 아래 유리로 둘러싼 테라스예요.","오른쪽 평면 네 장: Terrace, First Floor, Second Floor, Basement.","평면 곳곳에 곡선 벽이 보여요. p.13의 '곡선을 부분적으로 사용' 이에요."]},{"kind":"compare","head":"**흰 주택** 두 채 비교","cols":["","**메종 스테인(Villa Garches)**","**Masion Cook**"],"rows":[["장소","프랑스 파리 근교","프랑스 파리"],["연도","1928","1926"],["이 슬라이드의 그림","사진 두 장과 모형","사진 한 장과 평면 네 장"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**Masion Cook** 의 장소와 연도로 옳은 것은 무엇일까요?","choices":["프랑스 파리, 1926","프랑스 파리 근교, 1928","프랑스 포와시, 1931"],"a":0,"why":"파리, 1926년이에요. 파리 근교 1928은 **메종 스테인(Villa Garches)** 이에요."},{"kind":"check","q":"**Masion Cook** 슬라이드의 평면 이름에 없는 것은 무엇일까요?","choices":["Terrace","Basement","Garage"],"a":2,"why":"평면은 Terrace, First Floor, Second Floor, Basement 네 장이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["'Masion' 은 Maison 의 오타로 보이지만 슬라이드 표기를 그대로 알아 둬요.","평면 위 파란 글씨 두 군데는 필기예요. 슬라이드 원문이 아니에요."]},{"kind":"english","head":"논술 답안: 흰 주택의 예","en":"1920년대 르 코르뷔지에의 흰 주택에는 La Roche-Jeanneret 저택, Masion Cook(프랑스 파리, 1926), Garches의 집(메종 스테인, 프랑스 파리 근교, 1928), Stuttgart의 주택 등이 있다.","ko":"작품 이름과 장소, 연도를 짝지어 써요.","tip":"'육(26)은 쿡, 팔(28)은 스테인' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.15,0.05],"c":[0.015,0.01,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p015_22_01.jpg","say":"제목: Masion Cook. 철자 Masion 은 오타로 보여요."},{"b":[0.03,0.12,0.51,0.75],"c":[0.0045,0.0825,0.561,0.825],"r":0.9067,"img":"img/U7/walk/p015_22_02.jpg","say":"왼쪽 사진: 가로로 긴 창 두 줄, 튀어나온 발코니, 맨 위 유리 테라스."},{"b":[0.06,0.88,0.39,0.05],"c":[0.0405,0.85,0.429,0.11],"r":5.2,"img":"img/U7/walk/p015_22_03.jpg","say":"캡션: 르 코르뷔지에, Masion Cook, 프랑스 파리, 1926."},{"b":[0.57,0.13,0.2,0.34],"c":[0.558,0.113,0.224,0.374],"r":0.7986,"img":"img/U7/walk/p015_22_04.jpg","say":"평면 Terrace."},{"b":[0.79,0.13,0.2,0.34],"c":[0.776,0.113,0.224,0.374],"r":0.7986,"img":"img/U7/walk/p015_22_05.jpg","say":"평면 First Floor. 곡선 벽이 보여요."},{"b":[0.57,0.48,0.42,0.34],"c":[0.538,0.463,0.462,0.374],"r":1.6471,"img":"img/U7/walk/p015_22_06.jpg","say":"평면 Second Floor 와 Basement."}]}},{"p":16,"title":"르 코르뷔지에, Masion Cook 실내 네 컷, 프랑스 파리, 1926","terms":["Le Corbusier","Masion Cook","흰 주택","Void","편심","순수직방체","Villa Garches"],"pass1":[{"kind":"say","lines":["사진 네 장이 모두 집 안을 찍은 거예요.","**르 코르뷔지에(Le Corbusier)** 의 **Masion Cook**, 프랑스 파리, 1926년이에요.","1920년대 하얀 상자 집, **흰 주택** 의 속을 들여다보는 쪽이에요."]},{"kind":"analogy","head":"하얀 각설탕 상자 속","scene":"하얀 각설탕 상자 안에 구멍을 한쪽으로 치우치게 뚫는다고 생각해 보세요.","map":[["겉의 단순한 상자","**순수직방체**"],["위아래로 뚫린 빈 구멍","**Void**"],["중심이 한쪽으로 쏠림","**편심**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**흰 주택**: 1920년대 르 코르뷔지에가 지은 하얀 상자 모양 주택들이에요.","**Void**: 건물 안에 위아래로 비워 둔 빈 공간이에요.","**편심**: 공간의 중심이 한쪽으로 치우친 것이에요.","**Masion Cook** 은 슬라이드 철자예요. Maison(메종)의 오타로 보여서 메종 쿡이라고 읽어요."]},{"kind":"points","head":"사진에서 보이는 것","items":["왼쪽 위: 큰 문 너머로 바닥돌을 깐 테라스가 보여요. 오른쪽에는 아래로 트인 난간이 있어요.","오른쪽 위: 천장이 높은 거실이에요. 큰 창, 계단, 안락의자가 보이고 천장 한쪽이 둥글게 휘어요.","왼쪽 아래: 둥글게 휜 벽 양옆에 좁고 긴 창이 있고, 그 아래로 가로로 긴 창이 이어져요.","오른쪽 아래: 위에서 내려다본 높은 공간이에요. 여러 층의 벽과 난간이 겹쳐 보여요."]},{"kind":"points","head":"p.13 공통점과 맞춰 보기","items":["p.13은 **흰 주택** 의 공통점으로 수평으로 연속된 창, 단순한 상자형태(**순수직방체**)를 꼽았어요.","또 **Void** 와 테라스의 비대칭적 배치가 내부 공간의 **편심** 을 만든다고 했어요.","왼쪽 아래 사진의 가로로 긴 창이 '수평으로 연속된 창' 과 닮았어요.","천장이 높게 트인 오른쪽 사진들은 위아래로 뚫린 **Void** 를 떠올리게 해요.","둥근 천장과 벽은 '곡선을 부분적으로 사용하여 구성에 변화를 줌' 과 이어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**Masion Cook** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["프랑스 파리, 1926","프랑스 포와시, 1931","독일 슈투트가르트, 1927"],"a":0,"why":"프랑스 파리, 1926년이에요. 포와시 1931은 빌라 사보아, 슈투트가르트 1927은 2호연립주택이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드 철자 Masion Cook 은 Maison Cook(메종 쿡)의 오타로 보여요.","**메종 스테인(Villa Garches)** 은 1928년, 파리 근교예요. 메종 쿡(1926)과 헷갈리지 마세요.","사진 옆 파란 손글씨는 슬라이드 원문이 아니에요. 시험 사실로 외우지 마세요."]}],"walk":{"head":null,"parts":[{"b":[0.161,0.073,0.334,0.418],"c":[0.1443,0.0521,0.3674,0.4598],"r":1.0654,"img":"img/U7/walk/p016_23_01.jpg","say":"왼쪽 위: 큰 문 너머 테라스예요. 오른쪽에 아래로 트인 난간이 있어요."},{"b":[0.504,0.073,0.335,0.418],"c":[0.4872,0.0521,0.3685,0.4598],"r":1.0686,"img":"img/U7/walk/p016_23_02.jpg","say":"오른쪽 위: 천장이 높은 거실과 계단이에요. 천장 한쪽이 둥글어요."},{"b":[0.161,0.503,0.334,0.416],"c":[0.1443,0.4822,0.3674,0.4576],"r":1.0705,"img":"img/U7/walk/p016_23_03.jpg","say":"왼쪽 아래: 둥근 벽 아래로 가로로 긴 창이 이어져요."},{"b":[0.504,0.503,0.335,0.416],"c":[0.4872,0.4822,0.3685,0.4576],"r":1.0737,"img":"img/U7/walk/p016_23_04.jpg","say":"오른쪽 아래: 위에서 내려다본 높은 공간이에요. 벽과 난간이 겹쳐요."},{"b":[0.296,0.945,0.372,0.032],"c":[0.2774,0.89,0.4092,0.11],"r":4.96,"img":"img/U7/walk/p016_23_05.jpg","say":"캡션: 르 코르뷔지에, Masion Cook, 프랑스 파리, 1926."}]}},{"p":17,"title":"르 코르뷔지에, Villa La Roche Jeanneret, 프랑스 파리, 1924","terms":["Villa La Roche Jeanneret","Le Corbusier","흰 주택","Pilotis","Ribbon Windows","Five Points of Architecture"],"pass1":[{"kind":"say","lines":["이번 집은 **Villa La Roche Jeanneret** 예요. 프랑스 파리, 1924년이에요.","왼쪽에 평면도 세 장, 오른쪽에 하얀 집 사진이 있어요.","둥글게 휜 벽과 반듯한 벽이 한 집에 같이 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 볼 것","items":["설계자, 작품, 도시, 연도는 **르 코르뷔지에(Le Corbusier)**, **Villa La Roche Jeanneret**, 프랑스 파리, 1924년이에요.","p.13 **흰 주택** 목록의 'La Roche-Jeanneret 저택' 이 바로 이 집이에요.","평면도는 위에서부터 3층, 2층, 1층이에요. 한쪽 끝이 둥글게 휜 모양이 보여요.","사진 가운데: 휜 벽 위쪽에 가로로 긴 창이 이어지고, 그 아래를 가는 기둥이 받쳐 비어 있어요.","사진 오른쪽: 반듯한 흰 벽에 가로로 긴 창이 층마다 나 있어요."]},{"kind":"points","head":"기둥과 창, 용어로 부르기","items":["기둥으로 건물을 들어 올려 아래를 비우는 방식이 **필로티(Pilotis)** 예요.","건물 옆으로 길게 이어 붙인 띠 모양 창은 **수평띠창(Ribbon Windows)** 이에요.","둘 다 p.12 영어 목록 **건축의 5원칙(Five Points of Architecture)** 에 들어 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**Villa La Roche Jeanneret** 의 연도는 무엇일까요?","choices":["1924","1926","1928"],"a":0,"why":"1924년 프랑스 파리예요. 1926은 Masion Cook, 1928은 메종 스테인이에요."}],"walk":{"head":{"b":[0.2675,0.0056,0.0797,0.0284],"c":[0.2073,0,0.2,0.0604],"r":4.415,"img":"img/U7/walk/p017_h.jpg"},"parts":[{"b":[0.068,0.036,0.227,0.032],"c":[0.056,0,0.251,0.11],"r":3.0424,"img":"img/U7/walk/p017_22_01.jpg","say":"제목: Villa La Roche Jeanneret."},{"b":[0.075,0.1,0.252,0.674],"c":[0.0568,0.0663,0.2883,0.7414],"r":0.5185,"img":"img/U7/walk/p017_22_02.jpg","say":"평면도 세 장: 위에서부터 3층, 2층, 1층 평면도예요."},{"b":[0.36,0.44,0.315,0.24],"c":[0.3442,0.424,0.3465,0.272],"r":1.6985,"img":"img/U7/walk/p017_22_03.jpg","say":"휜 벽 위쪽에 가로로 긴 창이 이어져요."},{"b":[0.49,0.66,0.19,0.13],"c":[0.478,0.644,0.214,0.162],"r":1.7613,"img":"img/U7/walk/p017_22_04.jpg","say":"휜 벽 아래를 가는 기둥이 받치고 비어 있어요."},{"b":[0.675,0.09,0.288,0.65],"c":[0.6606,0.0575,0.3168,0.715],"r":0.5908,"img":"img/U7/walk/p017_22_05.jpg","say":"반듯한 흰 벽에 층마다 가로로 긴 창이 나 있어요."},{"b":[0.439,0.945,0.465,0.032],"c":[0.4157,0.89,0.5115,0.11],"r":6.2,"img":"img/U7/walk/p017_22_06.jpg","say":"캡션: 르 코르뷔지에, Villa La Roche Jeanneret, 프랑스 파리, 1924."}]}},{"p":18,"title":"둥근 벽과 반듯한 벽, 하얀 집 두 컷 (글자 없는 슬라이드)","terms":["Villa La Roche Jeanneret","Pilotis","Ribbon Windows","흰 주택"],"pass1":[{"kind":"say","lines":["글자 없이 사진 두 장만 있는 쪽이에요.","왼쪽은 둥근 벽, 오른쪽은 반듯한 벽이에요. 둘 다 하얀 **흰 주택** 모습이에요.","앞 쪽 **Villa La Roche Jeanneret** 의 둥근 벽과 닮았어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["캡션이 없어서 이 쪽은 이름도 연도도 말해 주지 않아요.","왼쪽: 둥근 흰 벽 위쪽에 가로로 긴 창이 둘러요.","왼쪽 아래: 튀어나온 덩어리를 기둥 하나가 받치고, 그 아래가 비어 마당으로 이어져요.","기둥으로 들어 올려 아래를 비운 모습이 **필로티(Pilotis)** 예요.","오른쪽: 반듯한 흰 벽에 **수평띠창(Ribbon Windows)** 이 길게 이어져요.","오른쪽 1층에는 큰 회색 문과 작은 출입문이 있고, 앞에 차가 서 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 쪽에는 캡션이 없어요. 이름과 연도는 p.17 캡션에서 가져와 같은 집으로 보는 거예요.","사진 위 파란 손글씨는 슬라이드 원문이 아니에요. 시험 사실로 외우지 마세요."]}],"walk":{"head":null,"parts":[{"b":[0.016,0.089,0.462,0.821],"c":[0,0.0479,0.5082,0.9031],"r":0.7503,"img":"img/U7/walk/p018_21_01.jpg","say":"왼쪽 사진: 둥근 흰 벽이에요."},{"b":[0.136,0.257,0.286,0.09],"c":[0.1217,0.241,0.3146,0.122],"r":3.4383,"img":"img/U7/walk/p018_21_02.jpg","say":"둥근 벽 위쪽을 두른 가로로 긴 창이에요."},{"b":[0.06,0.514,0.1,0.324],"c":[0.01,0.4978,0.2,0.3564],"r":0.7482,"img":"img/U7/walk/p018_21_03.jpg","say":"덩어리를 받치는 기둥과 그 아래 빈 곳이에요."},{"b":[0.521,0.243,0.408,0.29],"c":[0.5006,0.227,0.4488,0.322],"r":1.8584,"img":"img/U7/walk/p018_21_04.jpg","say":"오른쪽 사진: 반듯한 벽의 수평띠창이에요."},{"b":[0.521,0.586,0.13,0.319],"c":[0.486,0.57,0.2,0.351],"r":0.7597,"img":"img/U7/walk/p018_21_05.jpg","say":"오른쪽 1층의 큰 회색 문이에요."}]}},{"p":19,"title":"실내와 필로티, LC4 Chaise Lounge","terms":["LC4 Chaise Lounge","Le Corbusier","Pierre Jeanneret","샤롯테 페리앙","Pilotis","경사로","Villa La Roche Jeanneret"],"pass1":[{"kind":"say","lines":["사진 세 장과 의자 그림 한 장이에요.","오른쪽 아래 의자가 **LC4 Chaise Lounge** 예요.","**르 코르뷔지에(Le Corbusier)**, **피에르 잔느레(Pierre Jeanneret)**, **샤롯테 페리앙** 이 함께 디자인했어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**LC4 Chaise Lounge**: 누워서 쉬는 긴 의자예요. 금속 틀 위에 몸 모양으로 휜 받침이 얹혀 있어요.","**피에르 잔느레(Pierre Jeanneret)**: 르 코르뷔지에와 함께 설계하고 가구를 디자인한 건축가예요.","**샤롯테 페리앙**: LC4 Chaise Lounge를 함께 디자인한 디자이너예요. 이름은 슬라이드 표기 그대로예요."]},{"kind":"points","head":"사진에서 보이는 것","items":["왼쪽 위: 둥글게 휜 벽을 따라 가로로 긴 창이 이어지고, 창 앞에 둥근 기둥이 서 있어요.","오른쪽 위: 분홍 바닥에 검은 탁자가 있고, 붉은 면이 비스듬히 올라가요.","비스듬히 오르는 모양이 계단 대신 비탈길로 오르는 **경사로** 를 떠올리게 해요.","왼쪽 아래: 둥근 덩어리 아래를 둥근 기둥 하나가 받쳐요. 아래는 비어 자갈 마당이 돼요.","앞 쪽 **Villa La Roche Jeanneret** 의 둥근 벽, 긴 창, **필로티(Pilotis)** 와 닮은 요소들이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**LC4 Chaise Lounge** 를 함께 디자인한 세 사람으로 옳은 것은 무엇일까요?","choices":["르 코르뷔지에, 피에르 잔느레, 샤롯테 페리앙","르 코르뷔지에, 오장팡, 피에르 잔느레","르 코르뷔지에, 샤롯테 페리앙, 발터 그로피우스"],"a":0,"why":"슬라이드 캡션 그대로 르 코르뷔지에, 피에르 잔느레, 샤롯테 페리앙이에요. 오장팡은 잡지 에스프리 누보 쪽 인물이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**피에르 잔느레(Pierre Jeanneret)** 는 2호연립주택(1927)도 르 코르뷔지에와 함께 설계했어요.","의자는 세 사람, 2호연립주택은 두 사람이에요. 인원 수로 구분해요."]}],"walk":{"head":null,"parts":[{"b":[0.035,0.027,0.465,0.466],"c":[0.0117,0.0037,0.5115,0.5126],"r":1.3305,"img":"img/U7/walk/p019_22_01.jpg","say":"왼쪽 위: 휜 벽을 따라 이어진 긴 창과 둥근 기둥이에요."},{"b":[0.521,0.027,0.466,0.466],"c":[0.4874,0.0037,0.5126,0.5126],"r":1.3333,"img":"img/U7/walk/p019_22_02.jpg","say":"오른쪽 위: 분홍 바닥, 검은 탁자, 비스듬히 오르는 붉은 면이에요."},{"b":[0.035,0.531,0.465,0.464],"c":[0.0117,0.4896,0.5115,0.5104],"r":1.3362,"img":"img/U7/walk/p019_22_03.jpg","say":"왼쪽 아래: 둥근 덩어리를 받치는 기둥 하나와 빈 아래 공간이에요."},{"b":[0.568,0.59,0.321,0.248],"c":[0.5519,0.574,0.3531,0.28],"r":1.6814,"img":"img/U7/walk/p019_22_04.jpg","say":"LC4 Chaise Lounge: 금속 틀 위에 휜 받침, 머리 받침이 있어요."},{"b":[0.541,0.895,0.395,0.072],"c":[0.5212,0.876,0.4345,0.11],"r":5.2667,"img":"img/U7/walk/p019_22_05.jpg","say":"캡션: LC4 Chaise Lounge, 르 코르뷔지에, 피에르 잔느레, 샤롯테 페리앙 디자인."}]}},{"p":20,"title":"창 안의 긴 의자와 색이 있는 실내 (글자 없는 슬라이드)","terms":["LC4 Chaise Lounge","Void","흰 주택"],"pass1":[{"kind":"say","lines":["글자 없이 사진 두 장만 있는 쪽이에요.","왼쪽은 집 바깥, 오른쪽은 집 안이에요.","왼쪽 유리창 안에 앞 쪽 **LC4 Chaise Lounge** 와 닮은 의자가 보여요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["캡션이 없어서 이 쪽에는 이름도 연도도 적혀 있지 않아요.","왼쪽: 흰 벽 위에 큰 유리창이 있고, 아래에 검은 두 짝 문이 있어요.","유리창 안에 긴 의자 하나가 놓여 있어요. 모양이 **LC4 Chaise Lounge** 와 같아 보여요.","왼쪽 끝에는 둥글게 휜 벽의 모서리가 살짝 보여요.","오른쪽: 천장이 높은 방이에요. 노란 벽, 붉게 휜 벽, 검은 소파와 검은 탁자가 있어요.","바닥은 분홍색이고, 천장 가까이에 높은 창이 나 있어요."]},{"kind":"points","head":"겉은 하얗고 속은 색","items":["**흰 주택** 은 겉이 하얀 상자예요. 그런데 오른쪽 방은 벽마다 색이 달라요.","노랑, 붉은색, 회색 면이 나뉘어 칠해져 있어요.","두 층 높이로 높게 트인 방은 위아래로 비운 **Void** 를 떠올리게 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 쪽은 캡션이 없어요. 의자 이름은 p.19 캡션에서 가져왔어요.","어느 집의 어느 방인지는 슬라이드에 적혀 있지 않아요. 보이는 것만 기억해요."]}],"walk":{"head":null,"parts":[{"b":[0.016,0.089,0.482,0.854],"c":[0,0.0463,0.5302,0.9394],"r":0.7525,"img":"img/U7/walk/p020_22_01.jpg","say":"왼쪽 사진: 흰 벽, 큰 유리창, 검은 문이에요."},{"b":[0.121,0.49,0.15,0.08],"c":[0.096,0.474,0.2,0.112],"r":2.381,"img":"img/U7/walk/p020_22_02.jpg","say":"유리창 안의 긴 의자예요. LC4 Chaise Lounge와 같은 모양이에요."},{"b":[0.5,0.089,0.48,0.854],"c":[0.472,0.0463,0.528,0.9394],"r":0.7494,"img":"img/U7/walk/p020_22_03.jpg","say":"오른쪽 사진: 천장이 높은 방이에요."},{"b":[0.5,0.362,0.136,0.381],"c":[0.468,0.3429,0.2,0.4191],"r":0.6363,"img":"img/U7/walk/p020_22_04.jpg","say":"붉게 휜 벽이에요."},{"b":[0.675,0.514,0.154,0.081],"c":[0.652,0.498,0.2,0.113],"r":2.3599,"img":"img/U7/walk/p020_22_05.jpg","say":"노란 벽 앞의 검은 소파예요."}]}},{"p":21,"title":"르 코르뷔지에 & 피에르 잔느레, 바이센호프 주거단지 2호연립주택, 1927","terms":["바이센호프 주거단지 2호연립주택","Weissenhof Siedlung","Le Corbusier","Pierre Jeanneret","흰 주택","Pilotis","Ribbon Windows","Flat Roof","순수직방체"],"pass1":[{"kind":"say","lines":["**바이센호프 주거단지 2호연립주택** 이에요. 5단원에서 만난 집이에요.","**르 코르뷔지에(Le Corbusier)** & **피에르 잔느레(Pierre Jeanneret)**, 독일 슈투트가르트, 1927년이에요.","하얀 상자가 가는 기둥 위에 얹혀 있어요. 이것도 **흰 주택** 이에요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 볼 것","items":["캡션: 르 코르뷔지에 & 피에르 잔느레, **바이센호프 주거단지 2호연립주택**, 독일 슈투트가르트, 1927.","슈투트가르트의 집이라 p.13 **흰 주택** 목록의 'Stuttgart의 주택' 과 이어져요.","사진: 위층 상자가 앞으로 내밀리고, 그 아래를 가는 기둥이 줄지어 받쳐요. **필로티(Pilotis)** 예요.","옆면에는 가로로 긴 창이 이어져요. **수평띠창(Ribbon Windows)** 이에요.","지붕은 평평한 **평지붕(Flat Roof)** 이에요. 오른쪽 위 입체 그림에 옥상 공간이 그려져 있어요.","A, B, C 평면은 두 집이 거울처럼 마주 보는 모양이에요. 위쪽에 둥근 계단이 하나씩 있어요."]},{"kind":"points","head":"5단원에서 다시 부르기","items":["**바이센호프 주거단지(Weissenhof Siedlung)** 는 1927년 슈투트가르트에서 열린 근대건축가들의 주택전시회였어요.","5단원에서는 이 집이 **필로티(Pilotis)** 와 개방적인 평면 개념을 보여 줬다고 배웠어요.","7단원에서는 같은 집을 단순한 상자형태(**순수직방체**)의 **흰 주택** 무리로 다시 봐요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**바이센호프 주거단지 2호연립주택** 의 설계자와 연도로 옳은 것은 무엇일까요?","choices":["르 코르뷔지에 & 피에르 잔느레, 1927","르 코르뷔지에 혼자, 1931","르 코르뷔지에 & 샤롯테 페리앙, 1924"],"a":0,"why":"캡션 그대로 르 코르뷔지에 & 피에르 잔느레, 독일 슈투트가르트, 1927년이에요."},{"kind":"english","head":"논술 답안: 1920년대 흰 주택","en":"르 코르뷔지에의 1920년대 흰 주택(La Roche-Jeanneret 저택, 메종 쿡, 메종 스테인, Stuttgart의 주택 등)은 수평으로 연속된 창과 순수직방체, Void와 테라스의 비대칭적 배치에 의한 편심을 공통으로 가진다.","ko":"작품 이름 넷, 그다음 공통점 셋(창, 상자, 편심) 순서예요.","tip":"연도는 라 로슈 1924, 쿡 1926, 2호연립 1927, 스테인 1928로 해마다 하나씩이에요."}],"walk":{"head":null,"parts":[{"b":[0.049,0.04,0.109,0.029],"c":[0.0035,0,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p021_22_01.jpg","say":"제목: 2호연립주택."},{"b":[0.037,0.101,0.452,0.744],"c":[0.0144,0.0638,0.4972,0.8184],"r":0.81,"img":"img/U7/walk/p021_22_02.jpg","say":"사진: 내밀린 흰 상자와 가로로 긴 창이에요."},{"b":[0.182,0.438,0.232,0.11],"c":[0.17,0.422,0.256,0.142],"r":2.4038,"img":"img/U7/walk/p021_22_03.jpg","say":"상자 아래를 가는 기둥이 줄지어 받쳐요. 필로티예요."},{"b":[0.748,0.01,0.231,0.286],"c":[0.736,0,0.255,0.318],"r":1.0692,"img":"img/U7/walk/p021_22_04.jpg","say":"오른쪽 위 입체 그림: 옥상 공간까지 그린 집 전체예요."},{"b":[0.525,0.31,0.329,0.666],"c":[0.5086,0.2674,0.3619,0.7326],"r":0.6587,"img":"img/U7/walk/p021_22_05.jpg","say":"A, B, C 평면: 두 집이 거울처럼 마주 보고 둥근 계단이 있어요."},{"b":[0.044,0.871,0.413,0.11],"c":[0.0234,0.855,0.4543,0.142],"r":4.2657,"img":"img/U7/walk/p021_22_06.jpg","say":"캡션: 르 코르뷔지에 & 피에르 잔느레, 독일 슈투트가르트, 1927."}]}},{"p":22,"title":"르 코르뷔지에, 빌라 사보아, 프랑스 포와시, 1931","terms":["Villa Savoye","Le Corbusier","Pilotis","Ribbon Windows","Flat Roof","Roof Garden","Five Points of Architecture"],"pass1":[{"kind":"analogy","head":"젓가락 위의 도시락 상자","scene":"잔디밭 위에 하얀 도시락 상자를 젓가락 여러 개로 받쳐 든 모습을 떠올려 보세요.","map":[["하얀 도시락 상자","백색의 단순한 입방체"],["받쳐 든 젓가락","**필로티(Pilotis)**"],["상자를 두른 줄무늬","**수평띠창(Ribbon Windows)**"]]},{"kind":"say","lines":["**빌라 사보아(Villa Savoye)**, **르 코르뷔지에(Le Corbusier)**, 프랑스 포와시, 1931년이에요.","이제부터 네 쪽 동안 이 집 하나만 봐요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["캡션: 르 코르뷔지에, **빌라 사보아(Villa Savoye)**, 프랑스 포와시, 1931.","흰 상자가 가는 기둥들 위에 떠 있어요. 그 아래가 비어 있어요.","상자 둘레를 가로로 긴 창이 한 줄로 둘러요.","1층 벽은 위층 상자보다 안쪽으로 들어가 있고, 일부가 짙은 초록색이에요.","지붕 위에는 둥글게 휜 흰 벽이 솟아 있어요."]},{"kind":"points","head":"용어로 다시 부르기","items":["가는 기둥으로 들어 올린 방식은 **필로티(Pilotis)** 예요.","상자를 두른 긴 창은 **수평띠창(Ribbon Windows)** 이에요.","경사 없이 평평한 지붕은 **평지붕(Flat Roof)**, 그 위에 만든 정원은 **옥상정원(Roof Garden)** 이에요.","넷 모두 p.12 영어 목록 **건축의 5원칙(Five Points of Architecture)** 에 들어 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**빌라 사보아(Villa Savoye)** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["프랑스 포와시, 1931","프랑스 파리, 1926","프랑스 마르세이유, 1952"],"a":0,"why":"포와시, 1931년이에요. 파리 1926은 Masion Cook, 마르세이유 1952는 유니테 다비타시옹이에요."}],"walk":{"head":null,"parts":[{"b":[0.093,0.081,0.104,0.029],"c":[0.045,0.0405,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p022_22_01.jpg","say":"제목: 빌라 사보아."},{"b":[0.262,0.465,0.483,0.14],"c":[0.2379,0.449,0.5313,0.172],"r":4.1186,"img":"img/U7/walk/p022_22_02.jpg","say":"흰 상자와 둘레를 두른 가로로 긴 창이에요."},{"b":[0.271,0.6,0.468,0.067],"c":[0.2476,0.5785,0.5148,0.11],"r":6.24,"img":"img/U7/walk/p022_22_03.jpg","say":"상자를 받치는 가는 기둥들이에요. 필로티예요."},{"b":[0.312,0.59,0.225,0.09],"c":[0.3,0.574,0.249,0.122],"r":2.7213,"img":"img/U7/walk/p022_22_04.jpg","say":"안쪽으로 들어간 1층 벽이에요. 일부가 짙은 초록색이에요."},{"b":[0.548,0.44,0.15,0.07],"c":[0.523,0.42,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p022_22_05.jpg","say":"지붕 위로 솟은 둥근 흰 벽이에요."},{"b":[0.486,0.948,0.371,0.029],"c":[0.4674,0.89,0.4081,0.11],"r":4.9467,"img":"img/U7/walk/p022_22_06.jpg","say":"캡션: 르 코르뷔지에, 빌라 사보아, 프랑스 포와시, 1931."}]}},{"p":23,"title":"빌라 사보아의 네 가지 특징","terms":["Villa Savoye","Ribbon Windows","Pilotis","경사로","순수직방체","흰 주택"],"pass1":[{"kind":"say","lines":["**빌라 사보아(Villa Savoye)** 의 특징이 네 줄로 적혀 있어요.","하얀 상자, 위층의 생활 공간, 긴 창과 기둥, 지붕까지 이어지는 비탈길이에요."]}],"pass2":[{"kind":"points","head":"슬라이드 네 줄","items":["백색의 단순한 입방체로 설계된 2층 건물.","상층부에 주공간 구성.","연속된 **수평띠창(Ribbon Windows)**, **필로티(Pilotis)**.","지붕까지 계속되는 실내의 경사."]},{"kind":"points","head":"뜻 풀기","items":["입방체: 반듯한 상자 모양이에요. p.13 **흰 주택** 의 **순수직방체** 와 같은 생각이에요.","주공간: 거실, 식당처럼 주로 생활하는 곳이에요. 그것을 위층에 두었어요.","p.13 공통점 '중요한 방은 상층부에 설치: 프라이버시와 전망 확보' 와 이어져요.","실내의 경사: 계단 대신 비탈길, 즉 **경사로** 가 집 안에서 지붕까지 이어진다는 뜻이에요."]},{"kind":"points","head":"그림에서 볼 것","items":["왼쪽 모형: 지붕 위를 위에서 내려다본 모습이에요. 비스듬한 **경사로** 와 둥근 벽이 보여요.","모형 아래를 가는 기둥들이 받치고 있어요. **필로티(Pilotis)** 예요.","오른쪽 사진: 옥상 테라스예요. 비스듬히 오르는 벽, 둥근 벽, 높고 둥근 기둥 모양 구조물이 보여요.","옥상 테라스 앞쪽에 나무를 심은 화단이 있어요. 지붕 위 정원, **옥상정원(Roof Garden)** 을 떠올리게 해요.","사진 위 작은 글자는 '1931 Villa Savoye, Poissy, France' 예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**빌라 사보아(Villa Savoye)** 설명으로 슬라이드와 다른 것은 무엇일까요?","choices":["백색의 단순한 입방체로 설계된 2층 건물","상층부에 주공간 구성","1층에 주공간을 두고 위층은 비움"],"a":2,"why":"주공간은 상층부예요. 아래는 기둥으로 들어 올려 비워요."},{"kind":"english","head":"논술 답안: 빌라 사보아 핵심","en":"빌라 사보아(르 코르뷔지에, 프랑스 포와시, 1931)는 백색의 단순한 입방체로 설계된 2층 건물로, 상층부에 주공간을 구성하고 연속된 수평띠창, 필로티, 지붕까지 계속되는 실내의 경사를 가진다.","ko":"슬라이드 네 줄을 그대로 한 문장으로 이었어요.","tip":"'흰 상자, 위층, 띠창과 기둥, 경사' 네 마디로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.08,0.045,0.12,0.035],"c":[0.04,0.0075,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p023_23_01.jpg","say":"제목: 빌라 사보아."},{"b":[0.1,0.1,0.45,0.22],"c":[0.0775,0.084,0.495,0.252],"r":2.619,"img":"img/U7/walk/p023_23_02.jpg","say":"특징 네 줄: 입방체 2층, 상층부 주공간, 수평띠창과 필로티, 실내의 경사."},{"b":[0.035,0.405,0.544,0.568],"c":[0.0078,0.3752,0.5984,0.6248],"r":1.277,"img":"img/U7/walk/p023_23_03.jpg","say":"왼쪽 모형: 지붕 위의 경사로와 둥근 벽, 아래의 가는 기둥이에요."},{"b":[0.605,0.248,0.395,0.728],"c":[0.5655,0.1992,0.4345,0.8008],"r":0.7234,"img":"img/U7/walk/p023_23_04.jpg","say":"오른쪽 사진: 옥상 테라스와 비스듬히 오르는 벽이에요."},{"b":[0.62,0.278,0.125,0.03],"c":[0.5825,0.238,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p023_23_05.jpg","say":"사진 속 글자: 1931 Villa Savoye, Poissy, France."}]}},{"p":24,"title":"빌라 사보아 사진과 평면 세 장","terms":["Villa Savoye","Open Plan","Five Points of Architecture","Dom-ino","경사로","Pilotis"],"pass1":[{"kind":"say","lines":["위에 **빌라 사보아(Villa Savoye)** 사진, 아래에 평면 세 장이에요.","평면은 층마다 위에서 내려다본 지도 같은 그림이에요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 볼 것","items":["캡션: 르 코르뷔지에, 빌라 사보아, 프랑스 포와시, 1931. p.22와 같아요.","위 사진은 p.22와 같은 장면이에요. 흰 상자, 긴 창, 가는 기둥이 보여요.","평면 그림 모서리에 2, 3, 4 번호가 붙어 있어요.","왼쪽 평면: 한쪽 끝이 둥근 U자 모양이에요. 곡선 안쪽에 자동차 모양이 그려져 있어요.","가운데 평면: 오른쪽 위에 넓은 바닥 격자가 있고 'TERRASSE(테라스)' 라고 적혀 있어요.","오른쪽 평면: 둥글게 휜 벽이 있는 가장 위층 평면이에요."]},{"kind":"points","head":"평면으로 다시 보는 원리","items":["왼쪽 평면 둘레에 점처럼 찍힌 기둥들이 보여요. 집을 받치는 것이 벽이 아니라 기둥이에요.","기둥과 바닥판만으로 뼈대를 짜는 생각이 **도미노 시스템(Dom-ino)** 이에요.","벽이 짐을 안 지니 방 배치를 마음대로 하는 평면을 **자유로운 평면(Open Plan)** 이라 해요.","**자유로운 평면** 은 p.9, p.12 **건축의 5원칙(Five Points of Architecture)** 두 목록 모두에 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**빌라 사보아(Villa Savoye)** 의 주공간은 어디에 있을까요?","choices":["1층","상층부","지하층"],"a":1,"why":"p.23 '상층부에 주공간 구성' 이에요. 1층 벽은 위층 아래로 물러서 있어요(p.25)."},{"kind":"check","q":"벽이 짐을 안 지니 방 배치를 마음대로 하는 평면을 무엇이라 할까요?","choices":["**자유로운 평면(Open Plan)**","**자유로운 입면(Freed Facade)**","**수평띠창(Ribbon Windows)**"],"a":0,"why":"자유로운 평면이에요. 자유로운 입면은 겉면의 창과 벽을 마음대로 짜는 것이에요."}],"walk":{"head":null,"parts":[{"b":[0.066,0.027,0.891,0.451],"c":[0.0199,0.0045,0.9801,0.4961],"r":2.6341,"img":"img/U7/walk/p024_22_01.jpg","say":"위 사진: p.22와 같은 빌라 사보아 전경이에요."},{"b":[0.049,0.543,0.28,0.405],"c":[0.035,0.5228,0.308,0.4455],"r":0.9218,"img":"img/U7/walk/p024_22_02.jpg","say":"왼쪽 평면(2): 끝이 둥근 U자 모양, 안에 자동차 모양이 그려져 있어요."},{"b":[0.366,0.543,0.281,0.41],"c":[0.3519,0.5225,0.3091,0.451],"r":0.9138,"img":"img/U7/walk/p024_22_03.jpg","say":"가운데 평면(3): TERRASSE라고 적힌 넓은 바닥 격자가 있어요."},{"b":[0.679,0.538,0.293,0.414],"c":[0.6643,0.5173,0.3223,0.4554],"r":0.9436,"img":"img/U7/walk/p024_22_04.jpg","say":"오른쪽 평면(4): 둥글게 휜 벽이 있는 가장 위층이에요."},{"b":[0.557,0.95,0.371,0.027],"c":[0.5385,0.89,0.4081,0.11],"r":4.9467,"img":"img/U7/walk/p024_22_05.jpg","say":"캡션: 르 코르뷔지에, 빌라 사보아, 프랑스 포와시, 1931."}]}},{"p":25,"title":"빌라 사보아(Vila Savoye) 자세히: 매스, 1층, 중정, 색, 마스터 베드룸","terms":["Villa Savoye","Pilotis","중정","sunken","chasie"],"pass1":[{"kind":"say","lines":["글만 있는 쪽이에요. **빌라 사보아(Villa Savoye)** 를 더 자세히 설명해요.","겉모습, 1층, 거실, 유리 벽과 **중정**, 색, 침실 순서로 여섯 줄이에요."]}],"pass2":[{"kind":"points","head":"겉모습과 1층","items":["메인 매스는 거의 정사각형 모양이에요. 매스는 건물의 큰 덩어리를 말해요.","가늘고 관 모양으로 된 강철 기둥들이 매스를 2층 높이로 들어 올려요. **필로티(Pilotis)** 예요.","1층 벽들은 위층의 매스 아래로 들어가도록 뒤로 물러서 있어요.","1층 벽은 유리로 되어 있거나, 시각적인 효과를 최소화시켜 주는 어두운 녹색으로 칠해져 있어요."]},{"kind":"points","head":"거실, 중정, 색","items":["커다란 거실 겸 식당 공간이 건물의 한 면에 걸치도록 길게 연장되어 있어요.","바닥부터 천장에 이르는 유리 벽은 내부의 **중정** 을 면하고, 하늘을 향해 열려 있어요.","**중정**: 건물 안쪽에 하늘로 열린 마당이에요.","벽들은 밝은 파란색과 오렌지색이에요."]},{"kind":"points","head":"마스터 베드룸의 뛰어난 인테리어","items":["타일로 된 표면, 회색 타일의 파란색 줄눈으로 된 **썬큰(sunken)** 욕조가 있어요.","**썬큰(sunken)**: 바닥보다 낮게 파 넣은 것이에요. 욕조를 바닥에 묻은 셈이에요.","빌트인된 단으로 만든 **셰이즈(chasie)** 가 있어요. 드러누울 수 있는 의자예요.","빌트인은 따로 들여놓지 않고 건물에 붙박이로 만든 것이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**빌라 사보아(Villa Savoye)** 마스터 베드룸의 욕조 설명으로 옳은 것은 무엇일까요?","choices":["회색 타일의 파란색 줄눈으로 된 썬큰 욕조","흰 대리석으로 된 다리 달린 욕조","오렌지색 타일의 둥근 욕조"],"a":0,"why":"회색 타일, 파란색 줄눈, 썬큰(sunken) 욕조예요. 색 이름 두 개를 바꿔 내기 쉬워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["제목 철자 'Vila Savoye' 는 Villa의 오타로 보여요. p.23 사진 속 글자는 Villa Savoye예요.","'chasie' 도 chaise의 오타로 보여요. 슬라이드 표기는 셰이즈(chasie)예요.","p.22 사진의 초록색 1층이 '어두운 녹색으로 칠한 1층 벽' 이에요.","벽 색은 파란색과 오렌지색, 줄눈은 파란색, 타일은 회색이에요. 짝을 섞지 마세요."]},{"kind":"english","head":"논술 답안: 빌라 사보아 내부","en":"빌라 사보아의 메인 매스는 가는 관 모양 강철 기둥들에 의해 2층 높이로 들어올려지고, 1층 벽은 뒤로 물러서 있으며, 유리 벽이 내부의 중정을 면하고, 마스터 베드룸에는 썬큰 욕조와 셰이즈가 있다.","ko":"들어 올린 매스, 물러선 1층, 중정, 침실 순서예요.","tip":"여섯 줄 첫머리를 '매스, 1층, 거실, 유리 벽, 색, 침실' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.1,0.223,0.029],"c":[0.058,0.0595,0.247,0.11],"r":2.9939,"img":"img/U7/walk/p025_23_01.jpg","say":"제목: 빌라 사보아(Vila Savoye). Villa의 오타로 보여요."},{"b":[0.068,0.152,0.865,0.093],"c":[0.0247,0.1024,0.9515,0.1922],"r":6.6008,"img":"img/U7/walk/p025_23_02.jpg","say":"메인 매스는 거의 정사각형, 강철 기둥이 2층 높이로 들어 올려요."},{"b":[0.068,0.267,0.865,0.088],"c":[0.0247,0.2149,0.9515,0.1922],"r":6.6008,"img":"img/U7/walk/p025_23_03.jpg","say":"1층 벽은 뒤로 물러서 있고, 유리나 어두운 녹색이에요."},{"b":[0.068,0.376,0.77,0.04],"c":[0.0295,0.3104,0.847,0.1711],"r":6.6004,"img":"img/U7/walk/p025_23_04.jpg","say":"거실 겸 식당이 건물 한 면을 따라 길게 이어져요."},{"b":[0.068,0.438,0.865,0.155],"c":[0.0247,0.4194,0.9515,0.1922],"r":6.6008,"img":"img/U7/walk/p025_23_05.jpg","say":"유리 벽이 내부의 중정을 면하고 하늘로 열려 있어요. 벽은 파란색과 오렌지색이에요."},{"b":[0.068,0.613,0.8,0.163],"c":[0.028,0.597,0.88,0.195],"r":6.0171,"img":"img/U7/walk/p025_23_06.jpg","say":"마스터 베드룸: 썬큰 욕조와 빌트인된 단으로 만든 셰이즈예요."}]}},{"p":26,"title":"유니테 다비타시옹(Unite d'Habitation), 프랑스 마르세이유","terms":["Unite d'Habitation","Le Corbusier","뷰-포르 구역","Modulor"],"pass1":[{"kind":"analogy","head":"세로로 세운 마을","scene":"아파트 한 동 안에 가게, 운동장, 놀이터까지 다 들어 있다고 상상해 보세요.","map":[["건물 한 동","**유니테 다비타시옹(Unite d'Habitation)**"],["집, 가게, 운동장","주거, 상점, 운동과 놀이를 위한 장소"],["마을 사람들","조선소 노동자들"]]},{"kind":"say","lines":["**르 코르뷔지에(Le Corbusier)** 의 큰 노동자 공동주택이에요.","프랑스 마르세이유에 있어요. 본문은 1952년 완공, 캡션은 1953이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**유니테 다비타시옹(Unite d'Habitation)**: 르 코르뷔지에의 대규모 노동자 공동주택이에요.","**뷰-포르 구역**: 제2차 세계대전으로 파괴된 마르세이유의 구역이에요.","단위세대: 한 가구가 사는 집 한 칸이에요.","**모듈러(Modulor)**: 사람 몸 치수에서 뽑은 르 코르뷔지에의 비례 체계예요."]},{"kind":"points","head":"슬라이드 일곱 줄 (앞 넷)","items":["마르세이유 교외에 1952년 완공된 노동자 거주 공동주택이에요.","제 2차 세계대전으로 파괴된 도시의 **뷰-포르 구역** 에 거주하던 조선소 노동자들이 대상이에요.","그들을 이주시키기 위한 대규모 주거단지 계획이에요.","마르세이유의 사회생활 전체를 재구성하기 위한 목표예요.","길이 140m 높이 24m의 큰 규모로 주거, 상점, 운동과 놀이를 위한 장소를 모두 갖춰요."]},{"kind":"points","head":"슬라이드 일곱 줄 (뒤 셋)","items":["중앙의 출입복도를 중심으로 단위세대가 이중으로 교묘하게 맞물려요.","모든 주거단위가 아침과 저녁 햇빛을 모두 받을 수 있도록 남북으로 길게 배치했어요.","부재 사용 시 척도의 조정방법은 르 코르뷔지에의 비례체계인 **모듈러(Modulor)** 예요.","사진: 칸칸이 나뉜 긴 건물이 굵은 기둥들 위에 서 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유니테 다비타시옹(Unite d'Habitation)** 의 규모로 슬라이드에 적힌 것은 무엇일까요?","choices":["길이 140m, 높이 24m","길이 1km, 높이 24m","길이 140m, 높이 56m"],"a":0,"why":"길이 140m, 높이 24m예요. 1km는 5단원 칼 마르크스 호프 블록의 길이예요."},{"kind":"check","q":"**유니테 다비타시옹(Unite d'Habitation)** 을 남북으로 길게 놓은 까닭은 무엇일까요?","choices":["모든 주거단위가 아침과 저녁 햇빛을 모두 받도록","바닷바람을 막으려고","도로가 남북으로 나 있어서"],"a":0,"why":"슬라이드 그대로 '아침과 저녁 햇빛을 모두 받을 수 있도록' 이에요."},{"kind":"warn","head":"연도 함정","items":["본문은 '1952년 완공' 이에요.","캡션(p.26, p.29)은 1953, p.30 영어 캡션은 1947-53, p.28 스케치 글자는 1952예요.","답안에는 본문 문장 '1952년 완공' 을 쓰고, 나머지 숫자도 알아 두세요.","제목의 따옴표(’)와 d’ 뒤 띄어쓰기는 원본 표기예요. 같은 건물 이름이에요."]},{"kind":"english","head":"논술 답안: 유니테 다비타시옹 개요","en":"유니테 다비타시옹은 마르세이유 교외에 1952년 완공된 노동자 거주 공동주택으로, 뷰-포르 구역 조선소 노동자의 이주를 위해 계획되었고, 길이 140m 높이 24m에 주거, 상점, 운동과 놀이 장소를 모두 갖춘다.","ko":"언제, 어디, 누구를 위해, 얼마나 큰지 순서예요.","tip":"'일사공(140) 이사(24)' 로 크기를 외워요."}],"walk":{"head":null,"parts":[{"b":[0.057,0.06,0.6,0.11],"c":[0.027,0.044,0.66,0.142],"r":6.1972,"img":"img/U7/walk/p026_23_01.jpg","say":"제목과 첫 줄: 마르세이유 교외에 1952년 완공된 노동자 거주 공동주택."},{"b":[0.057,0.188,0.905,0.155],"c":[0.0045,0.1649,0.9955,0.2011],"r":6.6004,"img":"img/U7/walk/p026_23_02.jpg","say":"뷰-포르 구역의 조선소 노동자 이주, 사회생활 전체의 재구성."},{"b":[0.057,0.362,0.87,0.04],"c":[0.0135,0.2853,0.957,0.1933],"r":6.6011,"img":"img/U7/walk/p026_23_03.jpg","say":"길이 140m, 높이 24m. 주거, 상점, 운동과 놀이 장소를 모두 갖춰요."},{"b":[0.057,0.422,0.79,0.162],"c":[0.0175,0.406,0.869,0.194],"r":5.9725,"img":"img/U7/walk/p026_23_04.jpg","say":"출입복도 중심의 맞물림, 남북으로 길게 배치, 모듈러 사용."},{"b":[0.501,0.598,0.401,0.397],"c":[0.4809,0.5633,0.4411,0.4367],"r":1.3468,"img":"img/U7/walk/p026_23_05.jpg","say":"사진: 굵은 기둥 위의 칸칸이 나뉜 긴 건물이에요."},{"b":[0.032,0.955,0.454,0.029],"c":[0.0093,0.89,0.4994,0.11],"r":6.0533,"img":"img/U7/walk/p026_23_06.jpg","say":"캡션: 르 코르뷔지에, 유니테 다비타시옹, 프랑스 마르세이유, 1953."}]}},{"p":27,"title":"유니테 다비타시옹: 르 꼬르뷔제의 기본접근과 짓는 방법","terms":["Unite d'Habitation","Soleil","Espace","Verdure","중복도","복층","시트로앵 하우스","녹지 위의 고층주거","Pilotis","철근 콘크리트","in situ","prefabrication","Modulor"],"pass1":[{"kind":"say","lines":["**유니테 다비타시옹(Unite d'Habitation)** 을 지은 생각과 짓는 방법이에요.","생각은 세 단어예요. 해, 공간, 초록. 프랑스어로 Soleil, Espace, Verdure예요."]}],"pass2":[{"kind":"points","head":"르 꼬르뷔제의 기본접근 세 가지","items":["**채광(Soleil)**: **중복도** 와 **복층** 주택 구성으로 모든 주거단위에 적극적 채광을 도입해요.","공간(**Espace**): 시트로앵(**시트로앵 하우스**)의 설계원리를 근거로 중층의 거실을 도입해요.","**녹지(Verdure)**: '**녹지 위의 고층주거**' 개념, 거대한 **필로티(Pilotis)** 예요."]},{"kind":"points","head":"이 쪽의 용어 뜻","items":["**중복도**: 건물 가운데를 지나는 복도예요. 복도 양쪽에 집이 붙어요.","**복층**: 한 집이 위아래 두 층을 함께 쓰는 구성이에요.","중층의 거실: 층을 겹쳐 높게 쓰는 거실이에요. **시트로앵 하우스** 의 '상하층으로 분리된 거실' 과 이어져요.","**녹지 위의 고층주거**: 건물을 높이 세우고 땅은 녹지로 비워 두는 생각이에요."]},{"kind":"points","head":"짓는 방법","items":["**철근 콘크리트** 기둥과 보로 이루어진 '**인 시트(in situ)** 구조' 예요. 현장에서 콘크리트를 부어 만들어요.","반복적인 외피들은 콘크리트로 미리 성형되어 각 위치에 올려졌어요.","이것이 **미리 만들어진 부재사용(prefabrication)** 이에요.","'**모듈러(Modulor)**' 원리로 부재의 표준화, 규격화를 했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"유니테 기본접근 세 단어와 뜻의 짝으로 틀린 것은 무엇일까요?","choices":["Soleil, 채광","Espace, 공간","Verdure, 복층"],"a":2,"why":"Verdure는 **녹지(Verdure)** 예요. 복층은 **채광(Soleil)** 설명 안에 나와요."},{"kind":"check","q":"현장에서 콘크리트를 부어 만든 기둥과 보 구조를 무엇이라 할까요?","choices":["**인 시트(in situ)** 구조","**미리 만들어진 부재사용(prefabrication)**","**도미노 시스템(Dom-ino)**"],"a":0,"why":"인 시트(in situ)예요. 미리 성형해 올린 외피는 prefabrication이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**인 시트(in situ)** 는 기둥과 보, **미리 만들어진 부재사용(prefabrication)** 은 반복적인 외피예요.","유니테 다비타시옹은 두 방법을 함께 써요. 하나만 골라 쓰면 틀려요.","기본접근의 '공간' 은 영어가 아니라 프랑스어 Espace로 적혀 있어요."]},{"kind":"english","head":"논술 답안: 기본접근과 구법","en":"유니테 다비타시옹은 채광(Soleil), 공간(Espace), 녹지(Verdure)를 기본접근으로 하며, 철근 콘크리트 인 시트 구조에 미리 만들어진 부재(prefabrication)를 쓰고 모듈러 원리로 부재를 표준화, 규격화하였다.","ko":"기본접근 셋, 구조, 외피, 모듈러 순서예요.","tip":"'해, 공간, 초록' 다음에 '현장 뼈대, 미리 껍데기, 모듈러 치수' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.078,0.34,0.03],"c":[0.033,0.038,0.374,0.11],"r":4.5333,"img":"img/U7/walk/p027_23_01.jpg","say":"제목: 유니테다비타시옹(Unite d’Habitation). 여기는 붙여 썼어요."},{"b":[0.087,0.18,0.82,0.225],"c":[0.046,0.164,0.902,0.257],"r":4.6796,"img":"img/U7/walk/p027_23_02.jpg","say":"기본접근 세 가지: 채광(Soleil), 공간(Espace), 녹지(Verdure)."},{"b":[0.087,0.42,0.6,0.045],"c":[0.057,0.3758,0.66,0.1333],"r":6.6017,"img":"img/U7/walk/p027_23_03.jpg","say":"철근 콘크리트 기둥과 보의 인 시트(in situ) 구조예요."},{"b":[0.087,0.482,0.65,0.04],"c":[0.0545,0.4298,0.715,0.1445],"r":6.5975,"img":"img/U7/walk/p027_23_04.jpg","say":"반복적인 외피는 콘크리트로 미리 성형해 올렸어요."},{"b":[0.087,0.543,0.4,0.04],"c":[0.067,0.508,0.44,0.11],"r":5.3333,"img":"img/U7/walk/p027_23_05.jpg","say":"미리 만들어진 부재사용(prefabrication)."},{"b":[0.087,0.6,0.37,0.04],"c":[0.0685,0.565,0.407,0.11],"r":4.9333,"img":"img/U7/walk/p027_23_06.jpg","say":"모듈러 원리: 부재의 표준화, 규격화."}]}},{"p":28,"title":"유니테 다비타시옹의 거대한 필로티와 배치 스케치 (캡션 없는 슬라이드)","terms":["Unite d'Habitation","Pilotis","Verdure","녹지 위의 고층주거","Le Corbusier","철근 콘크리트"],"pass1":[{"kind":"say","lines":["사진 세 장과 스케치 한 장이에요. 캡션 줄은 없어요.","**유니테 다비타시옹(Unite d'Habitation)** 의 아래와 바깥을 보여 줘요.","굵은 다리 같은 기둥 위에 큰 건물이 얹혀 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것","items":["위 사진: 건물 아래예요. 아래로 갈수록 좁아지는 굵은 콘크리트 기둥이 줄지어 서 있어요.","기둥 사이로 건너편 잔디밭이 보여요. 건물 아래 땅을 비워 둔 거예요.","가운데 흑백 사진: 칸칸이 나뉜 발코니 격자 벽의 높은 건물이 굵은 기둥 위에 떠 있어요.","오른쪽 사진: 거친 콘크리트 면 사이로 발코니 안쪽에 칠한 색 면이 보여요.","왼쪽 스케치: 길쭉한 건물의 배치 그림이에요. 아래에 'Unité d'Habitation, 1952 Le Corbusier' 라고 적혀 있어요."]},{"kind":"points","head":"p.27, p.2와 맞춰 보기","items":["p.27 **녹지(Verdure)** 의 '거대한 **필로티(Pilotis)**' 가 위 사진의 굵은 기둥이에요.","기둥 위에 건물을 들고 땅은 비워 두는 생각이 '**녹지 위의 고층주거**' 예요.","p.2는 **르 코르뷔지에(Le Corbusier)** 를 거친 마감 콘크리트 사용을 연구한 최초의 건축가로 소개했어요.","오른쪽 사진의 거친 **철근 콘크리트** 면이 그 말과 이어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유니테 다비타시옹(Unite d'Habitation)** 의 거대한 **필로티(Pilotis)** 는 기본접근 세 가지 중 어디에 속할까요?","choices":["채광(Soleil)","공간(Espace)","녹지(Verdure)"],"a":2,"why":"p.27 '녹지(Verdure): 녹지 위의 고층주거 개념, 거대한 필로티' 예요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 쪽에는 캡션 줄이 없어요. 스케치 속 글자 1952만 적혀 있어요.","사진 위 파란 손글씨는 슬라이드 원문이 아니에요. 시험 사실로 외우지 마세요."]}],"walk":{"head":null,"parts":[{"b":[0.413,0.016,0.555,0.373],"c":[0.3852,0,0.6105,0.4103],"r":1.9839,"img":"img/U7/walk/p028_22_01.jpg","say":"위 사진: 건물 아래의 굵은 콘크리트 기둥들이에요. 거대한 필로티예요."},{"b":[0.035,0.407,0.266,0.553],"c":[0.0217,0.3793,0.2926,0.6083],"r":0.6414,"img":"img/U7/walk/p028_22_02.jpg","say":"왼쪽 스케치: 길쭉한 건물의 배치 그림이에요."},{"b":[0.035,0.905,0.266,0.055],"c":[0.0217,0.8775,0.2926,0.11],"r":3.5467,"img":"img/U7/walk/p028_22_03.jpg","say":"스케치 글자: Unité d'Habitation, 1952 Le Corbusier."},{"b":[0.35,0.412,0.284,0.55],"c":[0.3358,0.3845,0.3124,0.605],"r":0.6885,"img":"img/U7/walk/p028_22_04.jpg","say":"가운데 사진: 발코니 격자 벽의 높은 건물이 굵은 기둥 위에 떠 있어요."},{"b":[0.681,0.412,0.276,0.55],"c":[0.6672,0.3845,0.3036,0.605],"r":0.6691,"img":"img/U7/walk/p028_22_05.jpg","say":"오른쪽 사진: 거친 콘크리트 면과 발코니 안쪽의 색 면이에요."}]}},{"p":29,"title":"유니테 다비타시옹 입체 그림, 옥상, 단면","terms":["Unite d'Habitation","중복도","복층","Soleil"],"pass1":[{"kind":"say","lines":["큰 입체 그림, 옥상 사진 두 장, 단면 그림 한 장이에요.","건물을 잘라서 속을 보여 줘요. 집들이 복도를 사이에 두고 맞물려요."]},{"kind":"analogy","head":"지퍼처럼 맞물린 집","scene":"지퍼 이빨이 양쪽에서 엇갈려 맞물리듯, 집들이 위아래로 엇갈려 끼워져 있어요.","map":[["가운데 지퍼 줄","중앙의 출입복도, 곧 **중복도**"],["양쪽에서 엇갈린 이빨","위아래 두 층을 쓰는 **복층** 단위세대"]]}],"pass2":[{"kind":"points","head":"그림에서 보이는 것","items":["캡션: 르 코르뷔지에, 유니테 다비타시옹, 프랑스 마르세이유, 1953.","왼쪽 입체 그림: 굵은 기둥 위에 칸칸이 나뉜 긴 건물이에요. 옥상에 탑과 덩어리들이 솟아 있어요.","입체 그림 오른쪽 아래에는 집 한 칸을 서랍처럼 빼낸 모습이 그려져 있어요.","오른쪽 위, 가운데 사진: 옥상이에요. 둥글고 굵은 콘크리트 탑과 낮은 벽이 보여요.","오른쪽 아래 단면: 가운데 복도를 사이에 두고 두 집이 위아래로 엇갈려 맞물려 있어요."]},{"kind":"points","head":"p.26, p.27과 맞춰 보기","items":["p.26 '중앙의 출입복도를 중심으로 단위세대가 이중으로 교묘하게 맞물림' 을 단면이 보여 줘요.","p.27 **채광(Soleil)**: **중복도** 와 **복층** 주택 구성으로 모든 주거단위에 빛을 들여요.","단면을 보면 한 집이 건물의 양쪽 바깥 면까지 닿아요.","그래서 p.26처럼 모든 주거단위가 아침 햇빛과 저녁 햇빛을 모두 받을 수 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**중복도** 의 뜻으로 옳은 것은 무엇일까요?","choices":["건물 가운데를 지나는 복도","건물 바깥에 매단 복도","지붕 위의 산책길"],"a":0,"why":"건물 가운데를 지나는 복도예요. 양쪽에 집이 붙어요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["그림 위 파란 손글씨는 슬라이드 원문이 아니에요.","**중복도** 와 **복층** 은 p.27 슬라이드 글자로 외우고, 이 쪽 그림은 그 모습을 보는 데 써요."]}],"walk":{"head":null,"parts":[{"b":[0.125,0.024,0.4,0.914],"c":[0.105,0,0.44,1],"r":0.5867,"img":"img/U7/walk/p029_22_01.jpg","say":"왼쪽 입체 그림: 굵은 기둥 위의 긴 건물이에요."},{"b":[0.39,0.54,0.14,0.15],"c":[0.36,0.524,0.2,0.182],"r":1.4652,"img":"img/U7/walk/p029_22_02.jpg","say":"집 한 칸을 서랍처럼 빼낸 모습이에요."},{"b":[0.666,0.01,0.327,0.446],"c":[0.6403,0,0.3597,0.4906],"r":0.9776,"img":"img/U7/walk/p029_22_03.jpg","say":"오른쪽 위 사진: 옥상의 굵은 콘크리트 탑이에요."},{"b":[0.666,0.465,0.327,0.292],"c":[0.6403,0.449,0.3597,0.324],"r":1.4802,"img":"img/U7/walk/p029_22_04.jpg","say":"가운데 사진: 옥상의 탑과 낮은 벽들이에요."},{"b":[0.538,0.765,0.455,0.211],"c":[0.4995,0.749,0.5005,0.243],"r":2.7462,"img":"img/U7/walk/p029_22_05.jpg","say":"단면: 가운데 복도를 사이에 두고 두 집이 엇갈려 맞물려요."},{"b":[0.032,0.955,0.454,0.029],"c":[0.0093,0.89,0.4994,0.11],"r":6.0533,"img":"img/U7/walk/p029_22_06.jpg","say":"캡션: 르 코르뷔지에, 유니테 다비타시옹, 프랑스 마르세이유, 1953."}]}},{"p":30,"title":"Unite d'Habitation, Marseille, 1947-53 실내 세 컷","terms":["Unite d'Habitation","Le Corbusier"],"pass1":[{"kind":"say","lines":["영어 캡션 한 줄과 실내 사진 세 장이에요.","캡션은 'Unite d'Habitation, Marseille, 1947-53' 이에요.","**유니테 다비타시옹(Unite d'Habitation)** 안에서 사람들이 사는 모습이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것","items":["왼쪽 위: 높은 곳에서 내려다본 집 안이에요. 아이들과 어른이 바닥에서 놀고 일해요.","벽에 파란 선반 칸이 파여 있고, 오렌지색 방석과 바구니가 놓여 있어요.","왼쪽 아래: 넓은 방이에요. 빨간 벽, 반짝이는 타일 바닥, 굵은 콘크리트 기둥과 보가 보여요.","오른쪽 아래: 길게 뻗은 복도 같은 공간이에요. 한쪽 면이 큰 유리창이고 끝에 빨간 벽이 있어요.","어떤 방인지는 슬라이드에 적혀 있지 않아요. 보이는 것만 기억해요."]},{"kind":"compare","head":"마르세이유 유니테 연도, 어디에 무엇이 적혀 있나","cols":["어디에","적힌 연도"],"rows":[["p.26 본문","1952년 완공"],["p.26, p.29 캡션","1953"],["p.28 스케치 글자","1952"],["p.30 영어 캡션","1947-53"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"p.30 영어 캡션에 적힌 **유니테 다비타시옹(Unite d'Habitation)** 연도는 무엇일까요?","choices":["1947-53","1952","1958"],"a":0,"why":"1947-53이에요. 1952는 본문 완공 연도, 1958은 베를린 유니테예요."},{"kind":"english","head":"논술 답안: 르 코르뷔지에 1920년대에서 유니테까지","en":"르 코르뷔지에는 1920년대 흰 주택과 빌라 사보아(1931)에서 필로티와 수평띠창을 쓴 하얀 입방체를 만들었고, 마르세이유의 유니테 다비타시옹(1952년 완공)에서는 거대한 필로티 위에 노동자 공동주택을 세웠다.","ko":"흰 상자에서 큰 공동주택으로 넘어가는 흐름을 한 문장에 담았어요.","tip":"주문을 떠올려요. 기계 시대에 건축은 어떻게 생겨야 하나? 르 코르뷔지에의 답은 '상자를 기둥 위로' 예요."}],"walk":{"head":null,"parts":[{"b":[0.627,0.025,0.305,0.03],"c":[0.6118,0,0.3355,0.11],"r":4.0667,"img":"img/U7/walk/p030_22_01.jpg","say":"캡션: Unite d'Habitation, Marseille, 1947-53."},{"b":[0.007,0.01,0.452,0.405],"c":[0,0,0.4972,0.4455],"r":1.4881,"img":"img/U7/walk/p030_22_02.jpg","say":"왼쪽 위: 내려다본 집 안, 파란 선반 칸과 오렌지색 방석이에요."},{"b":[0.141,0.424,0.423,0.565],"c":[0.1198,0.3785,0.4653,0.6215],"r":0.9982,"img":"img/U7/walk/p030_22_03.jpg","say":"왼쪽 아래: 빨간 벽과 타일 바닥, 콘크리트 기둥과 보예요."},{"b":[0.57,0.424,0.423,0.565],"c":[0.5347,0.3785,0.4653,0.6215],"r":0.9982,"img":"img/U7/walk/p030_22_04.jpg","say":"오른쪽 아래: 한쪽이 큰 유리창인 긴 복도 같은 공간이에요."}]}},{"p":31,"title":"유니테 다비타시옹 베를린, 1958","terms":["Unite d'Habitation","Le Corbusier","Verdure","녹지 위의 고층주거","Karl Marx Hof"],"pass1":[{"kind":"say","lines":["넓은 공원 너머로 길쭉한 흰 아파트 한 동이 서 있어요.","**르 코르뷔지에(Le Corbusier)** 의 **유니테 다비타시옹(Unite d'Habitation)** 이에요.","이번에는 마르세이유가 아니라 독일 베를린, 1958년이에요.","같은 이름의 건물이 다른 도시에도 지어졌다는 이야기예요."]},{"kind":"say","lines":["5단원 **칼 마르크스 호프(Karl Marx Hof)** 는 옆으로 1km 길게 늘어선 단지였어요.","유니테는 주거, 상점, 놀이 장소를 한 동에 담은 '세로로 세운 마을' 이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["제목 줄은 '유니테 다비타시옹(Unite d' Habitation) 베를린' 이에요.","캡션은 르 코르뷔지에, 유니테 다비타시옹, 독일 베를린, 1958이에요.","앞에서 본 마르세이유 건물은 1952년 완공이었어요. 베를린은 6년 뒤예요.","건물은 숲과 잔디 사이에 높이 솟아 있어요. 앞에는 둥근 광장과 도로가 보여요.","p.27 **녹지(Verdure)** 의 '**녹지 위의 고층주거**' 를 떠올리면 돼요."]},{"kind":"compare","head":"마르세이유와 베를린","cols":["","마르세이유","베를린"],"rows":[["나라, 도시","프랑스 마르세이유","독일 베를린"],["연도","본문 1952년 완공 (캡션 1953, 영어 캡션 1947-53)","캡션 1958"],["캡션이 있는 쪽","p.26, p.29, p.30","p.31, p.33, p.35, p.36"]]},{"kind":"bg","src":"배경 지식","lines":["Unite d'Habitation 은 프랑스어로 '주거 단위' 라는 뜻이에요.","5단원 **칼 마르크스 호프(Karl Marx Hof)** 처럼 노동자를 위한 큰 주거를 이어받은 셈이에요.","마르세이유 유니테는 조선소 노동자를 위한 공동주택이었어요(p.26)."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"베를린에 있는 **유니테 다비타시옹(Unite d'Habitation)** 캡션의 연도는 무엇일까요?","choices":["1952","1958","1931"],"a":1,"why":"베를린은 1958년이에요. 1952는 마르세이유 완공, 1931은 빌라 사보아예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**유니테 다비타시옹(Unite d'Habitation)** 은 한 채가 아니에요. 마르세이유와 베를린이 둘 다 나와요.","마르세이유는 본문 1952년 완공, 캡션 1953, 영어 캡션 1947-53이에요.","베를린은 캡션 1958이에요.","제목의 따옴표(다비타시옹')와 d' 뒤 띄어쓰기는 슬라이드 표기 실수로 보여요."]}],"walk":{"head":null,"parts":[{"b":[0.068,0.05,0.43,0.045],"c":[0.0465,0.0175,0.473,0.11],"r":5.7333,"img":"img/U7/walk/p031_23_01.jpg","say":"제목: 유니테 다비타시옹(Unite d' Habitation) 베를린."},{"b":[0.075,0.112,0.83,0.835],"c":[0.0335,0.0702,0.913,0.9185],"r":1.3253,"img":"img/U7/walk/p031_23_02.jpg","say":"사진: 공원과 도로 너머로 본 건물 전체예요."},{"b":[0.42,0.44,0.255,0.155],"c":[0.4073,0.424,0.2805,0.187],"r":2.0,"img":"img/U7/walk/p031_23_03.jpg","say":"길쭉한 판 모양 건물이에요. 칸이 줄지어 반복돼요."},{"b":[0.38,0.963,0.41,0.03],"c":[0.3595,0.89,0.451,0.11],"r":5.4667,"img":"img/U7/walk/p031_23_04.jpg","say":"캡션: 르 코르뷔지에, 유니테 다비타시옹, 독일 베를린, 1958."}]}},{"p":32,"title":"베를린 유니테의 색 발코니와 주변 풍경 (글자 없는 슬라이드)","terms":["Unite d'Habitation","Pilotis","Verdure"],"pass1":[{"kind":"say","lines":["이 슬라이드에는 캡션이 없어요. 사진 세 장뿐이에요.","앞뒤 쪽이 베를린 **유니테 다비타시옹(Unite d'Habitation)** 이라서 같은 건물 이야기로 봐요.","발코니 옆벽이 빨강, 노랑, 파랑, 초록으로 칠해져 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["오른쪽 위: 비스듬히 본 긴 건물이에요. 발코니 옆벽마다 원색이 칠해져 있어요.","옥상 위에 안테나와 작은 덩어리가 올라가 있어요.","왼쪽 아래: 건물 정면 전체예요. 가운데 세로로 솟은 덩어리가 건물을 둘로 나눠요.","맨 아래층은 기둥 사이가 비어 있고 그 앞이 주차장이에요. **필로티(Pilotis)** 로 들어 올린 모습이에요.","오른쪽 아래: 높은 곳에서 내려다본 풍경이에요. 숲과 빨간 지붕, 먼 도시가 보여요.","숲이 넓게 펼쳐진 모습이 **녹지(Verdure)** 라는 기본접근을 떠올리게 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"베를린 **유니테 다비타시옹(Unite d'Habitation)** 사진에서 발코니 옆벽의 모습으로 맞는 것은?","choices":["빨강, 노랑, 파랑 같은 원색으로 칠해져 있다","벽돌로 요철을 만들었다","금색 판을 붙였다"],"a":0,"why":"원색으로 칠한 발코니가 베를린 유니테의 눈에 띄는 모습이에요. 벽돌 요철은 6단원 베델 주거단지, 금색 판은 베를린 필하모니 홀이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 캡션이 없어요.","도시와 연도는 p.31, p.33 캡션에서 가져와요. 독일 베를린, 1958이에요.","사진 위 파란 손글씨는 누군가의 필기예요. 슬라이드 내용이 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.326,0.01,0.647,0.522],"c":[0.2883,0,0.7117,0.5742],"r":1.6526,"img":"img/U7/walk/p032_21_01.jpg","say":"오른쪽 위: 비스듬히 본 긴 건물이에요."},{"b":[0.425,0.205,0.26,0.233],"c":[0.412,0.189,0.286,0.265],"r":1.439,"img":"img/U7/walk/p032_21_02.jpg","say":"발코니 옆벽에 빨강, 노랑, 파랑, 초록이 칠해져 있어요."},{"b":[0.059,0.562,0.453,0.4],"c":[0.0363,0.542,0.4983,0.44],"r":1.51,"img":"img/U7/walk/p032_21_03.jpg","say":"왼쪽 아래: 건물 정면 전체예요."},{"b":[0.064,0.852,0.447,0.062],"c":[0.0416,0.828,0.4917,0.11],"r":5.96,"img":"img/U7/walk/p032_21_04.jpg","say":"맨 아래층은 기둥 사이가 비어 있어요. 필로티예요."},{"b":[0.547,0.562,0.389,0.39],"c":[0.5276,0.5425,0.4279,0.429],"r":1.3299,"img":"img/U7/walk/p032_21_05.jpg","say":"오른쪽 아래: 높은 곳에서 내려다본 숲과 도시예요."}]}},{"p":33,"title":"색 판을 단 베를린 유니테의 정면, 1958","terms":["Unite d'Habitation","Le Corbusier","Modulor","prefabrication"],"pass1":[{"kind":"say","lines":["건물 정면을 가까이 찍은 사진 한 장이에요.","똑같은 크기의 칸이 바둑판처럼 끝없이 반복돼요.","칸마다 빨강, 검정, 청록 색 판이 비스듬히 나뉘어 칠해져 있어요."]},{"kind":"analogy","head":"같은 크기 블록 쌓기","scene":"같은 크기 레고 블록을 줄지어 쌓은 벽을 떠올려요.","map":[["같은 크기 블록","같은 크기로 반복되는 집 한 칸"],["블록마다 다른 색 스티커","칸마다 다른 색 판"],["블록 크기를 정하는 자","**모듈러(Modulor)** 비례"]]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["캡션은 르 코르뷔지에, 유니테 다비타시옹, 독일 베를린, 1958이에요.","같은 크기의 집 칸이 가로세로로 반복돼요.","층마다 구멍이 촘촘한 격자 난간이 띠처럼 이어져요.","칸 안쪽 벽은 대각선으로 나뉘어 빨강, 검정, 청록, 흰색으로 칠해져 있어요.","왼쪽 가운데 한 줄은 발코니 대신 가는 세로 날개벽이 촘촘히 서 있어요."]},{"kind":"points","head":"p.27과 이어 보기","items":["**유니테 다비타시옹(Unite d'Habitation)** 의 반복적인 외피들은 콘크리트로 미리 성형되어 각 위치에 올려졌어요.","이것이 **미리 만들어진 부재사용(prefabrication)** 이에요.","**모듈러(Modulor)** 원리로 부재를 표준화, 규격화했어요.","이 설명을 떠올리며 보면 똑같이 반복되는 칸이 눈에 들어와요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유니테 다비타시옹(Unite d'Habitation)** 의 반복적인 외피는 어떻게 만들었을까요?","choices":["현장에서 손으로 벽돌을 쌓았다","콘크리트로 미리 성형해 각 위치에 올렸다","유리 커튼월로 덮었다"],"a":1,"why":"반복적인 외피는 콘크리트로 미리 성형되어 각 위치에 올려졌어요. 미리 만들어진 부재사용(prefabrication)이에요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.067,0.859,0.859],"c":[0.0071,0.0241,0.9449,0.9449],"r":1.3333,"img":"img/U7/walk/p033_22_01.jpg","say":"정면 사진: 같은 크기 칸이 가로세로로 반복돼요."},{"b":[0.05,0.452,0.407,0.09],"c":[0.0297,0.436,0.4477,0.122],"r":4.8929,"img":"img/U7/walk/p033_22_02.jpg","say":"이 줄은 발코니 대신 가는 세로 날개벽이 촘촘해요."},{"b":[0.05,0.62,0.859,0.035],"c":[0.0071,0.542,0.9449,0.1909],"r":6.5996,"img":"img/U7/walk/p033_22_03.jpg","say":"층 사이를 잇는 격자 난간 띠예요."},{"b":[0.1,0.762,0.809,0.095],"c":[0.0596,0.7196,0.8899,0.1798],"r":6.5992,"img":"img/U7/walk/p033_22_04.jpg","say":"칸마다 대각선으로 나눈 색 판이에요."},{"b":[0.384,0.962,0.405,0.03],"c":[0.3638,0.89,0.4455,0.11],"r":5.4,"img":"img/U7/walk/p033_22_05.jpg","say":"캡션: 르 코르뷔지에, 유니테 다비타시옹, 독일 베를린, 1958."}]}},{"p":34,"title":"발코니 칸 클로즈업 (글자 없는 슬라이드)","terms":["Unite d'Habitation","prefabrication","Modulor"],"pass1":[{"kind":"say","lines":["글자도 캡션도 없는 사진 한 장이에요.","앞 쪽 **유니테 다비타시옹(Unite d'Habitation)** 정면을 더 가까이 당겨 찍은 모습이에요.","창, 색 판, 격자 난간이 한 칸에 어떻게 들어가는지 보는 쪽이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["한 칸 위쪽에는 가로로 긴 유리창이 있어요.","창 아래 벽은 대각선으로 나뉘어 두세 가지 색으로 칠해져 있어요.","칸을 나누는 옆벽 안쪽에도 노랑, 파랑, 빨강 같은 색이 칠해져 있어요.","층과 층 사이에는 네모 구멍이 촘촘한 격자 난간이 띠처럼 이어져요.","줄무늬 차양을 내린 집, 화분을 내놓은 집도 보여요. 사람이 사는 집이에요.","칸 모양이 모두 같아요. p.33 의 **모듈러(Modulor)** 와 반복 외피 이야기를 떠올려요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 글자가 하나도 없어요.","건물 이름과 도시, 연도는 p.33 캡션에서 가져와요. 베를린, 1958이에요.","색의 뜻이나 칸 치수는 슬라이드에 없어요. 지어서 외우지 않아요.","반복 외피를 미리 만들어 올린 방식은 **미리 만들어진 부재사용(prefabrication)** 이에요(p.27)."]}],"walk":{"head":null,"parts":[{"b":[0.0,0.0,0.214,0.248],"c":[0,0,0.238,0.28],"r":1.1333,"img":"img/U7/walk/p034_21_01.jpg","say":"한 칸: 위는 유리창, 아래는 색 판이에요."},{"b":[0.207,0.0,0.036,0.238],"c":[0.125,0,0.2,0.27],"r":0.9877,"img":"img/U7/walk/p034_21_02.jpg","say":"칸 옆벽 안쪽이 노랗게 칠해져 있어요."},{"b":[0.0,0.233,1.0,0.09],"c":[0.0,0.1669,1,0.2222],"r":6.0006,"img":"img/U7/walk/p034_21_03.jpg","say":"층 사이 격자 난간 띠예요."},{"b":[0.014,0.519,0.184,0.024],"c":[0.002,0.476,0.208,0.11],"r":2.5212,"img":"img/U7/walk/p034_21_04.jpg","say":"노란 줄 차양을 내린 집이에요."},{"b":[0.675,0.438,0.218,0.105],"c":[0.663,0.422,0.242,0.137],"r":2.3552,"img":"img/U7/walk/p034_21_05.jpg","say":"대각선으로 나눈 흰색과 빨간색 판이에요."}]}},{"p":35,"title":"모듈러 부조, SOLEIL, ESPACE, VERDURE, 거대한 필로티","terms":["Modulor","Soleil","Espace","Verdure","녹지 위의 고층주거","Pilotis","Unite d'Habitation"],"pass1":[{"kind":"say","lines":["사진 네 장이에요. 위 두 장은 건물 벽에 새긴 그림이에요.","왼쪽 위에 한 팔을 든 사람과 숫자 113, 140, 183, 226이 새겨져 있어요.","이 사람이 **모듈러(Modulor)** 예요. 사람 몸 치수로 만든 비례 자예요.","아래 두 장은 건물을 받친 커다란 기둥, **필로티(Pilotis)** 예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**모듈러(Modulor)**: 사람 몸 치수에서 뽑은 르 코르뷔지에의 비례 체계예요.","부조: 벽면에 모양을 도드라지게 새긴 조각이에요.","**필로티(Pilotis)**: 건물을 기둥으로 들어 올려 아래를 비우는 방식이에요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["캡션은 르 코르뷔지에, 유니테 다비타시옹, 독일 베를린, 1958이에요.","모듈러 인체 부조 옆 막대에 113, 140, 183, 226 숫자가 적혀 있어요.","오른쪽 위 벽에는 해, 구름 모양, 나무가 새겨져 있어요.","그 옆 글자가 SOLEIL, ESPACE, VERDURE예요. p.27 기본접근 세 단어와 같아요.","아래 사진: 굵은 기둥이 비스듬히 벌어지며 건물을 들어 올려요. 거대한 **필로티(Pilotis)** 예요.","필로티 아래 빈 땅에는 차들이 서 있어요."]},{"kind":"compare","head":"벽에 새긴 세 단어와 p.27 기본접근","cols":["벽 글자","기본접근","내용"],"rows":[["SOLEIL (해 그림)","**채광(Soleil)**","중복도와 복층주택 구성으로 모든 주거단위에 적극적 채광도입"],["ESPACE (구름 모양)","**Espace**(공간)","시트로앵의 설계원리를 근거로 중층의 거실 도입"],["VERDURE (나무 그림)","**녹지(Verdure)**","'**녹지 위의 고층주거**' 개념, 거대한 필로티"]]},{"kind":"bg","src":"배경 지식","lines":["모듈러 숫자의 단위는 센티미터(cm)예요.","183은 사람 키, 226은 손을 들어 올린 높이, 113은 배꼽 높이로 알려져 있어요.","슬라이드에는 숫자만 있어요. 시험에는 숫자 네 개를 그대로 외워요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"베를린 **유니테 다비타시옹(Unite d'Habitation)** 외벽의 모듈러 부조 옆 숫자가 아닌 것은?","choices":["113","183","226","300"],"a":3,"why":"부조 숫자는 113, 140, 183, 226이에요. 300은 '인구 300만의 현대도시' 의 숫자예요."},{"kind":"check","q":"벽에 새긴 VERDURE 와 짝이 맞는 기본접근 내용은 무엇일까요?","choices":["중복도와 복층주택 구성","시트로앵의 설계원리로 중층의 거실 도입","'녹지 위의 고층주거' 개념, 거대한 필로티"],"a":2,"why":"VERDURE 는 **녹지(Verdure)** 예요. '녹지 위의 고층주거' 개념과 거대한 필로티예요."},{"kind":"english","head":"논술 답안: 유니테 다비타시옹의 기본접근","en":"유니테 다비타시옹은 채광(Soleil), 공간(Espace), 녹지(Verdure)를 기본접근으로, 중복도와 복층으로 채광을, 중층의 거실, 녹지 위의 고층주거와 거대한 필로티를 두었다.","ko":"해, 공간, 초록 세 단어마다 내용 하나씩 붙여 써요.","tip":"베를린 외벽 글자 SOLEIL, ESPACE, VERDURE 그림(해, 구름, 나무)으로 외워요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["부조 옆 흰 손글씨 '모듈러' 는 필기예요. 슬라이드 원문은 캡션과 부조 속 글자뿐이에요."]}],"walk":{"head":null,"parts":[{"b":[0.405,0.017,0.272,0.482],"c":[0.3914,0,0.2992,0.5302],"r":0.7524,"img":"img/U7/walk/p035_24_01.jpg","say":"모듈러 인체 부조: 한 팔을 들어 올린 사람이에요."},{"b":[0.446,0.052,0.09,0.405],"c":[0.391,0.0318,0.2,0.4455],"r":0.5986,"img":"img/U7/walk/p035_24_02.jpg","say":"막대 위 숫자 113, 140, 183, 226이에요."},{"b":[0.696,0.017,0.271,0.48],"c":[0.6824,0,0.2981,0.528],"r":0.7528,"img":"img/U7/walk/p035_24_03.jpg","say":"해, 구름 모양, 나무 부조와 SOLEIL, ESPACE, VERDURE 글자예요."},{"b":[0.027,0.511,0.414,0.414],"c":[0.0063,0.4903,0.4554,0.4554],"r":1.3333,"img":"img/U7/walk/p035_24_04.jpg","say":"굵은 기둥이 건물을 들어 올렸어요. 거대한 필로티예요."},{"b":[0.461,0.522,0.403,0.404],"c":[0.4409,0.5018,0.4433,0.4444],"r":1.33,"img":"img/U7/walk/p035_24_05.jpg","say":"필로티 아래 빈 땅이에요. 차가 서 있어요."},{"b":[0.432,0.957,0.404,0.03],"c":[0.4118,0.89,0.4444,0.11],"r":5.3867,"img":"img/U7/walk/p035_24_06.jpg","say":"캡션: 르 코르뷔지에, 유니테 다비타시옹, 독일 베를린, 1958."}]}},{"p":36,"title":"단면도와 평면: 복층 주거단위가 맞물리는 법","terms":["복층","중복도","Unite d'Habitation","Pilotis","Soleil"],"pass1":[{"kind":"analogy","head":"지퍼처럼 맞물리는 집","scene":"지퍼 이빨이 양쪽에서 번갈아 끼워지는 모습을 떠올려요.","map":[["양쪽 지퍼 이빨","위아래 두 층을 쓰는 집들"],["가운데 지퍼 줄","건물 한가운데 복도"],["빈틈없이 맞물림","단위세대가 이중으로 교묘하게 맞물림"]]},{"kind":"say","lines":["왼쪽은 건물을 세로로 자른 단면도, 가운데는 집 평면, 오른쪽은 입체 그림이에요.","색칠한 칸이 집 한 채예요. 여러 집이 두 층에 걸쳐 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["단면도: 건물을 케이크처럼 세로로 잘라 속을 보여 주는 그림이에요.","**복층**: 한 집이 위아래 두 층을 함께 쓰는 구성이에요.","**중복도**: 건물 가운데를 지나는 복도예요."]},{"kind":"points","head":"이 그림에서 볼 것","items":["캡션은 르 코르뷔지에, 유니테 다비타시옹, 독일 베를린, 1958이에요.","단면도의 청록 칸과 빨간 칸은 두 층에 걸쳐 있어요. 안에 비스듬한 계단 선이 있어요.","노란 칸은 한 층에만 있어요.","가운데 흰 네모들이 세로로 줄지어 있어요. p.26 의 중앙 출입복도 자리로 보여요.","가운데 평면은 청록과 빨강이 두 장씩, 노랑이 한 장이에요. 두 장은 한 집의 위층과 아래층이에요.","맨 아래는 굵은 기둥 두 개가 건물을 받쳐요. **필로티(Pilotis)** 예요. 축척은 0, 5, 10m예요."]},{"kind":"points","head":"p.26, p.27과 이어 보기","items":["중앙의 출입복도를 중심으로 단위세대가 이중으로 교묘하게 맞물려요.","**채광(Soleil)**: **중복도** 와 **복층** 주택 구성으로 모든 주거단위에 적극적 채광을 들여요.","오른쪽 입체 그림은 필로티 위에 선 건물에서 앞면 한 덩어리를 떼어 내 속을 보여 줘요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유니테 다비타시옹(Unite d'Habitation)** 에서 모든 주거단위에 적극적 채광을 들인 방법은?","choices":["**중복도** 와 **복층** 주택 구성","유리 커튼월","지붕의 천창"],"a":0,"why":"채광(Soleil): 중복도와 복층주택 구성으로 모든 주거단위에 적극적 채광도입이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["그림 위 흰 손글씨(상부층, 하부층, 한쪽만 복층 등)는 필기예요. 슬라이드 원문이 아니에요.","슬라이드 글자는 캡션과 축척(0, 5, 10m)뿐이에요.","복층과 중복도의 설명은 p.26, p.27 본문에서 가져와요."]}],"walk":{"head":null,"parts":[{"b":[0.0,0.059,0.297,0.863],"c":[0,0.0158,0.3692,0.9493],"r":0.5186,"img":"img/U7/walk/p036_23_01.jpg","say":"단면도: 색칠한 칸이 집 한 채예요."},{"b":[0.163,0.589,0.094,0.069],"c":[0.11,0.5685,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p036_23_02.jpg","say":"빨간 집은 두 층에 걸쳐 있어요."},{"b":[0.311,0.048,0.355,0.629],"c":[0.2933,0.0166,0.3905,0.6919],"r":0.7525,"img":"img/U7/walk/p036_23_03.jpg","say":"평면: 같은 색 두 장이 한 집의 위층과 아래층이에요."},{"b":[0.071,0.724,0.207,0.138],"c":[0.059,0.708,0.231,0.17],"r":1.8118,"img":"img/U7/walk/p036_23_04.jpg","say":"굵은 기둥 두 개가 건물을 받쳐요. 필로티예요."},{"b":[0.594,0.195,0.386,0.788],"c":[0.5747,0.1332,0.4246,0.8668],"r":0.6531,"img":"img/U7/walk/p036_23_05.jpg","say":"입체 그림: 필로티 위 건물의 속을 열어 보여 줘요."},{"b":[0.093,0.933,0.407,0.029],"c":[0.0726,0.89,0.4477,0.11],"r":5.4267,"img":"img/U7/walk/p036_23_06.jpg","say":"캡션: 르 코르뷔지에, 유니테 다비타시옹, 독일 베를린, 1958."}]}},{"p":37,"title":"마르세이유 유니테의 단면과 주거단위 모형 (캡션 없는 슬라이드)","terms":["Unite d'Habitation","in situ","prefabrication","철근 콘크리트","복층","Karl Marx Hof","Soleil","Espace","Verdure","중복도","Modulor"],"pass1":[{"kind":"say","lines":["나무로 만든 모형 사진 세 장과 단면 그림 한 장이에요.","오른쪽 위 그림 제목에 UNITÉ D'HABITATION MARSEILLE 이 적혀 있어요.","이번에는 베를린이 아니라 마르세이유 건물의 모형이에요."]},{"kind":"recap","items":["7-5 유니테 다비타시옹을 한 줄씩 묶어요","마르세이유 노동자 공동주택, 1952년 완공, 길이 140m 높이 24m예요.","기본접근은 **채광(Soleil)**, **Espace**(공간), **녹지(Verdure)** 예요.","**중복도** 와 **복층** 으로 집이 맞물리고, 척도는 **모듈러(Modulor)** 예요.","5단원 **칼 마르크스 호프(Karl Marx Hof)** 처럼 노동자를 위한 큰 주거예요. 베를린에도 1958년에 지었어요."]}],"pass2":[{"kind":"analogy","head":"선반에 상자 끼우기","scene":"칸칸이 나뉜 나무 선반에 상자를 하나씩 끼워 넣는 모습을 떠올려요.","map":[["나무 선반 틀","모형의 나무 격자, 기둥과 보의 뼈대"],["끼워 넣은 상자","모형의 집 한 채"],["같은 상자를 여러 칸에","같은 모양 집의 반복"]]},{"kind":"points","head":"사진에서 보이는 것","items":["왼쪽: 가는 나무 막대로 짠 격자 틀 안에 길쭉한 집 상자가 끼워져 있어요.","아래 두 장: 집 상자를 끝에서 본 모습이에요. 위아래 두 칸으로 되어 있어요.","오른쪽 위 단면: 집들이 가운데를 두고 위아래로 엇갈려 맞물린 모습으로 보여요.","앞 쪽 베를린 단면도와 같은 생각이에요. **복층** 집들이 이중으로 맞물려요."]},{"kind":"points","head":"p.27과 이어 보기","items":["뼈대는 **철근 콘크리트** 기둥과 보로 이루어진 **인 시트(in situ)** 구조예요.","반복적인 외피는 미리 성형해 올렸어요. **미리 만들어진 부재사용(prefabrication)** 이에요.","모형의 나무 격자 틀과 끼워 넣은 상자가 이 '뼈대와 채움' 을 떠올리게 해요."]},{"kind":"bg","src":"배경 지식","lines":["Wohneinheit 는 독일어로 '주거 단위' 라는 뜻이에요.","프랑스어 Unité d'Habitation 도 같은 뜻이에요.","Schnitt 는 독일어로 '단면' 이에요. Schnitt A-A 는 A-A 선으로 자른 단면이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**인 시트(in situ)** 구조로 이루어진 것은 무엇일까요?","choices":["**철근 콘크리트** 기둥과 보","반복적인 외피","모듈러 인체 부조"],"a":0,"why":"인 시트 구조는 철근 콘크리트 기둥과 보예요. 반복적인 외피는 미리 만들어진 부재사용(prefabrication)이에요."},{"kind":"english","head":"논술 답안: 유니테 다비타시옹의 구조","en":"유니테 다비타시옹은 철근 콘크리트 기둥과 보의 인 시트(in situ) 구조에, 미리 성형한 외피를 올리는 미리 만들어진 부재사용(prefabrication)을 썼고, 모듈러로 부재를 규격화하였다.","ko":"구조(인 시트), 외피(prefabrication), 모듈러(표준화, 규격화) 세 칸이에요.","tip":"'뼈대는 현장에서, 껍데기는 미리, 크기는 모듈러로' 라고 외워요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 캡션이 없어요. 그림 속 글자에 MARSEILLE 이 있어요.","p.31-36 은 베를린, 이 쪽은 마르세이유예요.","파란 동그라미와 화살표는 누군가의 필기예요. 슬라이드 내용이 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.398,0.005,0.582,0.407],"c":[0.3598,0,0.6402,0.4477],"r":1.9066,"img":"img/U7/walk/p037_24_01.jpg","say":"제목: DIE WOHNEINHEIT UNITÉ D'HABITATION MARSEILLE REFERENZ."},{"b":[0.464,0.176,0.464,0.21],"c":[0.4408,0.16,0.5104,0.242],"r":2.8121,"img":"img/U7/walk/p037_24_02.jpg","say":"단면 Schnitt A-A: 집들이 위아래로 엇갈려 맞물려요."},{"b":[0.012,0.195,0.563,0.564],"c":[0,0.1668,0.6193,0.6204],"r":1.331,"img":"img/U7/walk/p037_24_03.jpg","say":"나무 격자 틀 안에 길쭉한 집 상자가 끼워져 있어요."},{"b":[0.468,0.545,0.241,0.427],"c":[0.456,0.5237,0.2651,0.4697],"r":0.7525,"img":"img/U7/walk/p037_24_04.jpg","say":"집 상자를 끝에서 본 모습: 위아래 두 칸이에요."},{"b":[0.733,0.545,0.247,0.438],"c":[0.7207,0.5182,0.2717,0.4818],"r":0.7519,"img":"img/U7/walk/p037_24_05.jpg","say":"다른 집 상자: 역시 위아래 두 칸이에요."}]}},{"p":38,"title":"2차 세계대전 이후의 작품: 노트르담 뒤 오 교회, 롱샹, 1951","terms":["Colline Notre Dame du Haut","롱샹교회","Le Corbusier","철근 콘크리트","흰 주택","Expressionism"],"pass1":[{"kind":"goal","items":["7-6 노트르담 뒤 오 교회(롱샹교회)에서 할 것","흰 상자에서 곡면 콘크리트로 바뀐 모습을 본다","떠 있는 지붕의 비밀(핀과 유리 부분)을 안다","세 개의 탑, 벽, 빛과 실내 디자인을 차례로 본다"]},{"kind":"say","lines":["1920년대 반듯한 **흰 주택** 을 떠올려 보세요.","그 상자를 찰흙처럼 주물러 휘면 이 교회가 돼요.","**노트르담 뒤 오 교회(Colline Notre Dame du Haut)**, 다른 이름 **롱샹교회** 예요.","프랑스 롱샹, 1951년, 2차 세계대전 이후의 작품이에요."]}],"pass2":[{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["후기의 디자인 기법에 대한 극적인 예예요.","곡선을 이루는 콘크리트 벽들이 불규칙한 모양의 실내를 둘러싸고 있어요.","지붕은 **철근 콘크리트** 로 비행기의 날개처럼 단면이 텅 빈 곡선을 이루게 축조했어요.","지붕은 핀(pin)들을 이용해 벽들 위로 올려져 있어요.","유리로 채워진 가늘고 긴 부분이 지붕을 공중에 떠 있는 것처럼 보이게 해요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽 사진: 둥근 흰 탑, 배 앞머리처럼 솟은 짙은 지붕, 크기가 제각각인 작은 창들이에요.","오른쪽 사진: 지붕이 크게 휘어 내려오고, 아래에 십자가와 작은 발코니가 보여요.","흰 벽과 짙은 콘크리트 지붕의 색 대비가 강해요.","p.2 소개처럼 **르 코르뷔지에(Le Corbusier)** 는 기능주의자들의 열망에 **표현주의(Expressionism)** 적인 강렬한 감각을 결합했어요."]},{"kind":"compare","head":"흰 상자에서 곡면으로","cols":["","1920년대 흰 주택","2차 세계대전 이후 롱샹교회"],"rows":[["모양","단순한 상자형태(순수직방체)","곡선을 이루는 콘크리트 벽"],["실내","Void와 테라스의 비대칭 배치","불규칙한 모양의 실내"],["지붕","평지붕, 옥상정원","비행기 날개 같은 텅 빈 곡선 지붕"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**노트르담 뒤 오 교회(Colline Notre Dame du Haut)** 지붕이 공중에 떠 있는 것처럼 보이는 까닭은?","choices":["지붕이 유리로 되어 있어서","핀(pin)으로 벽 위에 올리고, 유리로 채운 가늘고 긴 부분을 두어서","지붕을 줄로 매달아서"],"a":1,"why":"지붕은 핀(pin)들을 이용해 벽들 위로 올려져 있고, 유리로 채워진 가늘고 긴 부분이 떠 있는 것처럼 보이게 해요."},{"kind":"check","q":"**롱샹교회** 지붕의 설명으로 맞는 것은 무엇일까요?","choices":["**철근 콘크리트** 로 비행기 날개처럼 단면이 텅 빈 곡선","벽돌로 쌓은 고딕 볼트","평지붕 위 옥상정원"],"a":0,"why":"철근 콘크리트로 비행기의 날개처럼 단면이 텅 빈 곡선을 이루게 축조했어요. 평지붕과 옥상정원은 흰 주택 시절 이야기예요."},{"kind":"english","head":"논술 답안: 노트르담 뒤 오 교회","en":"롱샹교회(프랑스 롱샹, 1951)는 곡선의 콘크리트 벽이 불규칙한 실내를 둘러싸고, 비행기 날개처럼 단면이 텅 빈 철근 콘크리트 지붕을 핀으로 벽 위에 올려 떠 보이게 하였다.","ko":"벽(곡선, 불규칙한 실내), 지붕(비행기 날개, 텅 빈 단면), 핀과 유리(떠 보임) 순서예요.","tip":"'휜 벽, 날개 지붕, 핀으로 띄움' 세 마디로 외워요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드에 '이용해여' 라고 적혀 있어요. '이용하여' 의 오타예요.","롱샹교회 연도는 슬라이드 표기 1951로 외워요. 마르세이유 유니테(1952 완공)보다 한 해 앞서요.","슬라이드는 이 교회를 '후기의 디자인 기법에 대한 극적인 예' 라고 불러요. **표현주의(Expressionism)** 라는 말로 부르지는 않아요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.033,0.322,0.045],"c":[0.0339,0.0005,0.3542,0.11],"r":4.2933,"img":"img/U7/walk/p038_23_01.jpg","say":"제목: 2차 세계대전 이후의 작품."},{"b":[0.069,0.157,0.745,0.148],"c":[0.0318,0.141,0.8195,0.18],"r":6.0704,"img":"img/U7/walk/p038_23_02.jpg","say":"후기 디자인 기법의 극적인 예, 곡선 콘크리트 벽과 불규칙한 실내예요."},{"b":[0.069,0.329,0.874,0.152],"c":[0.0253,0.3079,0.9614,0.1942],"r":6.6008,"img":"img/U7/walk/p038_23_03.jpg","say":"비행기 날개 같은 텅 빈 지붕, 핀과 유리 부분으로 떠 보이는 지붕이에요."},{"b":[0.049,0.51,0.426,0.426],"c":[0.0277,0.4887,0.4686,0.4686],"r":1.3333,"img":"img/U7/walk/p038_23_04.jpg","say":"왼쪽 사진: 둥근 탑, 솟은 지붕, 제각각인 작은 창이에요."},{"b":[0.492,0.51,0.421,0.422],"c":[0.471,0.4889,0.4631,0.4642],"r":1.3302,"img":"img/U7/walk/p038_23_05.jpg","say":"오른쪽 사진: 휘어 내려온 지붕 아래 십자가와 발코니예요."},{"b":[0.25,0.957,0.623,0.03],"c":[0.2188,0.8615,0.6853,0.1385],"r":6.5974,"img":"img/U7/walk/p038_23_06.jpg","say":"캡션: 노트르담 뒤 오 교회(Colline Notre Dame du Haut, 롱샹교회), 프랑스 롱샹, 1951."}]}},{"p":39,"title":"깊은 몰아와 명상의 배","terms":["깊은 몰아와 명상의 배","Colline Notre Dame du Haut","롱샹교회","철근 콘크리트","Expressionism"],"pass1":[{"kind":"analogy","head":"하늘에 뜬 배","scene":"뒤집힌 배 밑바닥이 흰 벽 위에 살짝 얹힌 모습을 떠올려요.","map":[["배 밑바닥","짙은 곡면 콘크리트 지붕"],["배 안에 조용히 앉은 사람","기도하고 명상하는 사람"],["배의 이름","**깊은 몰아와 명상의 배**"]]},{"kind":"say","lines":["사진 한 장 위에 따옴표 문구가 크게 적혀 있어요.","'**깊은 몰아와 명상의 배**' 예요. **롱샹교회** 를 표현한 말이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 낱말 뜻","items":["몰아: 어떤 일에 푹 빠져 나를 잊는 상태예요.","명상: 마음을 가라앉히고 깊이 생각하는 일이에요.","**깊은 몰아와 명상의 배**: 그 안에서 나를 잊고 깊이 명상하는 배라는 뜻의 문구예요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["캡션은 노트르담 뒤 오 교회(Colline Notre Dame du Haut, 롱샹교회), 프랑스 롱샹, 1951이에요.","짙은 콘크리트 지붕이 배 밑바닥처럼 크게 휘어 하늘로 솟았어요.","오른쪽 둥근 벽 위에 짧은 받침이 지붕을 받치고 있어요. 지붕과 벽이 딱 붙어 있지 않아요.","p.38 의 핀(pin)과 유리로 채운 가늘고 긴 부분을 떠올리면 돼요.","벽에는 비스듬히 박힌 작은 창, 십자가, 돌로 된 단과 발코니가 보여요.","곡면 지붕의 극적인 모양이 6단원 **표현주의(Expressionism)** 건축을 떠올리게 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'**깊은 몰아와 명상의 배**' 는 어떤 건물을 표현한 말일까요?","choices":["빌라 사보아","**노트르담 뒤 오 교회(Colline Notre Dame du Haut)**","**유니테 다비타시옹(Unite d'Habitation)**"],"a":1,"why":"롱샹교회, 곧 노트르담 뒤 오 교회 사진 위에 적힌 문구예요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["사진 위 흰 손글씨와 파란 글씨(곡면, 틈 등)는 누군가의 필기예요. 슬라이드 원문이 아니에요.","지붕 설명은 p.38 본문 문장으로 외워요. **철근 콘크리트**, 비행기의 날개, 단면이 텅 빈 곡선이에요."]}],"walk":{"head":null,"parts":[{"b":[0.107,0.059,0.25,0.044],"c":[0.0945,0.026,0.275,0.11],"r":3.3333,"img":"img/U7/walk/p039_22_01.jpg","say":"문구: 깊은 몰아와 명상의 배."},{"b":[0.311,0.205,0.482,0.395],"c":[0.2869,0.1852,0.5302,0.4345],"r":1.627,"img":"img/U7/walk/p039_22_02.jpg","say":"짙은 콘크리트 지붕이 배 밑바닥처럼 휘었어요."},{"b":[0.671,0.533,0.05,0.076],"c":[0.596,0.516,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p039_22_03.jpg","say":"둥근 벽 위 짧은 받침이 지붕을 받쳐요."},{"b":[0.143,0.348,0.136,0.429],"c":[0.111,0.3266,0.2,0.4719],"r":0.5651,"img":"img/U7/walk/p039_22_04.jpg","say":"왼쪽 둥근 흰 탑이에요."},{"b":[0.429,0.686,0.307,0.095],"c":[0.4137,0.67,0.3377,0.127],"r":3.5454,"img":"img/U7/walk/p039_22_05.jpg","say":"십자가, 돌 단, 발코니와 사람들이에요. 건물 크기를 가늠해요."},{"b":[0.236,0.929,0.619,0.026],"c":[0.2051,0.8624,0.6809,0.1376],"r":6.5979,"img":"img/U7/walk/p039_22_06.jpg","say":"캡션: 노트르담 뒤 오 교회(Colline Notre Dame du Haut, 롱샹교회), 프랑스 롱샹, 1951."}]}},{"p":40,"title":"등각투상도와 롱샹교회의 탑들 (캡션 없는 슬라이드)","terms":["롱샹교회","Colline Notre Dame du Haut","세 개의 탑"],"pass1":[{"kind":"say","lines":["그림 한 장과 사진 세 장이에요. 캡션은 없어요.","왼쪽 위 그림에 '등각투상도' 라고 적혀 있어요.","교회를 위에서 비스듬히 내려다보며 속까지 그린 그림이에요.","사진들은 **롱샹교회** 의 둥근 머리를 한 탑들을 여러 방향에서 찍었어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 낱말 뜻","items":["등각투상도: 가로, 세로, 높이 세 방향을 같은 각도로 기울여 한 장에 입체를 그린 그림이에요.","탑: 주변보다 높이 솟은 건물 부분이에요."]},{"kind":"points","head":"그림과 사진에서 보이는 것만","items":["등각투상도: 휘어진 벽들이 불규칙한 실내를 감싸요. 벽 두께도 곳곳이 달라요.","오른쪽 위 사진: 왼쪽에 지붕 끝이 튀어나오고 오른쪽에 탑들이 솟아 있어요. 바깥 계단도 보여요.","왼쪽 아래 사진: 가장 높은 탑이에요. 세로로 긴 틈과 작은 둥근 창이 나 있고 꼭대기에 십자가가 있어요.","오른쪽 아래 사진: 뒤쪽에서 본 모습이에요. 낮은 탑 두 개와 높은 탑 하나가 보여요.","탑은 모두 세 개예요. p.43 에서 '**세 개의 탑**' 의 의미가 나와요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**롱샹교회** 사진들에서 볼 수 있는 탑은 모두 몇 개일까요?","choices":["두 개","세 개","다섯 개"],"a":1,"why":"세 개예요. p.43 에 '세개의 탑' 이 육중함, 안정감, 안전, 방호의 의미라고 나와요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드의 글자는 '등각투상도' 하나뿐이에요.","파란 화살표와 흰 손글씨는 누군가의 필기예요. 슬라이드 원문이 아니에요.","건물 이름과 연도는 p.38, p.39 캡션에서 가져와요. **노트르담 뒤 오 교회(Colline Notre Dame du Haut)**, 1951이에요."]}],"walk":{"head":null,"parts":[{"b":[0.136,0.014,0.232,0.381],"c":[0.124,0,0.256,0.4191],"r":0.8144,"img":"img/U7/walk/p040_22_01.jpg","say":"등각투상도: 위에서 비스듬히 본 교회의 속이에요."},{"b":[0.304,0.348,0.057,0.026],"c":[0.2325,0.306,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p040_22_02.jpg","say":"글자: 등각투상도."},{"b":[0.462,0.034,0.461,0.461],"c":[0.439,0.011,0.5071,0.5071],"r":1.3333,"img":"img/U7/walk/p040_22_03.jpg","say":"오른쪽 위: 튀어나온 지붕 끝과 탑들, 바깥 계단이에요."},{"b":[0.088,0.417,0.324,0.573],"c":[0.0718,0.3697,0.3564,0.6303],"r":0.7539,"img":"img/U7/walk/p040_22_04.jpg","say":"가장 높은 탑: 세로 틈, 둥근 창, 꼭대기 십자가예요."},{"b":[0.462,0.531,0.461,0.459],"c":[0.439,0.4951,0.5071,0.5049],"r":1.3391,"img":"img/U7/walk/p040_22_05.jpg","say":"뒤쪽 모습: 탑 세 개가 함께 보여요."}]}},{"p":41,"title":"거친 곡면 벽과 벽 위로 튀어나온 덩어리 (글자 없는 슬라이드)","terms":["롱샹교회","Colline Notre Dame du Haut","흰 주택"],"pass1":[{"kind":"say","lines":["글자 없는 사진 세 장이에요. 모두 **롱샹교회** 바깥이에요.","거칠게 마감한 흰 곡면 벽 위에 콘크리트 덩어리가 튀어나와 있어요.","그 아래 둥근 낮은 콘크리트 통 안에 삼각뿔과 원통이 놓여 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽 큰 사진: 벽면이 오톨도톨하게 거칠어요. 매끈한 **흰 주택** 의 벽과 달라요.","벽 위 가운데가 움푹 들어가고 그 자리에 콘크리트 덩어리가 튀어나와 있어요.","아래 둥근 낮은 콘크리트 통 안에 삼각뿔 두 개와 원통 하나가 있어요.","오른쪽 위 사진: 크게 내민 지붕 아래 원통 기둥, 둥근 발코니, 십자가, 돌로 된 단이 있어요.","오른쪽 아래 사진: 같은 벽을 멀리서 본 모습이에요. 뒤로 높은 탑이 보여요.","벽, 지붕, 바깥 물건이 모두 조각처럼 생겼어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 글자가 하나도 없어요.","덩어리와 통의 이름, 쓰임은 슬라이드에 없어요. 보이는 모양만 기억해요.","건물 이름은 앞 쪽 캡션의 **노트르담 뒤 오 교회(Colline Notre Dame du Haut)**, 롱샹, 1951이에요."]}],"walk":{"head":null,"parts":[{"b":[0.027,0.06,0.516,0.917],"c":[0.0012,0,0.5676,1],"r":0.7568,"img":"img/U7/walk/p041_21_01.jpg","say":"왼쪽: 거칠게 마감한 흰 곡면 벽이에요."},{"b":[0.316,0.276,0.114,0.086],"c":[0.273,0.26,0.2,0.118],"r":2.2599,"img":"img/U7/walk/p041_21_02.jpg","say":"벽 위로 튀어나온 콘크리트 덩어리예요."},{"b":[0.029,0.705,0.479,0.238],"c":[0.0051,0.689,0.5269,0.27],"r":2.602,"img":"img/U7/walk/p041_21_03.jpg","say":"둥근 낮은 통 안의 삼각뿔과 원통이에요."},{"b":[0.554,0.06,0.422,0.423],"c":[0.5329,0.0388,0.4642,0.4653],"r":1.3302,"img":"img/U7/walk/p041_21_04.jpg","say":"크게 내민 지붕, 원통 기둥, 십자가, 돌 단이에요."},{"b":[0.559,0.552,0.418,0.419],"c":[0.5381,0.5311,0.4598,0.4609],"r":1.3302,"img":"img/U7/walk/p041_21_05.jpg","say":"같은 벽을 멀리서 본 모습, 뒤에 높은 탑이에요."}]}},{"p":42,"title":"크기가 제각각인 창이 흩어진 벽과 색 창 그림 (글자 없는 슬라이드)","terms":["롱샹교회","Colline Notre Dame du Haut","흰 주택"],"pass1":[{"kind":"say","lines":["글자 없는 사진 한 장과 그림 한 장이에요.","위 사진은 **롱샹교회** 의 벽이에요. 창이 크기도 위치도 제각각이에요.","아래는 검은 벽에 색 창들을 그려 넣은 그림이에요."]}],"pass2":[{"kind":"points","head":"사진과 그림에서 보이는 것만","items":["위 사진: 지붕 아래 흰 벽에 네모 창들이 흩어져 있어요. 줄도 간격도 맞추지 않았어요.","창은 벽 속으로 깊게 파여 있고, 비스듬히 좁아지는 창도 있어요.","어떤 창은 아주 작고 어떤 창은 커요. 아래쪽에는 큰 창도 있어요.","아래 그림: 검게 칠한 벽에 크기가 다른 네모 창이 흩어져 있어요.","그 창마다 빨강, 노랑, 파랑, 초록 같은 색이 칠해져 있어요.","**흰 주택** 의 수평으로 연속된 창과 정반대예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**롱샹교회** 벽의 창 모습으로 맞는 것은 무엇일까요?","choices":["같은 크기 창이 한 줄로 길게 이어진다","크기와 위치가 제각각인 창이 벽에 흩어져 있다","창이 하나도 없다"],"a":1,"why":"크기도 위치도 제각각인 창이 흩어져 있어요. 줄 맞춘 긴 창은 흰 주택과 빌라 사보아의 수평띠창이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["파란 동그라미는 누군가의 필기예요. 슬라이드 원문이 아니에요.","아래 그림의 이름이나 그린 사람은 슬라이드에 없어요. 보이는 모양만 기억해요.","**노트르담 뒤 오 교회(Colline Notre Dame du Haut)** 의 컬러풀한 창문은 p.44 에서 글로 나와요."]}],"walk":{"head":null,"parts":[{"b":[0.35,0.017,0.52,0.518],"c":[0.324,0,0.572,0.5698],"r":1.3385,"img":"img/U7/walk/p042_21_01.jpg","say":"위: 크기와 위치가 제각각인 네모 창들이에요."},{"b":[0.568,0.133,0.038,0.062],"c":[0.487,0.109,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p042_21_02.jpg","say":"깊게 파여 비스듬히 좁아지는 창이에요."},{"b":[0.436,0.411,0.077,0.07],"c":[0.3745,0.391,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p042_21_03.jpg","say":"아래쪽의 큰 창이에요."},{"b":[0.025,0.535,0.586,0.455],"c":[0,0.4995,0.6446,0.5005],"r":1.7172,"img":"img/U7/walk/p042_21_04.jpg","say":"아래: 검은 벽에 색 창을 그린 그림이에요."},{"b":[0.207,0.79,0.043,0.052],"c":[0.1285,0.761,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p042_21_05.jpg","say":"빨간 색을 칠한 창 하나예요."}]}},{"p":43,"title":"두 유형의 벽체와 세 개의 탑","terms":["세 개의 탑","롱샹교회","Colline Notre Dame du Haut"],"pass1":[{"kind":"analogy","head":"성의 망루","scene":"옛날 성벽 곁에 우뚝 선 두꺼운 망루를 떠올려요.","map":[["두꺼운 망루","**세 개의 탑**"],["묵직하게 버팀","육중함, 안정감"],["안을 지켜 줌","안전, 방호"]]},{"kind":"say","lines":["사진 세 장과 글 두 줄이에요.","**롱샹교회** 의 벽과 **세 개의 탑** 이 무엇을 뜻하는지 알려 줘요."]}],"pass2":[{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["두 유형의 벽체로 에워쌈과 움직임을 표현해요.","**세 개의 탑**: 육중함, 안정감, 안전, 방호의 의미예요.","네 단어를 그대로 외워요. 육중함, 안정감, 안전, 방호예요."]},{"kind":"points","head":"이 쪽의 낱말 뜻","items":["에워쌈: 빙 둘러 감싸는 것이에요.","육중함: 크고 무거운 느낌이에요.","방호: 막아서 지키는 것이에요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽 위: 지붕 끝이 크게 튀어나오고 그 아래 굵은 기둥과 문이 있어요.","가운데 위: 둥근 머리의 탑 두 개가 나란히 솟아 있어요. 벽면이 거칠어요.","오른쪽 아래: 휘어진 벽과 크게 내민 지붕 아래 십자가, 돌 단, 발코니가 있어요.","슬라이드는 '두 유형' 이 무엇인지 이름을 붙이지 않았어요. 사진에서 곧은 벽과 휘어진 벽을 비교해 봐요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**세 개의 탑** 의 의미가 아닌 것은 무엇일까요?","choices":["육중함","안정감","가벼움","방호"],"a":2,"why":"세 개의 탑은 육중함, 안정감, 안전, 방호의 의미예요. 가벼움은 반대말이에요."},{"kind":"check","q":"**롱샹교회** 에서 두 유형의 벽체가 표현하는 것은 무엇일까요?","choices":["에워쌈과 움직임","질서와 혼돈","기능과 장식"],"a":0,"why":"두 유형의 벽체로 에워쌈과 움직임을 표현해요. 질서와 혼돈 사이의 긴장감은 라 투레트 수도원 이야기예요."},{"kind":"english","head":"논술 답안: 롱샹교회의 벽과 탑","en":"롱샹교회는 두 유형의 벽체로 에워쌈과 움직임을 표현하였고, 세 개의 탑은 육중함, 안정감, 안전, 방호의 의미를 가진다.","ko":"벽(에워쌈, 움직임), 탑(육중함, 안정감, 안전, 방호) 두 칸이에요.","tip":"탑 세 개에 단어 네 개, 앞 글자 '육, 안, 안, 방' 으로 외워요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["글자 위 파란 형광 표시와 '예술품 같다' 는 필기예요. 슬라이드 원문이 아니에요.","슬라이드 표기는 '세개의 탑' 으로 붙여 썼어요. 뜻은 같아요."]}],"walk":{"head":null,"parts":[{"b":[0.006,0.017,0.346,0.615],"c":[0,0,0.3806,0.6765],"r":0.7501,"img":"img/U7/walk/p043_23_01.jpg","say":"왼쪽 위: 튀어나온 지붕 끝, 굵은 기둥, 문이에요."},{"b":[0.374,0.038,0.334,0.594],"c":[0.3573,0.0083,0.3674,0.6534],"r":0.7497,"img":"img/U7/walk/p043_23_02.jpg","say":"가운데 위: 둥근 머리 탑 두 개예요."},{"b":[0.539,0.576,0.425,0.422],"c":[0.5178,0.5358,0.4675,0.4642],"r":1.3428,"img":"img/U7/walk/p043_23_03.jpg","say":"오른쪽 아래: 휘어진 벽과 내민 지붕 아래 십자가, 돌 단이에요."},{"b":[0.043,0.695,0.421,0.04],"c":[0.022,0.66,0.4631,0.11],"r":5.6133,"img":"img/U7/walk/p043_23_04.jpg","say":"두 유형의 벽체로 에워쌈과 움직임 표현."},{"b":[0.043,0.748,0.436,0.09],"c":[0.0212,0.732,0.4796,0.122],"r":5.2415,"img":"img/U7/walk/p043_23_05.jpg","say":"세개의 탑: 육중함, 안정감, 안전, 방호의 의미."}]}},{"p":44,"title":"빛나는 작은 창, 의식용 출입문(pivot), 챈슬","terms":["pivot","챈슬","롱샹교회","Colline Notre Dame du Haut","Le Corbusier"],"pass1":[{"kind":"analogy","head":"별빛 같은 창","scene":"깜깜한 방 벽에 바늘구멍을 뚫으면 걸을 때마다 빛이 반짝였다 사라지죠.","map":[["바늘구멍","아주 작은 유리가 채워진 창"],["걸을 때마다 반짝임","움직임에 따라 빛나 보이거나 빛이 끊어짐"],["방 전체의 분위기","신비롭고 감동적인 공간"]]},{"kind":"say","lines":["이제 **롱샹교회** 안으로 들어가요. 사진 두 장과 글 두 줄이에요.","어두운 벽에 깊게 파인 창들로 색색의 빛이 들어와요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**의식용 출입문(pivot)**: 에나멜 처리된 롱샹교회의 출입문이에요. pivot 은 영어로 회전축이라는 뜻이에요.","**챈슬**: 교회 제단 쪽 구역이에요.","에나멜: 겉에 유리질 광택 칠을 입힌 것이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["제단 뒤에 있는 벽은 아주 작은 유리가 채워진 창으로 구멍이 뚫려 있어요.","그래서 관찰자가 공간 안에서 움직이면 빛나 보이거나 빛이 끊어져요.","컬러풀한 창문들, 에나멜 처리된 **의식용 출입문(pivot)**, 좌석의 배치, **챈슬** 의 가구들이 있어요.","이것들이 모두 건축가에 의해 디자인되었어요. 건축가는 **르 코르뷔지에(Le Corbusier)** 예요.","그래서 고딕 교회의 인테리어들을 연상시키는 신비롭고 감동적인 공간을 창조했어요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽: 두꺼운 벽에 깊게 파인 네모 창들이 흩어져 있고 작은 색유리가 박혀 있어요.","오른쪽: 어두운 실내 끝에 십자가와 촛불이 있고, 모서리에 세로로 긴 빛줄기가 들어와요.","앞에는 나무 의자들이 줄지어 놓여 있어요. 슬라이드가 말한 좌석의 배치예요.","p.42 바깥 벽의 제각각인 창들과 모양이 닮았어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"슬라이드 목록에서 **롱샹교회** 건축가가 디자인했다고 한 것이 아닌 것은?","choices":["컬러풀한 창문들","에나멜 처리된 **의식용 출입문(pivot)**","**챈슬** 의 가구들","모듈러 인체 부조"],"a":3,"why":"모듈러 인체 부조는 베를린 유니테 다비타시옹 외벽(p.35)이에요. 나머지 셋과 좌석의 배치가 롱샹교회 목록이에요."},{"kind":"check","q":"제단 뒤 벽의 아주 작은 유리창이 만드는 효과는 무엇일까요?","choices":["관찰자가 움직임에 따라 빛나 보이거나 빛이 끊어진다","실내를 한결같이 밝게 비춘다","바깥 풍경을 크게 보여 준다"],"a":0,"why":"관찰자의 공간 안에서 움직임에 따라 빛나 보이거나 혹은 빛이 끊어져요."},{"kind":"english","head":"논술 답안: 롱샹교회의 실내","en":"롱샹교회는 컬러풀한 창문, 에나멜 처리된 의식용 출입문(pivot), 좌석 배치, 챈슬의 가구를 모두 건축가가 디자인하여 고딕 교회 인테리어를 연상시키는 신비로운 공간을 창조하였다.","ko":"창문, 출입문(pivot), 좌석, 챈슬 가구 네 가지 + 고딕 교회 연상이에요.","tip":"'창, 문, 의자, 챈슬' 네 개를 손가락으로 세며 외워요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["글자 위 파란 표시와 '회전문 같음' 손글씨는 필기예요. 슬라이드 원문이 아니에요.","'고딕 교회' 는 연상시킨다는 뜻이에요. 롱샹교회가 고딕 양식이라는 말이 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.068,0.076,0.882,0.086],"c":[0.0239,0.021,0.9702,0.196],"r":6.6,"img":"img/U7/walk/p044_23_01.jpg","say":"제단 뒤 벽의 아주 작은 유리창: 움직이면 빛나거나 끊어져요."},{"b":[0.068,0.181,0.882,0.148],"c":[0.0239,0.157,0.9702,0.196],"r":6.6,"img":"img/U7/walk/p044_23_02.jpg","say":"컬러풀한 창문, 의식용 출입문(pivot), 좌석 배치, 챈슬 가구, 고딕 교회 연상이에요."},{"b":[0.018,0.405,0.482,0.481],"c":[0,0.3809,0.5302,0.5291],"r":1.3361,"img":"img/U7/walk/p044_23_03.jpg","say":"왼쪽: 깊게 파인 창과 작은 색유리예요."},{"b":[0.517,0.405,0.482,0.481],"c":[0.4698,0.3809,0.5302,0.5291],"r":1.3361,"img":"img/U7/walk/p044_23_04.jpg","say":"오른쪽: 십자가와 촛불, 줄지은 나무 의자예요."},{"b":[0.693,0.41,0.029,0.276],"c":[0.6075,0.394,0.2,0.308],"r":0.8658,"img":"img/U7/walk/p044_23_05.jpg","say":"모서리에 세로로 긴 빛줄기가 들어와요."}]}},{"p":45,"title":"롱샹교회 실내: 두꺼운 벽, 깊은 창, 처진 천장 (글자 없는 슬라이드)","terms":["Colline Notre Dame du Haut","롱샹교회","Le Corbusier"],"pass1":[{"kind":"say","lines":["이 슬라이드에는 글자가 없어요. 사진 세 장뿐이에요.","앞 쪽에 이어 **롱샹교회** 안을 찍은 사진이에요.","어두운 천장이 아래로 처지고, 흰 벽이 휘어 있어요.","벽에는 크기가 제각각인 창 구멍이 뚫려 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽 위: 아주 두꺼운 벽에 크기가 다른 네모 창이 흩어져 뚫려 있어요.","창 구멍은 안쪽으로 갈수록 넓어지는 깔때기 모양이에요. 몇 개는 색유리예요.","어두운 천장과 벽 사이에 가는 빛줄기가 길게 보여요.","오른쪽 위: 흰 제단과 무릎 꿇는 난간이 있고, 벽에 둥근 발코니가 붙어 있어요.","아래: 어두운 천장이 물결처럼 처져 있고, 흰 벽이 휘어 있어요."]},{"kind":"points","head":"p.38 글과 짝지어 보기","items":["p.38: 곡선을 이루는 콘크리트 벽들이 불규칙한 모양의 실내를 둘러싸요.","아래 사진의 휘어진 흰 벽이 바로 그 모습이에요.","p.38: 유리로 채워진 가늘고 긴 부분이 지붕을 공중에 떠 있는 것처럼 보이게 해요.","왼쪽 위 사진 천장 가장자리의 빛줄기를 그 문장과 함께 보세요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"p.38에서 **롱샹교회** 의 지붕이 공중에 떠 보이는 까닭은 무엇이었을까요?","choices":["지붕을 굵은 기둥 하나로 받쳐서","유리로 채워진 가늘고 긴 부분이 벽과 지붕 사이에 있어서","지붕을 유리로만 만들어서"],"a":1,"why":"지붕은 핀(pin)들로 벽 위에 올렸고, 유리로 채운 가늘고 긴 부분이 지붕을 떠 보이게 해요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 캡션이 없어요. 이름과 연도는 p.38에서 가져와요.","**노트르담 뒤 오 교회(Colline Notre Dame du Haut)**, 프랑스 롱샹, 1951년이에요.","사진 위의 동그라미와 글씨는 손으로 한 필기예요. 슬라이드 원문이 아니에요."]}],"walk":{"head":null,"parts":[{"b":[0.027,0.059,0.463,0.462],"c":[0.0038,0.0359,0.5093,0.5082],"r":1.3362,"img":"img/U7/walk/p045_22_01.jpg","say":"왼쪽 위: 두꺼운 벽에 크기가 다른 깊은 창이 흩어져 있어요."},{"b":[0.236,0.09,0.254,0.09],"c":[0.2233,0.074,0.2794,0.122],"r":3.0536,"img":"img/U7/walk/p045_22_02.jpg","say":"천장과 벽 사이의 가는 빛줄기예요. 지붕이 떠 보이게 해요."},{"b":[0.507,0.059,0.469,0.468],"c":[0.4836,0.0356,0.5159,0.5148],"r":1.3362,"img":"img/U7/walk/p045_22_03.jpg","say":"오른쪽 위: 흰 제단과 난간, 벽에 붙은 둥근 발코니예요."},{"b":[0.161,0.563,0.647,0.427],"c":[0.1287,0.5303,0.7117,0.4697],"r":2.0203,"img":"img/U7/walk/p045_22_04.jpg","say":"아래: 어두운 천장이 물결처럼 처지고 흰 벽이 휘어 있어요."}]}},{"p":46,"title":"그림이 그려진 문과 깊은 창 구멍 (글자 없는 슬라이드)","terms":["롱샹교회","pivot","Le Corbusier"],"pass1":[{"kind":"say","lines":["이 슬라이드도 글자가 없어요. 사진 두 장이에요.","하나는 그림이 그려진 큰 문, 하나는 창 구멍이 가득한 두꺼운 벽이에요.","모두 **롱샹교회** 안쪽 모습이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽 위: 두꺼운 벽 사이에 커다란 문이 있어요.","문 면에 빨강, 노랑, 초록, 검정으로 그림이 그려져 있어요.","문 양옆 틈으로 바깥 빛이 새어 들어와요.","오른쪽 아래: 벽에 깊은 네모 구멍이 여러 개 뚫려 있어요. 크기와 기울기가 제각각이에요.","구석의 창에는 노랑, 초록 색유리가 끼워져 있어요. 앉은 사람과 비교하면 벽이 아주 커요."]},{"kind":"points","head":"p.44 글과 짝지어 보기","items":["p.44: 컬러풀한 창문들과 에나멜 처리된 **의식용 출입문(pivot)** 이 나와요.","좌석의 배치, 챈슬의 가구까지 모두 건축가가 디자인했어요.","왼쪽 위의 그림 문을 그 문장과 함께 떠올려 보세요. 다만 이 쪽에 이름표는 없어요.","건축가는 물론 **르 코르뷔지에(Le Corbusier)** 예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"p.44에서 **롱샹교회** 의 에나멜 처리된 출입문을 부른 이름은 무엇일까요?","choices":["**의식용 출입문(pivot)**","**램프**","**월 판넬**"],"a":0,"why":"에나멜 처리된 의식용 출입문(pivot)이에요. 램프와 월 판넬은 르 코르뷔지에 센터에서 나와요."},{"kind":"english","head":"논술 답안: 롱샹교회의 실내","en":"롱샹교회는 컬러풀한 창문들과 에나멜 처리된 의식용 출입문(pivot), 좌석의 배치, 챈슬의 가구들이 모두 건축가에 의해 디자인되어 신비롭고 감동적인 공간을 창조하였다.","ko":"창문, 출입문(pivot), 좌석, 챈슬 가구 네 가지가 모두 건축가 디자인이에요.","tip":"'창, 문, 의자, 챈슬' 네 개를 손가락으로 세어요."}],"walk":{"head":null,"parts":[{"b":[0.027,0.016,0.505,0.505],"c":[0.0018,0,0.5555,0.5555],"r":1.3333,"img":"img/U7/walk/p046_22_01.jpg","say":"왼쪽 위: 두꺼운 벽 사이의 큰 문이에요. 아래에 긴 의자가 보여요."},{"b":[0.221,0.09,0.175,0.229],"c":[0.2085,0.074,0.2,0.261],"r":1.0217,"img":"img/U7/walk/p046_22_02.jpg","say":"문 면의 원색 그림이에요. 양옆 틈으로 빛이 새어 들어와요."},{"b":[0.334,0.348,0.631,0.631],"c":[0.3024,0.3059,0.6941,0.6941],"r":1.3333,"img":"img/U7/walk/p046_22_03.jpg","say":"오른쪽 아래: 깊은 네모 창 구멍이 가득한 두꺼운 벽이에요."},{"b":[0.745,0.77,0.15,0.143],"c":[0.72,0.754,0.2,0.175],"r":1.5238,"img":"img/U7/walk/p046_22_04.jpg","say":"구석 창: 노랑, 초록 색유리가 끼워져 있어요."}]}},{"p":47,"title":"세 개의 예배당과 상부의 숨겨진 창문","terms":["롱샹교회","Colline Notre Dame du Haut","세 개의 탑"],"pass1":[{"kind":"analogy","head":"숨은 조명","scene":"천장 속에 숨긴 조명을 떠올려요. 등은 안 보이고 빛만 벽을 타고 내려와요.","map":[["천장 속에 숨긴 등","상부에 있는 숨겨진 창문들"],["벽을 타고 퍼지는 빛","예배당 안을 물들이는 빛"],["작은 방 세 개","**롱샹교회** 의 세 개의 예배당"]]}],"pass2":[{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["세 개의 예배당으로 들어오는 빛들은 상부에 있는 숨겨진 창문들로부터 들어와요.","창이 보이지 않으니 빛이 어디서 오는지 알기 어려워요.","이 문장이 이 쪽의 유일한 글이에요. 그대로 외워요."]},{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽 위: 둥근 천장 안쪽이 붉게 물들어 있고 가운데가 환해요.","오른쪽 아래: 같은 모양의 둥근 천장인데 흰색이에요.","두 사진 모두 아래쪽에 가는 유리 띠가 줄지어 있어요.","벽면이 거칠고 오톨도톨해요. 빛을 받은 곳과 그늘이 또렷이 갈려요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**롱샹교회** 의 세 개의 예배당으로 들어오는 빛은 어디에서 올까요?","choices":["바닥에 뚫린 창","상부에 있는 숨겨진 창문들","제단 뒤의 큰 유리벽"],"a":1,"why":"상부에 있는 숨겨진 창문들로부터 들어와요."},{"kind":"warn","head":"헷갈리기 쉬운 '세 개'","items":["**세 개의 탑**: 육중함, 안정감, 안전, 방호의 의미예요(p.43).","세 개의 예배당: 숨겨진 창문의 빛이 들어오는 곳이에요(p.47).","탑은 의미, 예배당은 빛. 두 문장을 섞지 않아요."]}],"walk":{"head":null,"parts":[{"b":[0.518,0.11,0.396,0.148],"c":[0.4982,0.094,0.4356,0.18],"r":3.2267,"img":"img/U7/walk/p047_22_01.jpg","say":"글: 세 개의 예배당 빛은 상부의 숨겨진 창문들에서 들어와요."},{"b":[0.027,0.059,0.44,0.438],"c":[0.005,0.0371,0.484,0.4818],"r":1.3394,"img":"img/U7/walk/p047_22_02.jpg","say":"왼쪽 위: 붉게 물든 둥근 천장이에요. 가운데가 환해요."},{"b":[0.071,0.362,0.329,0.067],"c":[0.0545,0.3405,0.3619,0.11],"r":4.3867,"img":"img/U7/walk/p047_22_03.jpg","say":"아래쪽의 가는 유리 띠예요."},{"b":[0.357,0.369,0.628,0.627],"c":[0.3092,0.3103,0.6908,0.6897],"r":1.3355,"img":"img/U7/walk/p047_22_04.jpg","say":"오른쪽 아래: 흰 둥근 천장이에요. 어둠 속에서 빛나 보여요."}]}},{"p":48,"title":"색유리 창: marie, étoile du matin (글자 없는 슬라이드)","terms":["롱샹교회","Colline Notre Dame du Haut","Le Corbusier"],"pass1":[{"kind":"say","lines":["사진 세 장 모두 색유리 창을 가까이 찍은 것이에요.","파랑, 노랑, 초록, 빨강 유리에 그림과 글씨가 그려져 있어요.","p.44에서 말한 **롱샹교회** 의 컬러풀한 창문들을 떠올려요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽: 파란 유리에 둥근 그림이 있어요. 창틀 아래로 파란 빛이 떨어져요.","오른쪽 위: 투명 유리에 'marie' 라는 글씨가 쓰여 있어요.","그 옆 유리에는 노란 꽃 그림과 초록 유리가 있어요.","오른쪽 아래: 붉은 유리에 'étoile du matin' 이라는 글씨가 쓰여 있어요.","세 창 모두 둘레의 벽이 아주 두껍고 거칠어요."]},{"kind":"bg","src":"일반 상식 (프랑스어 낱말)","lines":["marie 는 프랑스어 이름 '마리' 예요.","étoile du matin 은 프랑스어로 '아침의 별' 이라는 뜻이에요.","슬라이드는 낱말 뜻을 설명하지 않아요. 글자 모양만 기억해도 돼요."]},{"kind":"points","head":"p.44 글과 짝지어 보기","items":["p.44: 제단 뒤에 있는 벽은 아주 작은 유리가 채워진 창으로 구멍이 뚫려 있어요.","관찰자가 공간 안에서 움직이면 빛나 보이거나 혹은 빛이 끊어져요.","이 쪽 사진 같은 두꺼운 벽 속 작은 색유리를 떠올리면 쉬워요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**롱샹교회** 제단 뒤 벽의 작은 유리 창에 대한 설명으로 옳은 것은 무엇일까요?","choices":["관찰자의 움직임에 따라 빛나 보이거나 빛이 끊어진다","어느 자리에서 보아도 빛이 똑같다","창이 하나도 없는 막힌 벽이다"],"a":0,"why":"p.44: 관찰자의 공간 안에서 움직임에 따라 빛나 보이거나 혹은 빛이 끊어져요."}],"walk":{"head":null,"parts":[{"b":[0.051,0.279,0.369,0.654],"c":[0.0325,0.2463,0.4059,0.7194],"r":0.7523,"img":"img/U7/walk/p048_23_01.jpg","say":"왼쪽: 파란 유리 창이에요. 창틀 아래로 파란 빛이 떨어져요."},{"b":[0.473,0.016,0.449,0.45],"c":[0.4506,0,0.4939,0.495],"r":1.3304,"img":"img/U7/walk/p048_23_02.jpg","say":"오른쪽 위: 투명 유리와 노란 꽃, 초록 유리가 섞인 창이에요."},{"b":[0.636,0.219,0.1,0.052],"c":[0.586,0.19,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p048_23_03.jpg","say":"유리에 쓰인 글씨: marie."},{"b":[0.473,0.5,0.466,0.465],"c":[0.4497,0.4768,0.5126,0.5115],"r":1.3362,"img":"img/U7/walk/p048_23_04.jpg","say":"오른쪽 아래: 붉은 유리 아래 파란 유리가 받친 창이에요."},{"b":[0.586,0.59,0.207,0.162],"c":[0.574,0.574,0.231,0.194],"r":1.5876,"img":"img/U7/walk/p048_23_05.jpg","say":"유리에 쓰인 글씨: étoile du matin."}]}},{"p":49,"title":"두꺼운 벽 속 깊은 창 세 개 (글자 없는 슬라이드)","terms":["롱샹교회","Colline Notre Dame du Haut","세 개의 탑","Le Corbusier","Expressionism"],"pass1":[{"kind":"say","lines":["사진 세 장 모두 벽 속으로 깊게 파인 창을 찍은 것이에요.","창 자체는 작은데 벽 구멍은 크고 깊어요. 벽이 얼마나 두꺼운지 보여요."]},{"kind":"recap","items":["7-6 **롱샹교회** 를 한 줄로","**노트르담 뒤 오 교회(Colline Notre Dame du Haut)**, 프랑스 롱샹, 1951년이에요.","곡선 콘크리트 벽, 떠 보이는 지붕, '깊은 몰아와 명상의 배' 예요.","**세 개의 탑**, 컬러풀한 창, 숨겨진 창문의 빛이 실내를 만들어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽: 흰 벽에 깔때기처럼 좁아지는 구멍이 있고, 끝에 분홍빛 작은 창이 있어요.","가운데: 비스듬히 파인 구멍 끝에 초록, 빨강 유리 창이 있어요.","오른쪽: 아주 좁고 긴 틈 창이에요. 노랑, 초록 유리가 끼워져 있어요.","p.44의 '아주 작은 유리가 채워진 창' 을 가까이서 보는 느낌이에요."]},{"kind":"bg","src":"p.2 다시 보기","lines":["**르 코르뷔지에(Le Corbusier)** 는 기능주의와 대담하고 조소적인 **표현주의(Expressionism)** 를 결합했어요.","6단원 **표현주의(Expressionism)** 는 실재를 주관적으로 해석해 극적인 형태로 드러내는 흐름이었어요.","**롱샹교회** 의 곡면과 두꺼운 벽은 그 조소적인 쪽을 보여 줘요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"다음 중 **롱샹교회** 에 대한 설명이 아닌 것은 무엇일까요?","choices":["**세 개의 탑** 은 육중함, 안정감, 안전, 방호의 의미예요","세 개의 예배당의 빛은 상부의 숨겨진 창문들에서 와요","강철 지붕 아래 유리와 밝은 원색의 **월 판넬** 을 썼어요"],"a":2,"why":"세 번째는 p.50 **르 코르뷔지에 센터(Centre Le Corbusier)** 의 설명이에요."},{"kind":"english","head":"논술 답안: 롱샹교회의 빛","en":"롱샹교회의 제단 뒤 벽은 아주 작은 유리가 채워진 창으로 뚫려 관찰자의 움직임에 따라 빛나거나 빛이 끊어지며, 세 개의 예배당의 빛은 상부의 숨겨진 창문들로부터 들어온다.","ko":"제단 뒤 벽의 작은 창, 세 예배당의 숨겨진 창. 빛 두 가지예요.","tip":"'작은 창은 깜빡, 숨은 창은 은은' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.011,0.284,0.303,0.537],"c":[0,0.2571,0.3333,0.5907],"r":0.7523,"img":"img/U7/walk/p049_22_01.jpg","say":"왼쪽: 깔때기처럼 좁아지는 구멍 끝에 분홍빛 작은 창이에요."},{"b":[0.342,0.284,0.301,0.533],"c":[0.327,0.2573,0.3311,0.5863],"r":0.753,"img":"img/U7/walk/p049_22_02.jpg","say":"가운데: 비스듬한 구멍 끝에 초록, 빨강 유리예요."},{"b":[0.689,0.288,0.3,0.533],"c":[0.67,0.2613,0.33,0.5863],"r":0.7505,"img":"img/U7/walk/p049_22_03.jpg","say":"오른쪽: 좁고 긴 틈 창에 노랑, 초록 유리가 끼워져 있어요."}]}},{"p":50,"title":"르 코르뷔지에 센터(Centre Le Corbusier), 스위스 취리히, 1957","terms":["Centre Le Corbusier","Le Corbusier","입체파","Modulor","월 판넬","램프"],"pass1":[{"kind":"analogy","head":"큰 우산 아래 블록 상자","scene":"공원에 큰 우산을 펴고 그 아래 알록달록한 블록 상자를 놓았다고 떠올려요.","map":[["커다란 우산","강철로 된 거대한 지붕"],["우산대","지붕을 떠받치는 가는 기둥들"],["알록달록한 블록","유리와 밝은 원색들의 **월 판넬**"]]},{"kind":"say","lines":["새 단원 7-7이에요. **르 코르뷔지에 센터(Centre Le Corbusier)** 예요.","스위스 취리히, 1957년. 롱샹의 흰 곡면과 달리 강철, 유리, 원색 판이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["파빌리온: 전시를 위해 지은 작은 건물이에요.","**입체파**: 사물을 여러 면과 기하학 조각으로 나눠 그리는 미술 흐름이에요.","**월 판넬**: 벽을 이루는 판이에요.","**램프**: 층과 층을 잇는 비탈길이에요. 계단 대신 걸어서 올라가요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["스위스 취리히 공원에 있는 전시용 파빌리온이에요.","입체파적인 **모듈러(Modulor)** 를 기하학적 시스템으로 배열했어요.","유리와 밝은 원색들로 이루어진 **월 판넬** 을 사용했어요.","상부층으로 이동하는 길고 돌출된 **램프** 가 있어요.","강철로 된 거대한 지붕은 가는 기둥들이 떠받치고 있으며 건물 전체를 보호해요."]},{"kind":"bg","src":"7-1 모듈러 다시 보기","lines":["**모듈러(Modulor)** 는 사람 몸 치수에서 뽑은 **르 코르뷔지에(Le Corbusier)** 의 비례 체계예요.","p.5에서 처음 나왔어요. 이 단원 끝에서 다시 핵심 단어가 돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**르 코르뷔지에 센터(Centre Le Corbusier)** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["스위스 취리히, 1957","프랑스 이브, 1960","프랑스 롱샹, 1951"],"a":0,"why":"취리히 공원의 전시용 파빌리온, 1957년이에요. 이브 1960은 **라 투레트 수도원**, 롱샹 1951은 **롱샹교회** 예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["제목은 '르 꼬르뷔지에 센터', 캡션은 '르 코르뷔지에 센터' 로 표기가 섞여 있어요. 같은 건물이에요.","전시 건물이 둘이에요. 1925년 에스쁘리 누보 전시관(파리)과 1957년 센터(취리히)를 섞지 않아요."]},{"kind":"english","head":"논술 답안: 르 코르뷔지에 센터","en":"르 코르뷔지에 센터(스위스 취리히, 1957)는 입체파적인 모듈러를 기하학적 시스템으로 배열하고, 원색의 월 판넬과 돌출된 램프, 가는 기둥이 떠받치는 강철 지붕을 사용하였다.","ko":"모듈러 배열, 월 판넬, 램프, 강철 지붕 네 가지예요.","tip":"'자, 판, 길, 우산' 네 단어로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.063,0.043,0.368,0.038],"c":[0.0446,0.007,0.4048,0.11],"r":4.9067,"img":"img/U7/walk/p050_23_01.jpg","say":"제목: 르 꼬르뷔지에 센터(Centre Le Corbusier)."},{"b":[0.068,0.157,0.5,0.103],"c":[0.043,0.141,0.55,0.135],"r":5.4321,"img":"img/U7/walk/p050_23_02.jpg","say":"취리히 공원의 전시용 파빌리온, 입체파적인 모듈러 배열이에요."},{"b":[0.068,0.278,0.486,0.103],"c":[0.0437,0.262,0.5346,0.135],"r":5.28,"img":"img/U7/walk/p050_23_03.jpg","say":"유리와 밝은 원색들의 월 판넬, 길고 돌출된 램프예요."},{"b":[0.068,0.398,0.768,0.043],"c":[0.0296,0.3342,0.8448,0.1707],"r":6.5987,"img":"img/U7/walk/p050_23_04.jpg","say":"강철로 된 거대한 지붕을 가는 기둥들이 떠받쳐 건물 전체를 보호해요."},{"b":[0.043,0.5,0.918,0.452],"c":[0,0.4774,1,0.4972],"r":2.6817,"img":"img/U7/walk/p050_23_05.jpg","say":"사진 두 장: 꺾인 회색 지붕 아래 유리와 원색 판의 상자예요."},{"b":[0.35,0.955,0.429,0.033],"c":[0.3286,0.89,0.4719,0.11],"r":5.72,"img":"img/U7/walk/p050_23_06.jpg","say":"캡션: 르 코르뷔지에, 르 코르뷔지에 센터, 스위스 취리히, 1957."}]}},{"p":51,"title":"르 코르뷔지에 센터 전경","terms":["Centre Le Corbusier","Le Corbusier","월 판넬","Modulor"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. 공원 연못 너머로 **르 코르뷔지에 센터(Centre Le Corbusier)** 가 보여요.","꺾인 판 같은 큰 지붕 아래에 빨강, 노랑, 초록, 검정, 흰 판이 붙어 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것","items":["캡션: **르 코르뷔지에(Le Corbusier)**, **르 코르뷔지에 센터(Centre Le Corbusier)**, 스위스 취리히, 1957.","지붕: 회색 판이 크게 꺾여 두 덩어리로 아래 상자 위에 떠 있어요.","기둥: 가운데 굵은 네모 기둥과 지붕 끝의 가는 기둥들이 지붕을 받쳐요.","벽: 유리와 원색 **월 판넬** 이 네모 칸으로 짜여 있어요.","지붕이 상자보다 넓어서 건물 전체를 우산처럼 덮어요."]},{"kind":"points","head":"p.50 글과 짝지어 보기","items":["강철로 된 거대한 지붕 → 사진 위쪽의 꺾인 회색 지붕이에요.","가는 기둥들이 떠받침 → 지붕 끝에 선 가는 기둥이에요.","유리와 밝은 원색들의 **월 판넬** → 아래 상자의 색 칸이에요.","**모듈러(Modulor)** 를 기하학적 시스템으로 배열 → 색 칸들이 일정한 격자로 짜여 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"p.50에 적힌 **르 코르뷔지에 센터** 의 지붕 재료는 무엇일까요?","choices":["철근 콘크리트","강철","나무"],"a":1,"why":"강철로 된 거대한 지붕을 가는 기둥들이 떠받쳐요. 비행기 날개 같은 철근 콘크리트 지붕은 **롱샹교회** 예요."}],"walk":{"head":{"b":[0.7056,0.1821,0.1058,0.0619],"c":[0.6585,0.1661,0.2,0.0939],"r":2.8399,"img":"img/U7/walk/p051_h.jpg"},"parts":[{"b":[0.146,0.246,0.664,0.229],"c":[0.1128,0.23,0.7304,0.261],"r":3.7313,"img":"img/U7/walk/p051_22_01.jpg","say":"꺾인 회색 지붕이에요. 아래 상자보다 넓게 덮어요."},{"b":[0.139,0.433,0.3,0.214],"c":[0.124,0.417,0.33,0.246],"r":1.7886,"img":"img/U7/walk/p051_22_02.jpg","say":"유리와 원색 월 판넬이 네모 칸으로 짜여 있어요."},{"b":[0.482,0.295,0.179,0.367],"c":[0.47,0.2766,0.203,0.4037],"r":0.6705,"img":"img/U7/walk/p051_22_03.jpg","say":"지붕을 받치는 기둥들이에요. 가운데는 굵고 끝은 가늘어요."},{"b":[0.059,0.681,0.827,0.124],"c":[0.0176,0.6511,0.9097,0.1838],"r":6.5992,"img":"img/U7/walk/p051_22_04.jpg","say":"앞의 연못이에요. 건물과 색 판이 물에 비쳐요."},{"b":[0.35,0.955,0.429,0.033],"c":[0.3286,0.89,0.4719,0.11],"r":5.72,"img":"img/U7/walk/p051_22_05.jpg","say":"캡션: 르 코르뷔지에, 르 코르뷔지에 센터, 스위스 취리히, 1957."}]}},{"p":52,"title":"모듈러로 모든 디테일을 통제한 machine age(기계 시대)의 성공작","terms":["Modulor","machine age","Le Corbusier","Centre Le Corbusier"],"pass1":[{"kind":"say","lines":["글 세 줄과 실내 사진 두 장이에요.","한마디로, 작은 부분부터 건물 전체까지 한 가지 자로 쟀다는 이야기예요.","그 자가 **모듈러(Modulor)** 예요.","그래서 아름다움과 **기계 시대(machine age)** 의 기술을 이은 성공작이라고 해요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**기계 시대(machine age)**: 기계와 과학 기술이 이끄는 근대의 세계예요.","디테일: 손잡이, 창틀처럼 작은 부분이에요.","공동 사회: 여러 사람이 함께 사는 동네와 도시예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["모든 **르 코르뷔지에(Le Corbusier)** 의 작품에서와 같이 비율에 대한 기하학적 시스템을 체계적으로 사용했어요.","그래서 디자인의 모든 각각의 디테일들을 결정했어요.","가장 작은 디테일들로부터 건물 전체나 공동 사회들까지 모든 요소를 통제하려고 **모듈러(Modulor)** 를 적용했어요.","미학적인 가치 + 근대의 과학 기술에서 비롯된 **기계 시대(machine age)** 세계의 현실들을 연결한 성공작이에요."]},{"kind":"bg","src":"과목 주문 다시 보기","lines":["이 과목의 질문은 '기계 시대에 건축은 어떻게 생겨야 하나?' 예요.","1단원 미술공예운동은 기계를 싫어했어요. 주문의 첫 단계 '싫어' 예요.","7단원 끝의 **르 코르뷔지에 센터(Centre Le Corbusier)** 는 아름다움과 기계 시대를 이은 성공작으로 평가돼요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"p.52에서 **르 코르뷔지에 센터** 를 성공작이라고 한 까닭은 무엇일까요?","choices":["장식을 많이 붙여서","미학적인 가치와 근대 과학 기술의 **기계 시대(machine age)** 현실을 연결해서","옛 고딕 양식을 그대로 되살려서"],"a":1,"why":"미학적인 가치 + 근대의 과학 기술에서 비롯된 machine age(기계 시대) 세계의 현실들을 연결했어요."},{"kind":"check","q":"**모듈러(Modulor)** 를 적용한 범위로 슬라이드에 적힌 것은 무엇일까요?","choices":["가구에만","가장 작은 디테일들로부터 건물 전체나 공동 사회들까지","외벽 색에만"],"a":1,"why":"디자인적인 모든 요소들을 통제하려고 가장 작은 디테일부터 공동 사회까지 적용했어요."},{"kind":"english","head":"논술 답안: 모듈러와 기계 시대","en":"르 코르뷔지에는 가장 작은 디테일부터 건물 전체나 공동 사회까지 통제하기 위해 모듈러를 적용하였고, 미학적인 가치와 machine age(기계 시대)의 현실을 연결하였다.","ko":"모듈러의 범위(디테일 → 공동 사회)와 평가(미학 + 기계 시대) 두 가지예요.","tip":"'작은 것부터 도시까지 한 자로' 를 떠올려요."}],"walk":{"head":null,"parts":[{"b":[0.068,0.062,0.871,0.095],"c":[0.0245,0.0127,0.9581,0.1936],"r":6.5985,"img":"img/U7/walk/p052_23_01.jpg","say":"비율에 대한 기하학적 시스템을 체계적으로 써서 모든 디테일을 결정했어요."},{"b":[0.068,0.176,0.871,0.095],"c":[0.0245,0.1267,0.9581,0.1936],"r":6.5985,"img":"img/U7/walk/p052_23_02.jpg","say":"가장 작은 디테일부터 공동 사회까지 통제하려고 모듈러를 적용했어요."},{"b":[0.068,0.29,0.871,0.09],"c":[0.0245,0.2382,0.9581,0.1936],"r":6.5985,"img":"img/U7/walk/p052_23_03.jpg","say":"미학적인 가치 + 근대 과학 기술의 machine age(기계 시대)를 연결한 성공작이에요."},{"b":[0.046,0.49,0.474,0.471],"c":[0.0223,0.4665,0.5214,0.5181],"r":1.3418,"img":"img/U7/walk/p052_23_04.jpg","say":"왼쪽 아래 사진: 강철 틀과 큰 유리창, 금속 작업대가 있는 실내예요."},{"b":[0.555,0.362,0.359,0.638],"c":[0.5371,0.2982,0.3949,0.7018],"r":0.7503,"img":"img/U7/walk/p052_23_05.jpg","say":"오른쪽 사진: 거친 콘크리트 계단, 빨간 원기둥, 초록 쿠션 의자예요."}]}},{"p":53,"title":"원색 판과 그림 판, 실내 (글자 없는 슬라이드)","terms":["Centre Le Corbusier","월 판넬","Modulor"],"pass1":[{"kind":"say","lines":["글자 없이 사진 두 장이에요. **르 코르뷔지에 센터(Centre Le Corbusier)** 의 바깥 벽과 실내예요.","원색 판, 유리, 강철 틀이 네모 칸으로 짜여 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽: 빨강, 흰, 노랑 판과 유리창이 강철 틀에 끼워져 있어요.","그 사이 흰 판 하나가 문처럼 비스듬히 열려 있어요. 판에 검은 선 그림이 있어요.","오른쪽: 실내예요. 나무 상자 같은 위층이 강철 기둥 위에 얹혀 있어요.","빨간 원기둥, 긴 나무 탁자, 검은 사람 모양 조각이 보여요.","틀마다 볼트가 줄지어 박혀 있어요."]},{"kind":"points","head":"p.50 글과 짝지어 보기","items":["유리와 밝은 원색들로 이루어진 **월 판넬** 을 가까이서 보면 이래요.","검은 사람 조각은 p.55 사진에서 더 크게 보여요.","p.5 **모듈러(Modulor)** 그림 속의 한 팔 든 사람을 떠올려요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"p.50에서 **르 코르뷔지에 센터** 의 **월 판넬** 은 무엇으로 이루어졌다고 했나요?","choices":["유리와 밝은 원색들","붉은 벽돌","거친 노출 콘크리트"],"a":0,"why":"유리와 밝은 원색들로 이루어진 월 판넬이에요. 거친 노출 콘크리트는 **라 투레트 수도원** 이에요."}],"walk":{"head":null,"parts":[{"b":[0.002,0.206,0.607,0.607],"c":[0,0.1756,0.6677,0.6677],"r":1.3333,"img":"img/U7/walk/p053_22_01.jpg","say":"왼쪽: 빨강, 흰, 노랑 월 판넬과 유리창이 강철 틀에 끼워져 있어요."},{"b":[0.354,0.51,0.168,0.271],"c":[0.338,0.494,0.2,0.303],"r":0.8801,"img":"img/U7/walk/p053_22_02.jpg","say":"문처럼 열린 흰 판이에요. 검은 선 그림이 그려져 있어요."},{"b":[0.634,0.193,0.356,0.631],"c":[0.6084,0.1614,0.3916,0.6941],"r":0.7522,"img":"img/U7/walk/p053_22_03.jpg","say":"오른쪽: 실내예요. 나무 상자 같은 위층이 강철 기둥 위에 있어요."},{"b":[0.679,0.371,0.05,0.419],"c":[0.604,0.3501,0.2,0.4609],"r":0.5786,"img":"img/U7/walk/p053_22_04.jpg","say":"검은 사람 모양 조각이에요."},{"b":[0.936,0.195,0.054,0.524],"c":[0.7758,0.1688,0.2242,0.5764],"r":0.5186,"img":"img/U7/walk/p053_22_05.jpg","say":"빨간 원기둥이에요."}]}},{"p":54,"title":"지붕 아래 옥상, 그림 판, 벽걸이 그림, 램프 (글자 없는 슬라이드)","terms":["Centre Le Corbusier","램프","월 판넬","Pilotis","pivot"],"pass1":[{"kind":"say","lines":["사진 네 장이에요. 글자는 없어요.","**르 코르뷔지에 센터(Centre Le Corbusier)** 의 지붕 아래, 그림 판, 벽 그림, 비탈길이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽 위: 큰 강철 지붕 바로 아래의 옥상 마당이에요. 초록 둥근 문이 달린 상자가 있어요.","오른쪽 위: 커다란 흰 판이 문처럼 돌아가 열려 있어요. 검은 선으로 뿔 달린 얼굴이 그려져 있어요.","왼쪽 아래: 빨간 바탕에 검은 선 그림이 가득한 커다란 벽걸이예요.","오른쪽 아래: 난간이 달린 긴 비탈길이 위층으로 올라가요."]},{"kind":"points","head":"p.50 글과 짝지어 보기","items":["오른쪽 아래 비탈길이 '상부층으로 이동하는 길고 돌출된 **램프**' 예요.","왼쪽 위는 건물 전체를 보호하는 강철 지붕의 바로 아래예요.","초록, 빨강, 노랑 판은 **월 판넬** 이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**르 코르뷔지에 센터** 에서 상부층으로 이동하는 길고 돌출된 비탈길은 무엇일까요?","choices":["**램프**","**필로티(Pilotis)**","**의식용 출입문(pivot)**"],"a":0,"why":"램프예요. 필로티는 건물을 기둥으로 들어 올리는 방식, pivot은 롱샹교회의 출입문이에요."},{"kind":"warn","head":"사진 위 손글씨","items":["이 덱의 사진 위 파란, 흰 글씨는 누군가 손으로 적은 필기예요.","슬라이드 원문이 아니어서 시험 답의 근거로 쓰지 않아요."]}],"walk":{"head":null,"parts":[{"b":[0.027,0.054,0.454,0.452],"c":[0.0043,0.0314,0.4994,0.4972],"r":1.3392,"img":"img/U7/walk/p054_22_01.jpg","say":"왼쪽 위: 강철 지붕 아래 옥상 마당이에요."},{"b":[0.506,0.038,0.462,0.461],"c":[0.4829,0.015,0.5082,0.5071],"r":1.3362,"img":"img/U7/walk/p054_22_02.jpg","say":"오른쪽 위: 문처럼 돌아가 열린 흰 그림 판이에요."},{"b":[0.027,0.526,0.453,0.452],"c":[0.0043,0.5028,0.4983,0.4972],"r":1.3363,"img":"img/U7/walk/p054_22_03.jpg","say":"왼쪽 아래: 빨간 바탕의 커다란 벽걸이 그림이에요."},{"b":[0.51,0.52,0.459,0.459],"c":[0.4871,0.4951,0.5049,0.5049],"r":1.3333,"img":"img/U7/walk/p054_22_04.jpg","say":"오른쪽 아래: 원색 판 옆으로 난 긴 비탈길이에요."},{"b":[0.768,0.61,0.2,0.371],"c":[0.756,0.5915,0.224,0.4081],"r":0.7318,"img":"img/U7/walk/p054_22_05.jpg","say":"난간 달린 램프예요. 상부층으로 이어져요."}]}},{"p":55,"title":"강철 틀 전시 상자와 한 팔 든 사람 조각 (글자 없는 슬라이드)","terms":["Centre Le Corbusier","Modulor","machine age"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. **르 코르뷔지에 센터(Centre Le Corbusier)** 의 실내예요.","볼트로 조인 강철 틀 상자와, 한 팔을 든 검은 사람 조각이 있어요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["오른쪽 위: 강철 틀로 짠 네모 상자 같은 방이에요. 틀에 볼트가 줄지어 박혀 있어요.","상자 안 파란 벽에 그림 한 점, 나무 벽에 둥근 사진 한 점이 걸려 있어요.","왼쪽 아래: 큰 유리벽 앞에 검은 사람 모양 판이 서 있어요. 한 팔을 머리 위로 들었어요.","그 옆 판에는 선 그림이 붙어 있어요."]},{"kind":"points","head":"앞 내용과 이어 보기","items":["한 팔 든 사람 모양은 p.5 **모듈러(Modulor)** 그림 속 사람과 닮았어요.","**모듈러(Modulor)** 는 사람 몸 치수에서 뽑은 비례 체계였어요.","강철과 볼트가 그대로 드러난 모습은 p.52의 **기계 시대(machine age)** 를 떠올리게 해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**모듈러(Modulor)** 는 무엇에서 뽑은 비례 체계였나요?","choices":["사람 몸 치수","벽돌 한 장 크기","자동차 크기"],"a":0,"why":"사람 몸 치수에서 뽑은 르 코르뷔지에의 비례 체계예요."}],"walk":{"head":null,"parts":[{"b":[0.413,0.038,0.587,0.586],"c":[0.3543,0.0087,0.6457,0.6446],"r":1.3356,"img":"img/U7/walk/p055_22_01.jpg","say":"오른쪽 위: 강철 틀로 짠 네모 상자 같은 방이에요."},{"b":[0.616,0.205,0.087,0.2],"c":[0.5595,0.189,0.2,0.232],"r":1.1494,"img":"img/U7/walk/p055_22_02.jpg","say":"파란 벽에 걸린 그림 한 점이에요."},{"b":[0.736,0.038,0.04,0.571],"c":[0.6339,0.0094,0.2443,0.6281],"r":0.5186,"img":"img/U7/walk/p055_22_03.jpg","say":"강철 틀 기둥이에요. 볼트가 줄지어 박혀 있어요."},{"b":[0.027,0.457,0.524,0.524],"c":[0.0008,0.4236,0.5764,0.5764],"r":1.3333,"img":"img/U7/walk/p055_22_04.jpg","say":"왼쪽 아래: 큰 유리벽 앞의 실내예요."},{"b":[0.296,0.59,0.061,0.281],"c":[0.2265,0.574,0.2,0.313],"r":0.852,"img":"img/U7/walk/p055_22_05.jpg","say":"한 팔을 든 검은 사람 모양 판이에요."}]}},{"p":56,"title":"르 코르뷔지에, 라 투레트 수도원, 프랑스 이브, 1960","terms":["라 투레트 수도원","Le Corbusier","노출 콘크리트","Pilotis"],"pass1":[{"kind":"say","lines":["단원의 마지막 작품이에요. **라 투레트 수도원**, 프랑스 이브, 1960년이에요.","회색 콘크리트 건물이 비탈진 풀밭 위에 기둥으로 서 있어요.","수도사들이 함께 살며 기도하는 곳이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["수도원: 수도사들이 함께 살며 기도하고 공부하는 곳이에요.","**노출 콘크리트**: 마감재를 덧대지 않고 콘크리트 면을 그대로 드러낸 것이에요.","**필로티(Pilotis)**: 건물을 기둥으로 들어 올려 아래를 비우는 방식이에요."]},{"kind":"points","head":"사진에서 보이는 것","items":["캡션: **르 코르뷔지에(Le Corbusier)**, **라 투레트 수도원**, 프랑스 이브, 1960.","왼쪽 위: 안뜰 쪽이에요. 뾰족한 삼각 덩어리, 풀 덮인 지붕, 긴 통로가 보여요.","왼쪽 아래: 비탈 위에 선 건물이에요. 위 두 층에 작은 칸 창이 촘촘히 줄지어 있어요.","아래층은 가는 기둥들이 건물을 땅에서 들어 올려요. **필로티(Pilotis)** 를 떠올려요.","오른쪽: 기둥과 아치 위에 벽이 떠 있고, 둥근 원통 탑이 붙어 있어요.","벽은 모두 칠하지 않은 회색 콘크리트예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**라 투레트 수도원** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["프랑스 롱샹, 1951","프랑스 이브, 1960","스위스 취리히, 1957"],"a":1,"why":"프랑스 이브, 1960년이에요. 롱샹 1951은 **롱샹교회**, 취리히 1957은 **르 코르뷔지에 센터** 예요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["사진 위 파란 손글씨는 필기예요. 슬라이드 원문이 아니에요.","라 투레트가 앞 작품에서 무엇을 가져왔는지는 다음 쪽 p.57 글에 정확히 적혀 있어요."]}],"walk":{"head":null,"parts":[{"b":[0.054,0.065,0.151,0.033],"c":[0.0295,0.0265,0.2,0.11],"r":2.4242,"img":"img/U7/walk/p056_22_01.jpg","say":"소제목: 라 투레트 수도원."},{"b":[0.019,0.143,0.479,0.31],"c":[0,0.127,0.5269,0.342],"r":2.0542,"img":"img/U7/walk/p056_22_02.jpg","say":"왼쪽 위: 안뜰 쪽이에요. 삼각 덩어리와 긴 통로가 보여요."},{"b":[0.019,0.495,0.479,0.419],"c":[0,0.4741,0.5269,0.4609],"r":1.5243,"img":"img/U7/walk/p056_22_03.jpg","say":"왼쪽 아래: 비탈 위에 기둥으로 선 건물이에요. 위층에 작은 칸 창이 줄지어요."},{"b":[0.515,0.227,0.469,0.586],"c":[0.4841,0.1977,0.5159,0.6446],"r":1.0671,"img":"img/U7/walk/p056_22_04.jpg","say":"오른쪽: 콘크리트 벽과 둥근 원통 탑이에요."},{"b":[0.6,0.59,0.229,0.143],"c":[0.588,0.574,0.253,0.175],"r":1.9276,"img":"img/U7/walk/p056_22_05.jpg","say":"벽 아래의 기둥과 아치예요. 건물이 땅에서 떠 있어요."},{"b":[0.25,0.935,0.396,0.033],"c":[0.2302,0.89,0.4356,0.11],"r":5.28,"img":"img/U7/walk/p056_22_06.jpg","say":"캡션: 르 코르뷔지에, 라 투레트 수도원, 프랑스 이브, 1960."}]}},{"p":57,"title":"라 투레트 수도원: 거친 노출 콘크리트, 질서와 혼돈, 앞 작품의 종합","terms":["라 투레트 수도원","노출 콘크리트","질서와 혼돈","Villa Savoye","Unite d'Habitation","롱샹교회","브루탈리즘"],"pass1":[{"kind":"analogy","head":"종합 선물 세트","scene":"앞에서 하나씩 받은 과자를 한 상자에 모두 담은 선물 세트를 떠올려요.","map":[["선물 상자 하나","**라 투레트 수도원**"],["자연과 맞서는 하얀 상자","**빌라 사보아(Villa Savoye)**"],["작은 집이 줄지은 큰 아파트","**유니테 다비타시옹(Unite d'Habitation)**"],["곧은 각이 없는 교회","**롱샹교회**"]]},{"kind":"say","lines":["다시 말하면 7단원에서 배운 작품들이 한 건물에 모였어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["개구부: 창이나 문처럼 벽에 뚫은 구멍이에요.","**질서와 혼돈**: 반듯한 규칙과 뒤죽박죽이 함께 있어 생기는 팽팽한 느낌이에요.","직교: 두 선이 90도로 만나는 것이에요. 직교하지 않으면 비스듬한 각이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["거친 **노출 콘크리트** 마감이에요.","개구부가 리듬을 가지고 뚫려 있어요(규칙, 불규칙 표기는 아래 '조심할 점').","**질서와 혼돈** 사이의 강한 긴장감이 있어요.","복잡하고 풍부한 형태예요. 아래 네 가지를 앞 작품에서 가져왔어요."]},{"kind":"compare","head":"복잡하고 풍부한 형태: 어디에서 가져왔나","cols":["라 투레트의 부분","가져온 작품, 방식"],"rows":[["자연에 대립하는 방식","**빌라 사보아(Villa Savoye)**"],["수도사실","**유니테 다비타시옹(Unite d'Habitation)**"],["집회실 및 식당","자유로이 개방된 평면"],["직교하지 않는 자유로운 공간","롱샹성당(**롱샹교회**)"]]},{"kind":"points","head":"평면도 범례 (그림 속 글자)","items":["제목: 상층부 및 교회 평면.","A 수도원 입구, B 교회 입구, C 교회, D 주 제단, E 수도사 성가대석, F 성구실.","G 측 제단, H 강당, I 도서실, J 식당, K 수도사실, L 내부 중정.","K 수도사실이 둘레에 촘촘히 줄지어 L 내부 중정을 감싸요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"슬라이드 원본에서 조심할 점","items":["글자층은 '불규칙한 리듬의 개구부' 인데, 그림에는 '규칙적' 이 덧씌워져 '규칙적 리듬의 개구부' 로 보여요.","편집 흔적이라 슬라이드만으로는 어느 쪽인지 알 수 없어요. 두 표기를 모두 알아 둬요.","'유니테 다비티시옹' 은 다비타시옹의 오타예요. '롱샹성당' 은 **롱샹교회** 를 가리켜요."]},{"kind":"bg","src":"p.2 다시 보기","lines":["p.2: 르 코르뷔지에는 거친 마감 콘크리트 사용을 연구한 최초의 건축가예요.","p.2에는 **브루탈리즘** 의 발전도 적혀 있어요. **브루탈리즘** 은 거친 콘크리트를 그대로 드러내는 흐름이에요.","**라 투레트 수도원** 의 거친 **노출 콘크리트** 와 함께 묶어 외워요."]},{"kind":"check","q":"**라 투레트 수도원** 의 수도사실은 어느 작품에서 가져왔을까요?","choices":["**빌라 사보아(Villa Savoye)**","**유니테 다비타시옹(Unite d'Habitation)**","**롱샹교회**"],"a":1,"why":"수도사실 : 유니테 다비타시옹(슬라이드 표기 다비티시옹)이에요."},{"kind":"check","q":"**라 투레트 수도원** 에서 '직교하지 않는 자유로운 공간' 과 짝인 작품은 무엇일까요?","choices":["롱샹성당","빌라 사보아","르 코르뷔지에 센터"],"a":0,"why":"직교하지 않는 자유로운 공간 : 롱샹성당이에요. 자연에 대립하는 방식이 빌라 사보아예요."},{"kind":"english","head":"논술 답안: 라 투레트 수도원","en":"라 투레트 수도원(프랑스 이브, 1960)은 거친 노출 콘크리트 마감과 질서와 혼돈 사이의 강한 긴장감을 지니며, 빌라 사보아, 유니테 다비타시옹, 롱샹성당의 방식을 종합하였다.","ko":"마감, 긴장감, 종합(사보아, 유니테, 롱샹) 순서예요. 식당은 자유로이 개방된 평면이에요.","tip":"'자연 맞서기 사보아, 방은 유니테, 비스듬은 롱샹' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.066,0.048,0.413,0.421],"c":[0.0453,0.027,0.4543,0.4631],"r":1.308,"img":"img/U7/walk/p057_24_01.jpg","say":"사진: 비탈에 기둥으로 선 수도원이에요. 위 두 층에 작은 칸이 줄지어요."},{"b":[0.043,0.505,0.286,0.043],"c":[0.0287,0.4715,0.3146,0.11],"r":3.8133,"img":"img/U7/walk/p057_24_02.jpg","say":"거친 노출 콘크리트 마감."},{"b":[0.043,0.564,0.271,0.046],"c":[0.0294,0.532,0.2981,0.11],"r":3.6133,"img":"img/U7/walk/p057_24_03.jpg","say":"리듬의 개구부. 그림에는 '규칙적' 이 덧씌워져 있어요."},{"b":[0.043,0.624,0.357,0.046],"c":[0.0251,0.592,0.3927,0.11],"r":4.76,"img":"img/U7/walk/p057_24_04.jpg","say":"질서와 혼돈 사이의 강한 긴장감."},{"b":[0.043,0.686,0.443,0.276],"c":[0.0209,0.67,0.4873,0.308],"r":2.1095,"img":"img/U7/walk/p057_24_05.jpg","say":"복잡하고 풍부한 형태와 네 가지 출처예요."},{"b":[0.509,0.314,0.47,0.61],"c":[0.483,0.2835,0.517,0.671],"r":1.0273,"img":"img/U7/walk/p057_24_06.jpg","say":"상층부 및 교회 평면과 범례 A부터 L까지예요."}]}},{"p":58,"title":"라 투레트 수도원의 안팎 (글자 없는 슬라이드)","terms":["라 투레트 수도원","노출 콘크리트","롱샹교회","Le Corbusier","internationale Architektur"],"pass1":[{"kind":"say","lines":["7단원의 마지막 슬라이드예요. 글자 없이 사진 네 장이에요.","앞 쪽에 이어 **라 투레트 수도원** 의 안팎이에요."]},{"kind":"recap","items":["7단원 **르 코르뷔지에(Le Corbusier)** 를 한 줄로","p.2: **국제주의 건축(internationale Architektur)** 의 제 1세대예요.","1920년대 흰 주택에서, 2차 세계대전 이후 곡면과 거친 **노출 콘크리트** 로 갔어요.","롱샹교회 1951, 르 코르뷔지에 센터 1957, 라 투레트 수도원 1960 순서예요.","주문도 한 번 더. 기계 시대에 건축은 어떻게 생겨야 하나?"]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽 위: 콘크리트 벽 사이 창에 빨강, 초록, 노랑 색 판이 끼워져 있어요.","그 아래에 세모난 콘크리트 덩어리가 줄지어 튀어나와 있어요.","왼쪽 아래: 둥근 기둥이 선 긴 방에 나무 탁자와 의자가 줄지어 있어요. 초록, 빨강 커튼이 걸려 있어요.","오른쪽 위: 파란 천장에 둥근 구멍 세 개가 뚫려 있어요. 아래 벽은 노랗게 칠했어요.","오른쪽 아래: 어둡고 높은 콘크리트 방에 긴 나무 의자가 줄지어 있어요. 가는 틈 창으로 노랑, 빨강, 초록 빛이 들어와요."]},{"kind":"points","head":"p.57 글과 짝지어 보기","items":["콘크리트 벽에 가로 줄무늬 자국이 그대로 남아 있어요. 거친 **노출 콘크리트** 마감이에요.","탁자가 놓인 넓은 방은 p.57의 '집회실 및 식당 : 자유로이 개방된 평면' 과 함께 떠올려요.","회색 콘크리트 안에 원색 빛을 들인 모습은 **롱샹교회** 의 색유리 창과도 닮았어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"7단원 후기 작품을 연도 순서로 바르게 놓은 것은 무엇일까요?","choices":["롱샹교회 → 르 코르뷔지에 센터 → 라 투레트 수도원","라 투레트 수도원 → 롱샹교회 → 르 코르뷔지에 센터","르 코르뷔지에 센터 → 라 투레트 수도원 → 롱샹교회"],"a":0,"why":"1951 → 1957 → 1960 이에요."},{"kind":"check","q":"p.2에서 **르 코르뷔지에(Le Corbusier)** 를 무엇의 제 1세대라고 했나요?","choices":["**국제주의 건축(internationale Architektur)**","**표현주의(Expressionism)**","미술공예운동"],"a":0,"why":"국제주의 건축의 제 1세대예요. 표현주의는 기능주의와 '결합' 했다고 했어요."},{"kind":"english","head":"논술 답안: 2차 세계대전 이후의 르 코르뷔지에","en":"르 코르뷔지에는 노트르담 뒤 오 교회(롱샹, 1951), 르 코르뷔지에 센터(취리히, 1957), 라 투레트 수도원(이브, 1960)을 설계하였다.","ko":"작품, 도시, 연도 짝 세 개를 순서대로 써요.","tip":"'오일(51) 롱샹, 오칠(57) 취리히, 육공(60) 이브' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.035,0.038,0.39,0.349],"c":[0.0155,0.0206,0.429,0.3839],"r":1.49,"img":"img/U7/walk/p058_22_01.jpg","say":"왼쪽 위: 창의 원색 판과 줄지어 튀어나온 세모 콘크리트 덩어리예요."},{"b":[0.035,0.426,0.392,0.357],"c":[0.0154,0.4082,0.4312,0.3927],"r":1.4641,"img":"img/U7/walk/p058_22_02.jpg","say":"왼쪽 아래: 둥근 기둥이 선 긴 방에 탁자와 의자가 줄지어 있어요."},{"b":[0.46,0.08,0.521,0.447],"c":[0.4269,0.0576,0.5731,0.4917],"r":1.5541,"img":"img/U7/walk/p058_22_03.jpg","say":"오른쪽 위: 파란 천장과 노란 벽, 거친 콘크리트 벽이에요."},{"b":[0.511,0.105,0.382,0.162],"c":[0.4919,0.089,0.4202,0.194],"r":2.888,"img":"img/U7/walk/p058_22_04.jpg","say":"천장의 둥근 구멍 세 개예요. 빛이 들어오는 곳이에요."},{"b":[0.464,0.563,0.521,0.405],"c":[0.4269,0.5427,0.5731,0.4455],"r":1.7152,"img":"img/U7/walk/p058_22_05.jpg","say":"오른쪽 아래: 어두운 콘크리트 방, 긴 의자, 가는 색빛 틈 창이에요."}]}}]};
